-- Falas de Pokemon Gold em portugues brasileiro.
-- Chave = ponteiro da ROM USA, no formato que o gen1recomp usa.
-- Vazio ou ausente = cai em ingles.
return {
  ["00:2815"] = "Ação objeto.",
  ["40:4615"] = "Bom dia!\nBem-vindo ao\vCENTRO POKéMON!",
  ["40:4640"] = "Oi! Seja bem\nvindo ao CENTRO\vPOKéMON.",
  ["40:4664"] = "Boa Noite!\nVocê chegou tarde.\fBem-vindo ao\nCENTRO POKéMON!",
  ["40:469f"] = "Podemos curar\ntotalmente o\vseu POKéMON.    \fEu posso curar\nseu POKéMON?",
  ["40:46e2"] = "Me entregue seus\nPOKéMONS!",
  ["40:46fc"] = "Obrigado por\nesperar. \fSeus POKéMONS\nestão curados!",
  ["40:4730"] = "Esperamos vê-lo\nde novo.",
  ["40:4766"] = "Seus POKéMONS\nparecem ter\vmicroorganismos\vgrudados neles.\fSeus POKéMONS\nestão saudáveis e\vparecem estar bem.\fMas não podemos\ndizer mais nada\vno CENTRO POKéMON.",
  ["40:4801"] = "Lotado de livros\ndifíceis.",
  ["40:484a"] = "REVISTAS POKéMON…\nJOGOS DE POKéMONS…\fMANUAIS POKéMON…\nGRÁFICO POKéMON…",
  ["40:48ef"] = "O que é isso?\fOh, é um porta\nincensos!",
  ["40:4934"] = "Este é o MAPA.",
  ["40:4965"] = "É uma Televisão.",
  ["40:49cd"] = "Não há nada aqui…",
  ["40:4a43"] = "Tudo que o POKéMON\nprecisa!\fLOJA POKéMON.",
  ["40:4a66"] = "Agora julgaremos\no POKéMON que você\vcapturou.\f…\n…\fEscolhemos os\nvencedores!\fVocês estão\npreparados?",
  ["40:4ac8"] = "Uau! Que celular\nbonito.\fMe dê o seu\nnúmero do celular?\fTe ligo para uma\nrevanche!",
  ["40:4b39"] = "{PLAYER} guardou\nnúmero de {STRBUF}.",
  ["40:4b7a"] = "Certo…\nÉ so falar de\vnovo comigo se\vquiser o meu\vtelefone.",
  ["40:4bef"] = "Eu o aguardava.\nVamos batalhar!",
  ["40:4c77"] = "Anotar número de\nCELULAR?",
  ["40:4cb0"] = "Te ligarei se\nocorrer algo.",
  ["40:4d12"] = "Seu telefone não\ntem memória,\vpara pôr mais\vnúmeros!",
  ["40:4d6a"] = "{PLAYER} ganha o\n{STRBUF}º prêmio, o(a)\v{STRBUF}!",
  ["40:4d90"] = "{PLAYER} recebeu\n{STRBUF}.",
  ["40:4da3"] = "Compareçam no\npróximo Concurso!",
  ["40:4dc9"] = "Todos ganham um\nGRÃO como prêmio\vde consolação!",
  ["40:4dff"] = "Esperamos melhoras\nna próxima.",
  ["40:4e21"] = "Devolveremos seus\nPOKéMONS que\vguardamos.\fAqui estão!",
  ["40:4e55"] = "Sua equipe está\ncheia.\fO POKéMON foi para\nseu BOX no PC DO\vBILL.",
  ["40:4e96"] = "{STRBUF}\nGINÁSIO POKéMON",
  ["40:5014"] = "Oh? Sua BOLSA está\ncheia.\fNós guardaremos\nisso hoje, então\vvolte quando\vliberar espaço.",
  ["42:40dc"] = "Só quem chega ao\ntopo é que ganha\vum HM.",
  ["42:410e"] = "A SPROUT TOWER foi\nerguida há muito\fcomo lugar de\ntreino POKéMON.",
  ["42:414d"] = "Um BELLSPROUT de\nmais de 30 metros\fDizem que ele\nvirou o pilar\vcentral daqui.",
  ["42:41a1"] = "Viu o pilar\ntremendo?\fEstão treinando\nlá em cima.",
  ["42:41da"] = "Estátua POKéMON…\fParece muito\nimponente.",
  ["42:43cc"] = "Uma estátua\nPOKéMON…\fEla parece ser\nmuito famosa…",
  ["42:452b"] = "LÍDER: Sem dúvida\nvocê é um ótimo\vtreinador.\fComo prometi, aqui\nestá o HM.\fMas quero avisar\nlhe:\fVocê deve tratar\nmelhor seus\vPOKéMONS. \fSeu estilo de luta\né inadequado.\fOs POKéMONS não\nsão armas de\vguerra…",
  ["42:45f0"] = "…\n…Bah! Ele diz ser\vo LÍDER mas ele\vé bem fraco. \fÉ muito\ncertinho.\fNunca perderei\npara bobos que\fficam sendo legais\ncom os POKéMONS.\fSó ligo para\nPOKéMONS fortes\vque podem vencer.\fEu não me\nimportaria com\vPOKéMONS fracos.",
  ["42:46cc"] = "{RIVAL} usou\nCORDADEFUGA!",
  ["42:46e4"] = "Fico feliz por\nvocê chegar aqui!\fA TORRE BROTINHO\né um lugar de\vtreino.\fPessoas e POKéMONS\nse testam aqui\vpara fazerem\vjuntos um bom\vfuturo.\fSou o teste final.\fDeixe-me checar\nos laços entre\vvocê e os seus\vPOKéMONS!",
  ["42:47b6"] = "Ah, brilhante!",
  ["42:47c6"] = "Você e seus\nPOKéMONS não terão\vproblemas ao\vusarem esse golpe.\fPegue esse HM\nLUZES.",
  ["42:4817"] = "LUZES ilumina até\nos lugares mais \vescuros.\fMas para usá-lo\nfora de batalhas,\vvocê precisa da\vINSÍGNIA DA BRISA.",
  ["42:488c"] = "Espero que aprenda\ne cresça na sua\vjornada.",
  ["42:4a38"] = "É uma poderosa\npintura de um\vBELLSPROUT.",
  ["42:4a62"] = "Uma estátua\nPOKéMON…\fEla parece ser\nmuito famosa…",
  ["42:4b20"] = "Estou tentando\nencobrir o segredo\vdo lendário\vPOKéMON que\vaparenta estar\vaqui.\fDizem que o\nPOKéMON voa\vcontinuamente\vdesde quando a\vTORRE do oeste foi\vincendiada.\fEntão, eu pensei\nque se eu tivesse\vo que o POKéMON\vtem, ele seria\vatraído por esse\vitem.\fEu acho que\nesse item é\vprovavelmente…\fA ASA ARCO ÍRIS!\fMas, onde eu\npoderia achar\vuma?",
  ["42:4f24"] = "……………\f…Oh, é você.\fVocê queria ficar\nbem forte, então \vveio em busca do\vPOKéMON lendário\vque supostamente\vestá aqui.\fEsta é sua\nhistória, né?\fBem, isso não vai\nacontecer.\fPorque eu vou\npegá-los!\fEu serei o melhor\ntreinador do\vmundo, então um\vPOKéMON lendário\vseria perfeito\vpara mim.\f…Bem, de qualquer\nmaneira, estou\vficando cansado de\vter um bobão como\vvocê sempre\vaparecendo.",
  ["42:5093"] = "…Humph!\fPor isso eu odeio\nbatalhar com\vbobos.\fNão há desafio\nnisto.",
  ["42:50da"] = "…Aw, por mais que\nvocê tente, nunca\vpegará um POKéMON\vlendário.",
  ["42:5124"] = "…Humph!\fPoro isso odeio\nbatalhar com\vbobos.\fÉ jogar meu tempo\nfora.",
  ["42:516d"] = "Ei, estou\ntreinando\vsecretamente\vaqui!\fNão me embarasse\npelo olhar!",
  ["42:51ac"] = "Queimei até\nvirar cinzas…",
  ["42:51cb"] = "Me empolguei tanto\nno treinamento que\vcaí nesse buraco.",
  ["42:552a"] = "Um bando de\nDIGLETTS saíram do\vchão!\fIsto foi chocante.",
  ["42:562d"] = "… … …\fJá faz tempo,\n{PLAYER}.\f…Desde que perdi\npara você, pensei\vcomo era carente\vcom os meus\vPOKéMONS…\fE temos uma\nresposta para lhe\vdar.\fVamos lhe mostrar,\n{PLAYER}!",
  ["42:56c5"] = "… … …\fPensei que treinei\nmeu POKéMON para\vele poder fazer\vo melhor…\f…Mas não foi\no suficiente…",
  ["42:5722"] = "… … …\f…Você venceu\njusto e limpo.\fEu admito.\nMas isto não\vacabou.\fEu sempre vou ser\no maior treinador\vPOKéMON.\fPorque estes caras\nestão atrás de\vmim.   \f…Escute,\n{PLAYER}.\fUm dia deste vou\nlhe mostrar o\vquanto sou bom\vconseguindo\vvencer-lhe.",
  ["42:5808"] = "… … …\fReembolsei minha\ndívida contigo.\fCom meu POKéMON,\nvou ganhar do\vCAMPEÃO e me\vtornarei o melhor\vtreinador POKéMON\vdo mundo.",
  ["42:5a87"] = "Espere.\f…Você está indo\nencarar o desafio\vda LIGA POKéMON?\f…Não me faça rir.\fVocê é bem mais\nfraco que eu.\fEu não sou mais\ncomo antes.\fAgora eu tenho os\nmelhores e mais\vfortes POKéMONS\vcomigo.\fEstou invencível!\f{PLAYER}! Eu\ndesafio você!",
  ["42:5b65"] = "…Não pude vencer…\fEu dei tudo o que\ntinha…\fO que você tem\nque eu não tenho…\fEstou começando\na entender o que o\vmestre de dragões\vme disse…",
  ["42:5bf6"] = "…Eu não desisti de\nme tornar o melhor\vtreinador…\fEu descobrirei\npor que eu não\vposso ganhar e ser\vforte…\fQuando acabar,\neu desafiarei\vvocê.\fE eu vencerei você\ncom todo o meu\vpoder.\f…Humph! Você\nestará o mesmo até\vlá.",
  ["42:5cd2"] = "…Humph!\fQuando se trata\ndisso, nada supera\vo poder.\fEu não preciso de\nmais ninguém.",
  ["42:8b49"] = "i.",
  ["42:a000"] = "oga! Eu tenho\nPOKéMONS inúteis!",
  ["42:e248"] = " vou dividir\nessa PEDRA DO REI\vcom você.",
  ["42:e342"] = "dor de OLIVINE.\fO FAROL foi\nconstruído em\vhomenagem a estes\vPOKéMONS.",
  ["42:e700"] = "s.\fE você é?",
  ["43:4196"] = "Olhe! Olhe minha\nmala!\fEu imprimi meus\nfavoritos da\vPOKéDEX e os\vprendi na minha\vmala.",
  ["43:41f1"] = "Eu recebi essa\nCARTA da minha\vfilha. Eu fiquei\vfeliz.",
  ["43:4228"] = "Preste atenção!\f…Opa, tenho que\nparar de pensar\vcomo professores\vo tempo todo.\fVocê deve ser um\ntreinador POKéMON.\fComo está\ntrabalhando duro,\veu quero que você\vleve isso.",
  ["43:4320"] = "Estou brincando\ncom figuras\vque imprimi na\vPOKéDEX.",
  ["43:4352"] = "Se eu vencer,\npegarei as figuras\vdo garoto.",
  ["43:437f"] = "Eu caminho no\nPARQUE, mas eu\vnunca vou à\vgrama.  \fOs treinadores\nsempre querem\vbatalhar…",
  ["43:43ed"] = "Estou imprimindo\nminha POKéDEX.\fVocê pode imprimir\nCARTAS e BOXES do\vcomputador.",
  ["43:46e4"] = "PRAÇA DO DESCANSO\nPARQUE NACIONAL.",
  ["43:4705"] = "O que é esse\naviso?\fFavor só batalhar\nna grama.\fPARQUE NACIONAL\nESCRITÓRIO DO\vCHEFE.",
  ["43:4745"] = "Talvez não possa\nvencê-lo em\vbatalhas.\fMas eu sou mais\nlegal.",
  ["43:475a"] = "DICAS DO TREINADOR\fImprima uma CARTA\vabrindo-a e\vapertanto START.",
  ["43:48e0"] = "DON: Eu vou\nvencer! Não me\vatrapalhe.",
  ["43:4907"] = "ED: Com ESPOROS,\nmeu PARASECT faz\vPOKéMONS dormirem.",
  ["43:4937"] = "NICK: Treino\nrápido POKéMONS\vpara batalharem.",
  ["43:4960"] = "WILSON: Não me\ninteresso em\vvencer.\fEu apenas procuro\npor POKéMONS\vraros.",
  ["43:49a9"] = "BENNY: Ssh! Você\nvai espantar o\vSCYTHER.\fTe vejo depois.",
  ["43:49e6"] = "BARRY: Canse os\nPOKéMONS insetos\vantes de jogar uma\vPOKé BOLA.",
  ["43:4a25"] = "CINDY: O que foi?\fAchou engraçado\nver meninas\vcapturando os\vPOKéMON insetos?",
  ["43:4a70"] = "JOSH: Eu coleciono\nPOKéMONS insetos\vdesde quando eu\vera um bebê.\fNão há maneiras de\neu perder!",
  ["43:4acd"] = "SAMUEL: Se tiver\ntempo disponível,\vvá procurar\vPOKéMONS insetos.",
  ["43:4b0c"] = "KIPP: Eu estudei\nmuito os POKéMONS\vinsetos.\fCom certeza eu\nvencerei.",
  ["43:4b4f"] = "PRAÇA DO DESCANSO\nPARQUE NACIONAL.",
  ["43:4b70"] = "O que é esse\naviso?\fFavor só batalhar\nna grama.\fPARQUE NACIONAL\nESCRITÓRIO DO\vCHEFE.",
  ["43:4bc5"] = "DICAS DO TREINADOR\nImprima uma CARTA\vabrindo-a e\vapertando START.",
  ["43:4e1f"] = "Bem-vindo!",
  ["43:4e29"] = "Olá. Perdão, mas\nnão sortearemos\vnenhuma viagem\vhoje.",
  ["43:4e62"] = "Oi, está aqui pelo\nSHOW DO NUMERO DA\vSORTE?\fQuer que\neu olhe os números\vde IDENTIFICAÇÃO\vdos seus POKéMONS?\fSe tiver sorte,\nvocê ganhará um\vprêmio.",
  ["43:4ee2"] = "O número de\nIDENTIFICAÇÃO\vdessa semana é\v{STRBUF}.",
  ["43:4f02"] = "Deixe-me ver se\nvocê ganhou.",
  ["43:4f21"] = "…\n…",
  ["43:4f26"] = "Volte na próxima\nsemana para o\vNUMERO DA SORTE.",
  ["43:4f5d"] = "Uau! Você acertou\ntodos os cinco\vnúmeros!\fNos temos um\ngrande\nvencedor!\fVocê ganhou uma\nMASTER BOLA!",
  ["43:4fcb"] = "Ei! Você acertou\nos últimos três\vnúmeros!\fVocê ganhou o\vsegundo prêmio, o\vDIVIDE EXP.!",
  ["43:501e"] = "Oh, você acertou\nos dois últimos\vnúmeros.\fVocê ganhou o\nterceiro prêmio, o\vPP MAIS.",
  ["43:5068"] = "Você não acertou\nnúmero algum.",
  ["43:508e"] = "Você não tem lugar\npara o prêmio.\fLibere espaço e\nvolte em seguida.",
  ["43:50d5"] = "Nós temos\num concurso\vde perguntas\vfuncionando.\fAcerte cinco\nperguntas para\vreceber um CARTÃO\vDE RÁDIO.\fColoque-o na sua\nPOKéGEAR para\vescutar rádio a\vqualquer hora ou\vlugar.\fVocê deseja\nparticipar?",
  ["43:519a"] = "Pergunta 1:\fO MAPA pode ser\nmostrado na\vPOKéGEAR?",
  ["43:51d1"] = "Correto!\nPergunta 2:\fA NIDORINA só pode\nser fêmea?",
  ["43:5204"] = "Na mosca!\nPergunta 3:\fKURT, o homem das\nPOKé BOLAS, usa\vTRUTAS?",
  ["43:524d"] = "Muito bem!\nPergunta 4:\fMAGIKARP não\naprenderá nenhum\vgolpe TM?",
  ["43:528b"] = "Uau!\nCerto novamente!\vVamos para a\vpergunta final:\fO programa de\nrádio do PROFESSOR\vCARVALHO é muito\vfamoso.\fMARIE é a DJ do\nprograma?",
  ["43:530b"] = "Legal! Conseguiu!\nParabéns!    \fAqui está o seu\nprêmio, o CARTÃO\vDE RÁDIO!",
  ["43:5350"] = "A POKéGEAR de\n{PLAYER} pode ser\vum rádio agora!",
  ["43:5375"] = "Sintonize na nossa\nprogramação.",
  ["43:5399"] = "Desculpe-me, mas\nvoce errou.\fTente de novo!",
  ["43:53d3"] = "Ah, entendo. Tente\nse você mudar de\vidéia.",
  ["43:5403"] = "BEN é um ótimo DJ.\fSua doce voz me\nderrete!",
  ["43:5439"] = "Eu amo MARY, do\nSHOW POKéMON.\fEmbora eu saiba\napenas o que ela\vpareça gostar.",
  ["43:5574"] = "1º ANDAR-RECEPÇÃO\n2º-LOJAS\f3º-FUNCIONÁRIOS\n4º-PRODUÇÃO\f5º-ESCRITÓRIO DO\nDIRETOR.",
  ["43:55be"] = "CANAL DA SORTE!\fGanhe com o número\ndos POKéMONS!\fTroque seus\nPOKéMONS e\vcolecione números\vdiferentes!",
  ["43:570e"] = "Pode escutar ao\nrádio de todo\vlugar. Sintonize!",
  ["43:5740"] = "As canções do\nrádio podem fazer\vPOKéMONS dormirem.",
  ["43:576d"] = "Por que eles\nqueriam dominar a\vTORRE DE RÁDIO?",
  ["43:57b5"] = "Perdão. Só pessoas\nautorizadas podem\vpassar daqui.\fNão era assim\nantes.\fTem algo de errado\ncom o DIRETOR…",
  ["43:582e"] = "Você pode ir a\nqualquer lugar\vaqui dentro.\fO DIRETOR está bem\nde novo, como era\vantes.",
  ["43:5ade"] = "2º ANDAR-LOJAS",
  ["43:5ae8"] = "SHOW DO CARVALHO\fO Show Mais Quente\nno ar.",
  ["43:5b1b"] = "Qualquer lugar,\nhora!\fRÁDIO POKéMON.",
  ["43:5cbf"] = "Temos gravações\ndos sons de todos\vos POKéMONS que\vforam achados.\fDevemos ter uns\n200 tipos.",
  ["43:5d20"] = "Os POKéMONS, para\nos treinadores,\vsão seus amáveis\vparceiros.\fÉ terrível como a\nEQUIPE ROCKET\vtenta controlar os\vPOKéMONS.",
  ["43:5d89"] = "Funcionamos 24\nhoras por dia para\vtransmitir bons\vprogramas.\fFarei o meu melhor\npara correr contra\vo tempo!",
  ["43:5df2"] = "O chefe da EQUIPE\nROCKET se trancou.\fMas o DIRETOR\npode abrir a\vporta.\fEle está no quinto\nandar.\fPor favor,\nsalve-o!",
  ["43:5e69"] = "O DIRETOR está\nsalvo?",
  ["43:5e80"] = "Obrigado!\nVocê é meu herói!\fIsso é um presente\nmeu para você.",
  ["43:5ebf"] = "É o DIA DE SOL.\nIsso ajuda ataques\vde fogo por um\vtempo.",
  ["43:5efa"] = "Agiu de maneira\nexcelente!",
  ["43:6060"] = "\vPOKéMONS dormirem.",
  ["43:6100"] = "ha…\fSe precisar, posso\ntransmitir sinais\vfortes daqui.",
  ["43:6142"] = "É o encaixe para\no CARTÃO.",
  ["43:615a"] = "{PLAYER} colocou\no CARTÃO.",
  ["43:6174"] = "3º ANDAR-\nFUNCIONÁRIOS.",
  ["43:6182"] = "M→SICA POKéMON\ncom o DJ BEN.",
  ["43:62b0"] = "Eu escutei ao\nrádio enquanto\vestava nas RUÍNAS.\fEu ouvi um\nprograma estranho\vlá.",
  ["43:6306"] = "MARY: Por quê?\nPor que tenho que\vpassar por isso?\fMEOWTH, ajude-me!",
  ["43:6349"] = "MARY: Oh! Você é\nmeu pequeno herói!\fLevará isso como\nagradecimento?",
  ["43:638d"] = "MARY: É muito bom\npara POKéMONS que\vsabem golpes do\vtipo normal.",
  ["43:63ca"] = "MARY: Sintonize-se\nem mim no SHOW\vDO PROFESSOR\vCARVALHO.",
  ["43:6600"] = "Excelente.\fEssa TORRE DE\nRÁDIO preencherá\vnosso grande\vprojeto.",
  ["43:665f"] = "Eu não acho que\nPOKéMONS são\vbonitos?\fAcharei meus\nPOKéMONS bonitos\vdepois de vencerem\vos seus!",
  ["43:669c"] = "4º ANDAR-PRODUÇÃO.",
  ["43:66ab"] = "4º ANDAR-\nESTUDIO 2.",
  ["43:686a"] = "V-você veio me\nresgatar aqui?",
  ["43:6889"] = "Era isso o que\nestava esperando?\fErrado!\nSou um impostor!\fPretendo ser o\nverdadeiro para\veu tomar posse\vdaqui.\fDeseja saber onde\no verdadeiro\vDIRETOR está?\fClaro, eu te\ncontarei.\fMas só se você me\nderrotar!",
  ["43:6965"] = "Certo. Vou lhe\ncontar onde ele\vestá.",
  ["43:6988"] = "Nós colocamos\no verdadeiro\vDIRETOR no\vSUBTERRÂREO, no\vDEPÓSITO.\fEstá no final\ndo SUBTERRÂNEO.\fMas duvido que\nvocê chegue lá.",
  ["43:6a59"] = " não.",
  ["43:6b23"] = "Oh? Você conseguiu\nchegar aqui?\fVocê deve ser um\nótimo treinador.\fPretendemos\ndominar essa\vESTAÇÃO DE RÁDIO\ve anunciar nosso\vretorno.\fIsso deve trazer\nnosso chefe\vGIOVANNI de volta\vdo seu treinamento\vsolo.\fVamos recuperar\nnossa glória\vanterior.\fNão permitirei\nvocê de interferir\vnossos planos.",
  ["43:6c45"] = "Não! Perdoe-me,\nGIOVANNI!",
  ["43:6c60"] = "Como pode ser?\fNossos sonhos\nserão destruídos.\fEu não era o\ncerto para a\vtarefa.\fComo GIOVANNI fez\nantes, eu vou\vfinalizar a EQUIPE\vROCKET hoje.\fAté outro dia.",
  ["43:6d04"] = "DIRETOR: {PLAYER},\nobrigado!\fSuas ações\ncorajosas salvaram\vtoda a nação\vPOKéMON.\fEu sei que não é\nmuito, mas leve\visso aqui.",
  ["43:6d7e"] = "Isso era uma torre\nna CIDADE\vGOLDENROD.\fMas ela estava\nmuito velha e\vacabada.\fEntão nós a\nsubstituímos pela\vnossa TORRE DE\vRÁDIO.\fDurante a\ndemolição, nós\vencontramos algo\vno topo.\fDisseram que\num POKéMON gigante\vsobrevoava por\vGOLDENROD no\vpassado.\fTalvez aquele\nPOKéMON caiu.\fEle devia ser como\naquele que aparece\vna TORRE ESTRANHA\vna CIDADE\vECRUTEAK.\fBom, é melhor eu\nir ao meu\vESCRITÓRIO.",
  ["43:6ee3"] = "Isso era uma torre\naqui na CIDADE\vGOLDENROD.\fMas ela\nestava velha e\vdesgastada.\fEntão substituímos\npela TORRE DE\vRÁDIO.\fDurante a\ndemolição, nós\vachamos algo no\vtopo.\fDisseram que um\nPOKéMON gigante\vsobrevoava por\vGOLDENROD no\vpassado.\fTalvez aquele\nPOKéMON caiu.\fEle devia ser como\naquele que aparece\vnas ILHAS\vRODOPIO perto de\vCIANWOOD.\fÉ melhor eu ir ao\nmeu ESCRITÓRIO.",
  ["43:7049"] = "DIRETOR: Olá,\n{PLAYER}!\fVocê sabe, eu amo\nPOKéMONS.\fEu construí essa\nTORRE DE RÁDIO\vpara eu expressar\vo meu amor.\fSeria bom se as\npessoas gostassem\vdos programas\vapresentados na\vnossa RÁDIO.",
  ["43:706a"] = "uê?!",
  ["43:70e3"] = "BEN: Você escuta\nà nossa música?",
  ["43:7105"] = "5º ANDAR-\nESCRITÓRIO DO\vDIRETOR.",
  ["43:711e"] = "5º ANDAR-\nESTUDIO 1.",
  ["43:8900"] = "o\vtumbas de reis.\fComo as pirâmides,\npor exemplo.",
  ["43:8e00"] = "nhos nas\vRUÍNAS?\fEles se parecem\nmuito com aqueles\vdesenhos das\vparedes de lá.\fHum…Isso deve\nsignificar que\vexistem muitos\vtipos deles…",
  ["43:9346"] = "LUZES!",
  ["43:9d00"] = "descontar toda\vminha raiva em\vvocê!",
  ["43:a200"] = "quipado com a\vPEDRA DO REI é\vmuitas vezes\vmordido por um\vSHELLDER.\fEi, eu vou dividir\nessa PEDRA DO REI\vcom você.",
  ["43:a744"] = "IVINE, \veu vou ao GINÁSIO.\fO tipo de POKéMON\nda LÍDER DO\vGINÁSIO mudou e\veu nem havia\vpercebido.",
  ["43:a95a"] = "IA\vem CIANWOOD.",
  ["43:d200"] = "\vneste lugar agora.\fTemos planos\nmaiores.\fEm breve\nvocê apreciará o\vverdadeiro poder\vda EQUIPE ROCKET.\fDivirta-se\nenquanto puder…\fHahahaha…",
  ["43:d25f"] = ",\vvocê poderia ser\vEXECUTIVO.",
  ["43:d759"] = " para se\ntornar um MESTRE\vPOKéMON é longa e\vdifícil.\fSabendo disso,\nvocê pretende\vcontinuar?\f…\fEntendo. Não, você\ntem razão.\fSe desistisse\nfacilmente, você\vnunca teria\vseguido o sonho do\vprimeiro lugar.\fEu espero vê-lo\nnovamente!",
  ["43:e600"] = "…\fEssa idéia me\nentusiasma!",
  ["44:409f"] = "Hã? Isso é uma\nPOKéDEX, não é?\vPosso vê-la?\fExistem muitos\ntipos de POKéMONS.\fHã? O que é isso?\nQue POKéMON é\vesse?\fSe parece com os\nestranhos desenhos\vdas paredes das\vRUÍNAS. \fSe aqueles\ndesenhos são\vmesmo POKéMONS,\ventão devem haver\vmuito mais.   \fJá sei! Deixe-me\natualizar a sua\vPOKéDEX. Siga-me.",
  ["44:42fd"] = "PEDRA DO MISTÉRIO\nSALÃO DOS PAINÉIS.",
  ["44:431a"] = "RUÍNAS ALFA\fBem-vindo\nTuristas.",
  ["44:433a"] = "RUÍNAS ALFA\nCENTRO DE PESQUISA\fA autoridade sobre\nas RUÍNAS ALFA.",
  ["44:443c"] = "É uma réplica de\num POKéMON ancião.",
  ["44:4461"] = "Um POKéMON que\nvoava com suas\vasas com cores do\varco-íris.",
  ["44:4516"] = "Bem-vindo a esse\nsalão.\fAqui há painéis\nmóveis feitos\vpor anciões que\vformam o desenho\vde um POKéMON.\fMova o painel para\nformar uma figura.\fAo lado direito,\nhá a descrição\vdesse POKéMON.",
  ["44:4553"] = "m POKéMON.\fMova o painel para\nformar uma figura.\fAo lado direito,\nhá a descrição\vdesse POKéMON.",
  ["44:45cb"] = "É uma réplica de\num POKéMON ancião.",
  ["44:45f0"] = "Um POKéMON que se\nesconde no chão.\fSeus olhos nas\ncostas checam o\vlocal.",
  ["44:46bb"] = "É uma réplica de\num POKéMON ancião.",
  ["44:46e0"] = "Esse POKéMON\nflutuava no mar\vbatendo seus dez\vtentáculos.",
  ["44:4795"] = "É uma réplica de\num POKéMON ancião.",
  ["44:47ba"] = "Esse POKéMON\nvoador atacavasuas\vvítimas com presas\vtipo serras.",
  ["44:484a"] = "Há uma estranha\npresença aqui…",
  ["44:486d"] = "Essa é uma\ngrande sala, mas\vnada há aqui.",
  ["44:489b"] = "Esse lugar tem\num estilo muito\vmístico.\fUma espécie de\nforça oculta.",
  ["44:48e5"] = "Lugares atigos\nàs vezes são\vtumbas de reis.\fComo as pirâmides,\npor exemplo.",
  ["44:4900"] = "o\vtumbas de reis.\fComo as pirâmides,\npor exemplo.",
  ["44:4933"] = "É uma réplica de\num POKéMON ancião.",
  ["44:4b1e"] = "Pronto! Atualizei\nsua POKéDEX.\fAdicionei uma\nPOKéDEX opcional\vpara os UNOWNS.\fEla os grava na\nordem em que você\vos capturou.",
  ["44:4bb7"] = "O UNOWN que\ncapturar será\vgravado.\fCheque para saber\nquantos tipos\vexistem.",
  ["44:4c05"] = "Você capturou\ntodas formas de\vUNOWNS?\fQue ótima\ndescoberta!\fEu ajeitei a\nimpressora para\vo manuseio de\vUNOWNS.\fSinta-se livre\npara usá-la.",
  ["44:4c93"] = "As RUÍNAS têm\nuns 1500 anos.\fMas não se sabe\nporque elas foram\vfeitas, ou por\vquem.",
  ["44:4ceb"] = "Quantos tipos de\nPOKéMONS devem\vhaver nas RUÍNAS?",
  ["44:4d1e"] = "Apareceram\nPOKéMONS nas\vRUÍNAS?\fQue notícia\nincrível!\fPrecisaremos\ninvestigar isto.",
  ["44:4d71"] = "Existem símbolos\nraros desenhados\vnas paredes das\vRUÍNAS.\fEles devem ser a\nchave para revelar\vos mistérios\vdas RUÍNAS.",
  ["44:4ded"] = "Viu os POKéMONS\nestranhos nas\vRUÍNAS?\fEles se parecem\nmuito com aqueles\vdesenhos das\vparedes de lá.\fHum…Isso deve\nsignificar que\vexistem muitos\vtipos deles…",
  ["44:4e8b"] = "RUÍNAS ALFA\fDécimo ano de\nexploração.",
  ["44:4eae"] = "POKéMON misterioso\nNome: UNOWN\fUm total de 26\ntipo encontrados.",
  ["44:4ee3"] = "Parece não\nfuncionar ainda.",
  ["44:4f02"] = "Os UNOWNS precisam\nser imprimidos.",
  ["44:4f5b"] = "Tem muitos\nlivros acadêmicos.\fRuínas Anciãs…\nMistério dos\vAnciões…",
  ["44:5859"] = "no chão\né um lixo.\fLeve-o se você\nquiser!",
  ["44:5b06"] = "KURT: Olá,\n{PLAYER}!\fOs guardas acima\nme empurraram\vquando eu os\vgritei.\fMas eu acabei\ncaindo para dentro\vdo POÇO.\fEu bati minhas\ncostas com força,\ve não posso me\vmover.\fRatos! Se eu\ntivesse desmaiado,\vmeu POKéMON os\vpuniria…\fAh, ele não pode\nser ajudado.\f{PLAYER}, mostre a\neles a sua raiva\vno meu lugar!",
  ["44:5f00"] = " RABOS DOS\vSLOWPOKES?\fSe a EQUIPE ROCKET\nte obedecer, nossa\vreputação seria\varruinada!",
  ["44:6023"] = "Um SLOWPOKE sem a\nsua CAUDA…\fHã? Ele tem uma\nCARTA. Quer Ler?",
  ["44:6061"] = "{PLAYER} lê a\nCARTA.\fSeja bom e olhe\npela casa com o\vvovô e o SLOWPOKE.\fCom amor, Papai.",
  ["44:60b9"] = "Um SLOWPOKE sem\na sua CALDA…",
  ["44:6182"] = "Eu estou esperando\npara ver o momento\vda evolução do\vSLOWPOKE.\fAtravés desta\npesquisa, eu fiz\vuma descoberta.  \fUm SLOWPOKE\nequipado com a\vPEDRA DO REI é\vmuitas vezes\vmordido por um\vSHELLDER.\fEi, eu vou dividir\nessa PEDRA DO REI\vcom você.",
  ["44:624a"] = "Eu vou ser como\num SLOWPOKE.\fEu vou esperar\npacientemente,\ventão vou poder\vver um evoluir.",
  ["44:62c5"] = "As pessoas treinam\nneste FAROL.\fNão é fácil subir\ndevido aos\vtreinadores de\vPOKéMONS.",
  ["44:631a"] = "No passado,\nos POKéMONS\viluminavam o mar o\vredor de OLIVINE.\fO FAROL foi\nconstruído em\vhomenagem a estes\vPOKéMONS.",
  ["44:6c51"] = "a voando.",
  ["44:6dbd"] = "JASMIM: Este\nPOKéMON sempre\vmanteve o mar\viluminado à noite.\f…Mas ele ficou\ndoente…   \fEle está\nofegante…\fEu sei que existe\numa FARMÁCIA\vmaravilhosa na\vCIDADE CIANWOOD.\fMas tem que\natravessar o mar…\fEu não posso\ndeixar AMPHY\vsozinho…",
  ["44:6ea0"] = "…Você poderia\npegar o REMÉDIO em\vCIANWOOD?\fPor favor!",
  ["44:6ed5"] = "JASMINE: …Este\nmedicamento curará\vAMPHY?",
  ["44:6eff"] = "{PLAYER} deu a\nPOÇÃO SECRETA à\vJASMINE.",
  ["44:6f26"] = "JASMIM: …Hum, por\nfavor, não se\vofenda…\n\fA AMPHY não aceita\nnada de ninguém,\vsó de mim…",
  ["44:6f80"] = "JASMIM: …\fAMPHY como se\nsente?",
  ["44:6fa8"] = "JASMIM: …Oh,\nestou aliviada…\fIsto é maravilhoso\namigo!…\fObrigado mesmo,\nmuito obrigado.\f…Voltarei ao meu\nGINÁSIO.",
  ["44:701b"] = "JASMINE: …Eu entendo…",
  ["44:702d"] = "…AMPHY, aguente!",
  ["44:7055"] = "Sua respiração\nestá muito\vrápida!…",
  ["44:9f00"] = "e\vpoderoso…",
  ["44:a000"] = "me atrapalha…\fMe contou que eu\nnão amo e confio\vnos POKéMONS o\vbastante.\fEstou furioso por\nperder para um\vcoração mole como\vele.\f…Humph!\fEu não tenho tempo\npara os seus\vgostos!",
  ["44:a164"] = "sumir\vo comando.\n    \fPor isso estamos\nem alerta.\fNão deixarei\nninguém perturbar\vesse lugar!",
  ["44:c455"] = "essa PEDRA DO REI\vcom você.",
  ["44:d500"] = "ra\vdestruir a EQUIPE\vROCKET.",
  ["44:d569"] = "uele olhar\vassustado.\fEu vou lhe\ndar algo que o\vassustará!",
  ["45:4126"] = "Arrgh…\nVocê descobriu\vnossa escada\vsecreta…",
  ["45:414f"] = "Heheh!\nA experiência\vfuncionou muito\vbem.\fAs MAGIKARPS são\ninúteis, mas os\vGYARADOS são\vgrandes fábricas\vde dinheiro.",
  ["45:41bc"] = "Urrgh…\fO POKéMON dragão\ndo cara é\vpoderoso…",
  ["45:41e5"] = "LANCE: DRAGONITE,\nHIPER RAIO.",
  ["45:4204"] = "O que o trouxe,\n{PLAYER}?\fComo eu pensei,\naquele estranho\vsinal de rádio\vestá vindo daqui.",
  ["45:4259"] = "As escadas ficam\naqui.",
  ["45:4275"] = "LANCE: {PLAYER},\ndevemos ir checar\vesse lugar.\fEu irei primeiro.",
  ["45:47cd"] = "Ei!\nAlerta intruso!",
  ["45:47e3"] = "Não… Eu falhei…",
  ["45:47f4"] = "É minha vez!\nNão tem saída!",
  ["45:4814"] = "Existem sensores\nde movimento nas\vestátuas dos\vPOKéMONS.\fApareceremos até\nvocê achar o botão\vsecreto.",
  ["45:4900"] = "jo.\fAquilo no chão\nafrente é o painel\vde teletransporte.\fSe pisá-lo, você\nvoltará para a\ventrada.",
  ["45:4a37"] = "É uma estátua de\num PERSIAN…\fSeus olhos têm um\nbrilho estranho.",
  ["45:4a68"] = "Um botão secreto!\nÉ melhor\vapertá-lo.",
  ["45:4a8b"] = "O botão está\ndesligado.",
  ["45:4f65"] = "Fique parado ai!",
  ["45:4f7b"] = "Não podemos ter\num pirralho como\vvocê livre.\fIsso é contra o\norgulho da EQUIPE\vROCKET.\fPor mais forte que\nseja, você não\vpode vencer nós\vdois ao mesmo\vtempo.\fPerdão, garoto.\nPrepare-se para\vser lixado.",
  ["45:5044"] = "Ei! Não se ache o\nmelhor. Divirta-se\vpor aqui.",
  ["45:5075"] = "O quê? Você tem um\ncúmplice?\fCadê a sua honra?\fEm nome do chefe\ndeste lugar,\vGIOVANNI, eu lhe\vmostrarei o\vquanto é errado\vinterferir nos\vplanos da EQUIPE\vROCKET!",
  ["45:5114"] = "Tch, você é forte\nmesmo.\fIsso não é ruim.\fSe você entrasse\nna EQUIPE ROCKET,\vvocê poderia ser\vEXECUTIVO.",
  ["45:517e"] = "…Esse esconderijo\né feito para…\fMas tudo bem.\fA experiência da\ntransmissão foi\vum sucesso total.\fNão me importo\ncom o que ocorrer\vneste lugar agora.\fTemos planos\nmaiores.\fEm breve\nvocê apreciará o\vverdadeiro poder\vda EQUIPE ROCKET.\fDivirta-se\nenquanto puder…\fHahahaha…",
  ["45:5290"] = "LANCE:\nConseguimos. Nós\vderrotamos todos\vos ROCKETS aqui.\fMas me intrigo com\no jovem rapaz que\veu batalhei por\vaqui…",
  ["45:5306"] = "Perdão, {PLAYER}.\nEu vi como você\vera bom, então eu\vrecuei.\fAgora o que resta\nfazer é desativar\vesse estranho\vsinal de rádio.",
  ["45:5387"] = "É essa máquina que\nestá causando\vtodos problemas.\fNão vejo um\ninterruptor nela…\fNão temos escolha.\nTemos que\vfazer todos\vos ELECTRODES\vdesmaiarem.\fIsso deve fazer\nessa máquina parar\vde transmitir\vestranhos sinais.\fNão é culpa dos\nPOKéMONS, e isso\vme deixa furioso.\f{PLAYER}, vamos\ncomeçar o\vtrabalho.",
  ["45:54a2"] = "LANCE: Eu fico com\neste lado.",
  ["45:54c1"] = "LANCE: Aquele\nsinal estranho\vfinalmente parou.\fO LAGO deve voltar\nao normal.\fVocê é o herói!\fDeixe-me\nagradecê-lo em\vnome de todos os\vPOKéMONS.\fOh, sim. Você deve\nlevar isso.\fEu achei isso\naqui, mas eu não\vpreciso disso.",
  ["45:55b0"] = "É o REDEMOINHO.\nEnsine-o a um\vPOKéMON para\vatravessar águas\vselvagens.\fMas lembre-se\ndisso:\fVocê só pode\nusá-lo fora de\vbatalhas se\vpossuir a INSÍGNIA\vdo GINÁSIO\vMAHOGANY.",
  ["45:564c"] = "{PLAYER}…\fA jornada para se\ntornar um MESTRE\vPOKéMON é longa e\vdifícil.\fSabendo disso,\nvocê pretende\vcontinuar?\f…\fEntendo. Não, você\ntem razão.\fSe desistisse\nfacilmente, você\vnunca teria\vseguido o sonho do\vprimeiro lugar.\fEu espero vê-lo\nnovamente!",
  ["45:574f"] = "LANCE: Você está\nbem?\fSeu POKéMON está\nferido e cansado.\fPara isso, lhes dê\nalguns dos meus\vremédios.",
  ["45:57af"] = "LANCE: {PLAYER},\nvamos dar o nosso\vmelhor para os\vPOKéMONS.",
  ["45:59f1"] = "A porta está\nfechada…\fEla precisa da\nsenha para abrir.",
  ["45:5a23"] = "A porta está\nfechada.\f{PLAYER} usou a\nsenha.\fA porta abriu!",
  ["45:5a5f"] = "É o transmissor de\nrádio que está\venviando o sinal\vsinistro.\fEstá trabalhando\nna força máxima.",
  ["45:5abb"] = "O terrível sinal\ndo transmissor de\vrádio finalmente\vparou.",
  ["45:5e2f"] = "LANCE: Precisamos\nde duas senhas\vpara acessar a\vsala do chefe.\fSó alguns ROCKETS\nsabem essas\vsenhas.\fFoi um ROCKET que\nme contou isso.\f{PLAYER}, vamos\nprocurar essas\vsenhas.",
  ["45:5eeb"] = "Urrggh…\nO rapaz com capa é\vincrivelmente\vpoderoso…",
  ["45:5f1d"] = "… \fEu não te contei\nque ia destruir a\vEQUIPE ROCKET?\f…Diga-me, quem era\naquele rapaz com\vuma capa e que\vusava POKéMONS\vdragões?\fMeu POKéMON não\nfoi páreo para\vele.\fEu não ligo em\nperder. Eu posso\vderrotá-lo pegando\vPOKéMONS mais\vpoderosos.\fE o que ele disse\nque me atrapalha…\fMe contou que eu\nnão amo e confio\vnos POKéMONS o\vbastante.\fEstou furioso por\nperder para um\vcoração mole como\vele.\f…Humph!\fEu não tenho tempo\npara os seus\vgostos!",
  ["45:60b6"] = "O quê? Quem é\nvocê? Esse é\vo escritório do\vnosso líder,\vGIOVANNI.\fDesde quando a\nEQUIPE ROCKET\vfaliu há três anos\vatrás, ele está\vtreinando.\fMas sabemos que\nele voltará um dia\vpara reassumir\vo comando.\n    \fPor isso estamos\nem alerta.\fNão deixarei\nninguém perturbar\vesse lugar!",
  ["45:61c7"] = "Eu… Nada pude\nfazer…\fGIOVANNI, por\nfavor, perdoe-me…",
  ["45:61fe"] = "Não, não posso\ndeixar isso me\vafetar.\fDevo informar aos\noutros…",
  ["45:623b"] = "MURKROW: A senha\né…\fGRANDE GIOVANNI.",
  ["45:6626"] = "A porta está\nfechada…\fEle usa duas\nsenhas para abrir.",
  ["45:6659"] = "A porta está\nfechada…\f{PLAYER} usou as\nduas senhas.\fA porta foi\naberta!",
  ["45:6a44"] = "Ah, cara…\nMeu chefe vai\vficar irritado… \fO FARFETCH'D que\nCORTA árvores para\vfazer carvão\vfugiu.\fNão posso\nprocurá-lo aqui\vna FLORESTA ILEX.\fEla é grande,\nassustadora e\vescura demais para\vmim.",
  ["45:6b01"] = "Uau! Muito\nobrigado!\fO POKéMON do meu\nchefe não me\vobedece porque\veu não tenho\vINSÍGNIAS.",
  ["45:6b57"] = "Este é o POKéMON\nperdido.",
  ["45:6b6e"] = "FARFETCH'D: FARF!",
  ["45:6c29"] = "Este é o HM CORTA.\nEnsine ele a um\vPOKéMON para\vcortar árvores.\fClaro, é preciso\nter a INSÍGNIA DO\vGINÁSIO DE AZALEA\vpara poder usá-lo.",
  ["45:6ca8"] = "Deseja aprender\ncomo se fabrica\vcarvão comigo? \fVocê será o\nprimeiro em dez\vanos!",
  ["45:6d03"] = "O que estou\nfazendo?\fEstou sacudindo as\nárvores usando\vCABEÇADA.\fÉ divertido. Tente\ntambém!",
  ["45:6d55"] = "Balance as árvores\nusando a CABEÇADA.\fTem vezes que os\nPOKéMONS caem\vdormindo.",
  ["45:6d97"] = "A FLORESTA ILEX\ntem árvores tão\vgrandes que não se\vpode ver o céu.\fFique atento com\nos itens que são\vjogados no chão.",
  ["45:6e11"] = "SANTUÁRIO DA\nFLORESTA ILEX…\fÉ em homenagem ao\nprotetor da\vfloresta.",
  ["45:9d00"] = "osso confiar.\fPor favor, salve\na TORRE DE RÁDIO…\fE toda a nação\nPOKéMON!",
  ["45:a762"] = "or preciso.",
  ["45:cd49"] = "u, certo?",
  ["45:cd63"] = "\najuda golpes do\vtipo escuro.",
  ["46:4500"] = "ompletando a\vPOKéDEX?\fAqui vai uma dica!\fO ANDARILHO\nANTHONY, na ROTA\v33, é um bom\vrapaz.\fEle te ligará se\nvir algum POKéMON\vraro!",
  ["46:457a"] = "A porta está\ntrancada…",
  ["46:458d"] = "A porta está\naberta.",
  ["46:45a0"] = "A CHAVE PORÃO\nabriu a porta.",
  ["46:45c3"] = "Bem-vindo!\fEu comando o SALÃO\nPOKéMON.\fDos IRMÃOS\nCABELEIREIRO,\veu sou o mais\vvelho e melhor\vcabeleireiro.\fPosso deixar seu\nPOKéMON mais\vbonito por apenas\v¥500.\fVocê quer que eu\nfaça isso?",
  ["46:4664"] = "Em qual POKéMON\neu devo trabalhar?",
  ["46:4682"] = "Certo! Veja como\nficou bonito!",
  ["46:46a2"] = "Isso! Tudo pronto!",
  ["46:46b4"] = "Você está certo?\nQue vergonha!",
  ["46:46d3"] = "Você precisa de\nmais dinheiro que\visso.",
  ["46:46f5"] = "Só faço um corte\npor dia.\fEu já fiz um hoje.",
  ["46:4726"] = "Bem-vindo ao\nSALÃO POKéMON!\fEu sou o mais\njovem e barato\vcabeleireiro\vdos IRMÃOS\vCABELEIREIROS! \fMudo o visual do\nseu POKéMON por\vapenas ¥300.\fO que você acha?",
  ["46:47bb"] = "De qual POKéMON\neu devo cortar?",
  ["46:47d8"] = "Bom! Eu melhorarei\no visual!",
  ["46:47f4"] = "Aí está.\nEstá pronto!",
  ["46:480c"] = "Não?\nQue chato, cara!",
  ["46:4825"] = "Você está com\npouco dinheiro.",
  ["46:4845"] = "Eu só faço um\ncorte por dia.\fPerdão, eu já\ntrabalhei muito\vhoje.",
  ["46:4889"] = "{STRBUF} parece\num pouco feliz.",
  ["46:48a6"] = "{STRBUF} parece\nfeliz.",
  ["46:48b8"] = "{STRBUF} parece\nencantado!",
  ["46:48ce"] = "Não estamos\nabertos hoje.",
  ["46:48e4"] = "NINGUÉM PODE\nPASSAR A PARTIR\vDESSE PONTO!",
  ["46:4e67"] = "Espere!\fEu vi você, então\neu te parei.\fEu não preciso\nde um subordinado\venquanto eu cuido\vda EQUIPE ROCKET.\fEspere um pouco…\fVocê já me\nderrotou antes,\vnão é?\fFoi sorte.\fMas pagarei meus\ndébitos!",
  ["46:4f27"] = "…Por quê…\nPor que eu perdi?\fEu escolhi o\nPOKéMON mais\vforte.\fEu não facilitei.\fMas por que eu\nperdi?",
  ["46:4f8c"] = "…Eu não entendo…\fSerá que o LANCE\ndisse a verdade?  \fQue eu não trato\ndireito os\vPOKéMONS?\fAmor…\fConfiança…\fÉ disso mesmo que\neu preciso?\fEles estão me\nimpedindo de\vvencer?\fEu… eu não\nentendo.\fMas isso não vai\nacabar aqui.\fNão agora. Não\ndevido a isso.\fNão desistirei do\nmeu sonho de me\vtornar o melhor\vtreinador POKéMON\vdo mundo!",
  ["46:50cc"] = "Humph. Esse é meu\npoder real, bobo.\fVou fazer a EQUIPE\nROCKET virar\vhistória.\fTriturarei o LANCE\ncom meu calcanhar.",
  ["46:5140"] = "Eu fui desafiado\npara uma batalha\vlá embaixo.\fLá é muito\ndesagradável.\fTome cuidado.",
  ["46:519a"] = "Há algumas Lojas\naí em baixo…\fMas há treinadores\ntambém lá.\fEu tenho medo de\ndescer lá!",
  ["46:551e"] = "Está escrito\nBOTÃO 1.",
  ["46:55e1"] = "Está DESLIGADO.\nDeseja LIGÁ-LO?",
  ["46:55f7"] = "Está LIGADO.\nDeseja DESLIGÁ-LO?",
  ["46:560d"] = "Está escrito\nBOTÃO 2.",
  ["46:5624"] = "Está escrito\nBOTÃO 3.",
  ["46:563b"] = "Está escrito\nEMERGÊNCIA.",
  ["46:5795"] = "Ei, garoto! Você\nestá atrapalhando.\fNosso dever é\ntrabalhar em luga-\vres onde ninguém\vnos veja!",
  ["46:57f7"] = "Eu perco a\npaciência quando\valguém me vê\vtrabalhando.\fEi, garoto,\nfuja.",
  ["46:5840"] = "Oohah! Oohah!\fO negócio no chão\né um lixo.\fLeve-o se você\nquiser!",
  ["46:5a00"] = "le me liquidou…",
  ["46:5b8f"] = "DIRETOR: Quem?\nO quê? Você veio\vme resgatar?\fObrigado!\fA TORRE DE RÁDIO!\fO que está havendo\naqui?\fDominados pela\nEQUIPE ROCKET?\fEi! Leve este\nCARTÃO.",
  ["46:5c24"] = "DIRETOR: Use-o\npara abrir persi-\vanas no 3º ANDAR.",
  ["46:5c56"] = "Estou implorando\npela sua ajuda.\fNem imagino o\nque eles farão se\vcontrolarem o\vtransmissor.\fEles podem até\ncontrolar POKéMONS\vusando um sinal\vespecial!\fVocê é o único que\neu posso confiar.\fPor favor, salve\na TORRE DE RÁDIO…\fE toda a nação\nPOKéMON!",
  ["46:5f3d"] = "Ei!\fEu sou o REI\nCARATÊ!\fEu treino sozinho\naqui no escuro!\fVocê! Batalhe\ncomigo!\fHwaarggh!",
  ["46:5f99"] = "Arrrgghh!\nFui derrotado!",
  ["46:5fb0"] = "Eu… Eu fui\ntriturado…\fMeu treinamento\nainda não é o\vbastante…\fMas uma derrota é\numa derrota.\vEu admito.\fComo prova que\nme derrotou, eu\vlhe darei um raro\vPOKéMON lutador.",
  ["46:6045"] = "{PLAYER} recebeu\nTYROGUE.",
  ["46:605a"] = "TYROGUE é do tipo\nlutador.\fEle evolui em um\nPOKéMON mais\vforte.\fContinue treinando\nduro.\fEu também\vtreinarei.\fAté mais!",
  ["46:60cf"] = "Não tem lugar na\nsua equipe!",
  ["46:6267"] = "Está todo\nimobilizado no\vgelo.",
  ["46:9153"] = "OGUE.",
  ["46:ca00"] = "do\vmundo.",
  ["46:cb43"] = "Era a\nÁGUA MÍSTICA.\fEu não preciso\ndela, você a quer?",
  ["46:d744"] = "tavam passeando\vem algum lugar.",
  ["47:438b"] = "Uau! Você me\nsurpreendeu!\fEstava de\nÓCULOSESCURO, daí\vnem notei sua\vpresença. \fO que eu faço\naqui?\fEi, não se\npreocupe com isso.\fEu lhe darei\num par de\vÓCULOSESCURO,\ventão esqueça que\vme viu, certo?",
  ["47:4458"] = "Os ÓCULOSESCURO\najuda golpes do\vtipo escuro.",
  ["47:459c"] = "CLAIR: Certo.\nEu reconheço o\vseu poder real.\fEsta INSÍGNIA é\nsua.",
  ["47:45e1"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA\vCRESCENTE do\vGINÁSIO da VILA\vBLACKTHORN.",
  ["47:45fa"] = "A INSÍGNIA CRES-\nCENTE permitirá\vseu POKéMON usar o\vgolpe para escalar\vcachoeiras.\fE seu POKéMON o\nreconhecerá como\vum treinador e\vobedecerá todas\vas ordens sem\vquestionar.\fE eu também quero\nque você leve\visso aqui.",
  ["47:46d6"] = "Isto contém o\nSOPRO DRAGÃO.\fNão tem nada a ver\ncom a ver com o\vmeu sopro.\fSe não quiser,\nvocê não é\vobrigado a levar.",
  ["47:4754"] = "Então você\ncolecionou todas\vas INSÍGNIAS.\fSua destinação é\na LIGA POKÉMON no\vPLANALTO ÍNDIGO.\fVocê sabe como\nchegar lá?\fDaqui, vá à\nCIDADE NEW BARK.\fDepois SURFE ao\nleste. Aquela rota\vé bem difícil.\fNão se atreva a\nperder na LIGA\vPOKÉMON!\fCaso o faça, me\nsentirei pior\vainda do que ter\vperdido para\vvocê!",
  ["47:4881"] = "SANTUÁRIO DO\nDRAGÃO\fUm santuário\nhonrando os\vPOKéMONS dragões\vque viveram na\vTOCA DO DRAGÃO.",
  ["47:48d6"] = "…\nO quê? {PLAYER}?\f…Não batalharei com\nti agora…\fMeus POKéMONS não\nestão prontos para\vos seus.\fNão posso exigir\nmuito agora.\fTenho que ser\ndisciplinada para\vtornar-me a melhor\vtreinadora POKéMON\vde todos os\vtempos.",
  ["47:4980"] = "…\fBom…\fAprenda a ficar\nlonge do meu\vcaminho…",
  ["47:49a6"] = "{PLAYER} achou o(a)\n{STRBUF}!",
  ["47:49b8"] = "Mas {PLAYER} não\npode pegar mais\vitens.",
  ["48:4101"] = "Uau, sua POKéGEAR\né incrível!\fFoi sua mãe quem\nlhe deu ela?",
  ["48:413e"] = "Espere, {PLAYER}!",
  ["48:4148"] = "O que você pensa\nque está fazendo?",
  ["48:4168"] = "É perigoso sair\nsem um\vPOKéMON!\fPOKéMON selvagens\npulam do mato\fno caminho para\na próxima cidade.",
  ["48:41ce"] = "Oh! Seu POKéMON\né adorável!\vQueria ter um!",
  ["48:41fc"] = "Oi, {PLAYER}!\nSaindo de novo?\fVocê devia avisar\nsua mãe quando\vsair.",
  ["48:4240"] = "Ligue para sua mãe\nna POKéGEAR para\fcontar como você\nestá indo.",
  ["48:427e"] = "Ei, {PLAYER}!\fSoube que o PROF.\nELM descobriu\vnovos POKéMON.",
  ["48:42b0"] = "……\fEntão este é o\nfamoso LAB POKéMON\vdo ELM…",
  ["48:42d7"] = "…O que você está\nolhando?",
  ["48:42f2"] = "CIDADE NEW BARK\fA cidade onde\nos ventos do\vrecomeço sopram",
  ["48:4332"] = "Casa de {PLAYER}",
  ["48:433c"] = "LAB POKéMON ELM",
  ["48:434a"] = "CASA DO ELM",
  ["48:45ae"] = "Você é um\ntreinador novato,\vné? Dá para ver!\fTudo bem! Todo\nmundo já foi\vnovato um dia!\fSe quiser, posso\nte ensinar umas\vcoisas.",
  ["48:463a"] = "Certo, então!\nMe siga!",
  ["48:4650"] = "Este é um CENTRO\nPOKéMON. Curam\fseu POKéMON num\ninstante.\fVocê vai depender\nmuito deles,\fé bom aprender\nsobre eles.",
  ["48:46cf"] = "Esta é uma LOJA\nPOKéMON.\fVendem BALLS para\npegar POKéMON\fselvagens e outros\nitens úteis.",
  ["48:4724"] = "A ROUTE 30 fica\npor aqui.\fTreinadores lutam\ncom seus POKéMON\fpreferidos lá.\nVale ver.",
  ["48:4772"] = "Este é o mar,\ncomo você vê.\fAlguns POKéMON só\nsão achados\vna água.",
  ["48:47b7"] = "Aqui…\fÉ a minha casa!\nObrigado pela\vcompanhia.\fDeixe eu lhe dar\num presentinho.",
  ["48:4803"] = "A POKéGEAR de\n{PLAYER} tem MAPA!",
  ["48:481c"] = "A POKéGEAR fica\nmais útil quando\vvocê põe CARDS.\fBoa sorte na sua\njornada!",
  ["48:48ad"] = "…\fVocê pegou um\nPOKéMON no LAB.\fQue desperdício.\nUm fraco desses.\f…\fNão entendeu o\nque eu disse?\fPois eu tenho um\nPOKéMON bom.\fVou te mostrar\no que eu digo!",
  ["48:4942"] = "Hunf. Feliz por\nter ganhado?",
  ["48:4961"] = "…\fMeu nome é ???.\fEu vou ser o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["48:49a5"] = "Hunf. Isso foi\nperda de tempo.",
  ["48:49c7"] = "…\fMeu nome é ???.\fEu vou ser o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["48:4a0b"] = "Você falou com o\nvelho perto do\vCENTRO POKéMON?\fEle põe um MAPA de\nJOHTO na sua\vPOKéGEAR.",
  ["48:4a63"] = "Com POKéMON por\nperto, qualquer\vlugar é bom.",
  ["48:4a91"] = "A casa do\nMR.POKéMON fica\vmais adiante.",
  ["48:4abc"] = "Eu lutei com os\ntreinadores da\vestrada.\fMeus POKéMON\nperderam feio!\fPreciso levar eles\nao CENTRO POKéMON",
  ["48:4b21"] = "Um POKéMON que eu\npeguei tinha algo\fAcho que é\nMYSTIC WATER.\fNão preciso dele,\nvocê quer?",
  ["48:4b7c"] = "Volto a pescar,\nentão.",
  ["48:4b9b"] = "CHERRYGROVE CITY\fA cidade das\nflores perfumadas",
  ["48:4bd0"] = "CASA DO GUIA",
  ["48:4d29"] = "Olá!\nVocê treinador?\fLutar com LÍDER,\nganhar você?",
  ["48:4d62"] = "Ooh, la la!\nMuito bom mesmo!",
  ["48:4d81"] = "É mesmo? Então\nestudar você deve!\vMe siga!",
  ["48:4daf"] = "Aqui, professor eu\nsou. Bom é você\vestudar aqui!",
  ["48:4ddf"] = "Dizem que aparecem\nfantasmas na\vSPROUT TOWER.\fDiziam que ataques\nnormais não pegam\fnos fantasmas.\nNada mesmo.",
  ["48:4e49"] = "Ei, você é\ntreinador POKéMON\fSe vencer o LÍDER\nde GINÁSIO daqui,\fvai estar pronto\npara valer!",
  ["48:4ea5"] = "FALKNER, do\nGINÁSIO POKéMON\fde VIOLET, é um\nótimo treinador!\fEle herdou o\nginásio do pai\fe fez um belo\ntrabalho nele.",
  ["48:4f1b"] = "Vi uma árvore que\nse mexe adiante!\fSe você tocar,\nela se contorce\ve dança! Legal!",
  ["48:4f68"] = "VIOLET CITY\fA cidade dos\naromas de outrora",
  ["48:4f92"] = "VIOLET CITY\nGINÁSIO POKéMON\vLÍDER: FALKNER\fO elegante mestre\ndo tipo voador",
  ["48:4fda"] = "SPROUT TOWER\fConheça o caminho\ndos POKéMON",
  ["48:5003"] = "ACADEMIA POKéMON\nDO EARL",
  ["48:51e7"] = "…Diga-me a\nresposta.\fÉ verdade que a\nEQUIPE ROCKET\vretornou?\fO quê? Você os\nderrotou? Ah!\vMentiroso.\fIsso não é piada?\nVamos ver se você\vé bom mesmo.",
  ["48:5280"] = "… Humph! POKéMON\ninútil!\fEscute cara, só\nvenceu porque meus\vPOKéMONS são\vfracos.",
  ["48:52cd"] = "Odeio treinadores\nPOKéMON fracos. \vNão importa quem\vou o que.\fEu serei forte e\nvou exterminar os\vfracos.\fIsso serve para\na EQUIPE ROCKET\vtambém.\fEles são poderosos\nquando em grupo.\fMas sozinhos eles\nsão uns fracos.\fEu odeio todos\neles.\fE você desapareça.\nUm fracote como\vvocê é apenas uma\vdistração.",
  ["48:53f5"] = "…Humph! Sabia que\nvocê mentia.",
  ["48:5415"] = "É inseguro ir lá\ndentro, mas eu\vestarei atento.\fNão sou um Bom\nSamaritano?",
  ["48:5461"] = "Você sabe algo do\nRABOSLOWPOKE?\vSoube que é ótimo!\vNão fica feliz\vsabendo disso?",
  ["48:54b5"] = "Os SLOWPOKES\ndesapareceram da\vcidade…\fSoube que suas\nCALDAS são\vvendidas por aí.",
  ["48:550d"] = "Os SLOWPOKES\nvoltaram.\fConhecendo eles,\nsei que não\vestavam passeando\vem algum lugar.",
  ["48:5568"] = "Veio aqui para que\nKURT faça BOLAS\vpara você?\fMuitas pessoas só\nfazem isso.",
  ["48:55b4"] = "Atravesse AZALEA\ne você estará na\vFLORESTA ILEX.\fMas aquelas\nárvores magrelas\vimpossibilitam\va passagem.\fO POKéMON do\nHOMEM DO CARVÃO\vpode cortá-las.",
  ["48:564a"] = "SLOWPOKE: …\f……………",
  ["48:565d"] = "………Yawn?",
  ["48:5679"] = "CIDADE AZALEA \fOnde Pessoas e\nPOKéMONS Vivem Em\vÓtima Harmonia.",
  ["48:56b2"] = "CASA DO KURT.",
  ["48:56c0"] = "CIDADE AZALEA\fLÍDER DO GINÁSIO\nPOKéMON: BUGSY\fUma enciclopédia\nPOKéMON ambulante.",
  ["48:5706"] = "POÇO SLOWPOKE\fChamado também de\nPOÇO FAZ CHUVA.\fOs moradores\nacreditam que o\vbocejo do SLOWPOKE\vchama a chuva.\fOs registros\ninformam que estes\vbocejos acabaram\vcom uma seca há\v400 anos atrás.",
  ["48:57ac"] = "ESTUFA DE CARVÃO.",
  ["48:57bb"] = "FLORESTA ILEX\fEntre pelo portão.",
  ["48:5936"] = "Você cruzou o mar\npara chegar aqui?\fDeve ter sido\nduro.\fIsto seria mais\nfácil se seu\vPOKéMON tivesse\va técnica VOAR…",
  ["48:59a8"] = "Mas você não pode\nusar VOAR sem a\vINSÍGNIA daqui.\fSe você ganhar\ndo LÍDER DO\vGINÁSIO daqui,\vvenha me ver.\fTe darei uma coisa\nboa.",
  ["48:5a28"] = "É a INSÍGNIA DA\nTEMPESTADE!\fEntão você pode\nlevar o HM!",
  ["48:5a62"] = "Ensine VOAR ao\nseus POKéMONS.\fVocê poderá voar\nrapidamente para\vum lugar que você\vjá visitou.",
  ["48:5abc"] = "Meu marido perdeu\npara você, então\vele precisa\vtreinar.\fQue bom, porque\nele já estava\vficando gordo.",
  ["48:5b24"] = "Se você usar o\nVOAR, você voltará\và OLIVINE\vrapidamente.",
  ["48:5b5e"] = "As pedras ao norte\nda cidade podem\vser quebradas.\fElas podem conter\nalgo.\fSeus POKéMONS\npodem quebrá-las\vusando QUEBRA\vPEDRA.",
  ["48:5bd9"] = "CHUCK, o LÍDER DO\nGINÁSIO, batalha\vcom POKéMONS do\vtipo LUTADOR.",
  ["48:5c78"] = "CIDADE CIANWOOD\fA Cidade Mais\nAquática De JOHTO.",
  ["48:5ca7"] = "CIDADE CIANWOOD\fLÍDER DO GINÁSIO\nPOKéMON: CHUCK\fEle vai mostrar do\nque é capaz.",
  ["48:5cee"] = "500 Anos de\nTradição.\fFARMÁCIA CIANWOOD \fEstamos esperando\nsuas encomendas.",
  ["48:5d3d"] = "NOVO EST→DIO\nFOTOGRÁFICO.\fTire Uma Foto\nPara Recordação!",
  ["48:5ec6"] = "Eles contruíram\na nova TORRE\vde RÁDIO para\vsubstituir a velha\vque estava em\vruínas.",
  ["48:5f06"] = "Eu sei que tem uma\nnova LOJA DE\vBICICLETAS, mas\veu não consigo\vencontrá-la.",
  ["48:5f43"] = "Aquele homem\nvestido de preto\vfaz parte da\vEQUIPE ROCKET?\fQue tolo!",
  ["48:5f8a"] = "Aquele homem\nvestido de preto\vrealmente fazia\vparte da EQUIPE\vROCKET?\fEu não acredito!",
  ["48:5fd0"] = "A TORRE DE RÁDIO\nem GOLDENROD é um\vponto turístico.\fEles estão fazendo\numa campanha\vpromocional agora\vmesmo.\fEstão modificando\nas POKéGEARS, que\vpoderão funcionar\vcomo rádios!",
  ["48:6071"] = "Oh, sua POKéGEAR\nfunciona como um\vrádio!",
  ["48:6093"] = "E-he-he-he…\fEu me encrenquei\npor jogar no\vporão da LOJA DE\vDEPARTAMENTOS.",
  ["48:60e0"] = "O homem daquela\ncasa altera os\vnomes dos\vPOKéMONS.\fEle pode alterar\nos dos seus.",
  ["48:612c"] = "Uau! Essa é uma\ngrande cidade.\fEu não sei onde\nficam as coisas.",
  ["48:616a"] = "Então essa é a\nTORRE DE RÁDIO…",
  ["48:6187"] = "O que você quer,\nseu peste? Saia\vdaqui!",
  ["48:61ab"] = "Saia do meu\ncaminho, idiota!",
  ["48:61ca"] = "Roubar esta TORRE\nDE RÁDIO…\fO quê? Isto não é\nda sua conta!",
  ["48:6207"] = "POKéMONS? Eles não\nsão nada mais\vque fábricas de\vdinheiro!",
  ["48:623f"] = "Um dia nosso\nsonho será real…\fFoi um grande\nempenho…",
  ["48:627c"] = "Ei, pirralho! Você\nnão é deste lugar.\fSaia daqui!",
  ["48:62a8"] = "Experimente o\nverdadeiro terror\vda EQUIPE ROCKET!",
  ["48:62d4"] = "ESTAÇÃO DA CIDADE\nGOLDENROD.",
  ["48:62ec"] = "CIDADE GOLDENROD\fTORRE DE RÁDIO.",
  ["48:6308"] = "LOJA DE\nDEPARTAMENTOS.\fNossa seleção é\ncheia de bens\vPOKéMON.",
  ["48:6341"] = "CIDADE GOLDENROD\fLÍDER DO GINÁSIO\nPOKéMON: WHITNEY\fA Garota\nIncrivelmente\vLinda!",
  ["48:6386"] = "CIDADE GOLDENROD\fA Cidade Que Tem\nMais Charme!",
  ["48:63b8"] = "LOJA DE\nBICICLETA.\fO mundo é\nredondo!",
  ["48:63de"] = "CASA DE JOGOS\nde GOLDENROD.\fA Sua Diversão.",
  ["48:640b"] = "ALTERADOR DE\nNOMES\fAltere aqui o nome\ndo seu POKéMON.",
  ["48:6435"] = "ENTRADA\nSUBTERRÂNEA.",
  ["49:40d7"] = "…\fVocê aqui?\fNão precisa ficar\ntrêmulo.\fEu não me aborreço\ncom fracos.\fFalando nisso,\na LÍDER DO GINÁSIO\vda cidade não está\vaqui.\fEstá supostamente\ncuidando de um\vPOKéMON doente\vlá no FAROL.\fBurra!\nHahaha!\vEu abandono\vPOKéMONS doentes!\fUm POKéMON que\nnão batalha é\vdesprezível!\fPor que você não\nvai treinar lá\vno FAROL?\fQuem sabe, você\nnão deixa de ser\vum fracote!",
  ["49:4235"] = "As estradas\nescuras são\vperigosas. \fMas no período da\nnoite, o mar é\vaté mais\vtraiçoeiro!\fSem a luz do FAROL\npara iluminar o\vmar, nenhum navio\vpode velejar\vpela noite!",
  ["49:42e1"] = "Aquela coisa que\nvocê tem é uma\vPOKéGEAR certo?\vUau, incrível.",
  ["49:431e"] = "Uau, você tem uma\nPOKéDEX!\fIsto é tão legal!",
  ["49:434e"] = "Olá, treinador!\nO mar está doce!\fCante comigo!\nYo-ho! Temos que\vpegar POKéMONS…",
  ["49:439a"] = "CIDADE OLIVINE\fO Porto Mais Belo\nDe Todo o Mundo.",
  ["49:43ca"] = "PASSAGEM DO CAIS\nEM FRENTE.",
  ["49:43e7"] = "CIDADE OLIVINE\fLÍDER DO GINÁSIO\nPOKéMON: JASMINE\fA Garota Com Roupa\nde Aço.",
  ["49:442a"] = "FAROL de OLIVINE\nTambém Conhecido\vComo FAROL\vILUMINADO.",
  ["49:4604"] = "ECRUTEAK tem duas\ntorres:\fuma ao leste e\noutra ao oeste.",
  ["49:4646"] = "Ah, jovem.\nVocê aprendeu a\vdançar como as\vGAROTAS KIMONO?\fSe ir ao seu\nTEATRO DE DANÇA,\vum estranho senhor\vlhe dará algo\vmuito bom, eu ouvi\vdizer.",
  ["49:46de"] = "Eu vou praticar no\nTEATRO DE DANÇA.\fSe importa de ir\ncomigo?",
  ["49:471d"] = "Ela era para ser a\ntorre mais alta,\vmas ela foi\vqueimada pelo\vfogo.",
  ["49:4761"] = "Três grandes\nPOKéMONS correram\vpara direções\vdistintas.\fQuem foram eles?",
  ["49:47a4"] = "Ouvi um boato\nsobre o FAROL DE\vOLIVINE.\fO POKéMON que\nservia como guia,\vficou doente.\fParece que eles\nestão encrencados.",
  ["49:481d"] = "O POKéMON no FAROL\nDE OLIVINE foi\vcurado.\fAgora os barcos\npodem navegar\vseguros pela\vnoite.",
  ["49:487e"] = "Ouvi dizer que os\nPOKéMONS estão\vfazendo alvoroços\vno LAGO DA RAIVA.\vEu gostaria de ver\visto.",
  ["49:48c3"] = "CIDADE ECRUTEAK\fA Cidade Histórica\nOnde o Passado\vEncontra o\vPresente.",
  ["49:4905"] = "TORRE ESTRANHA\fDizem que POKéMONS\nlendários moram\vlá.",
  ["49:493a"] = "CIDADE ECRUTEAK\fLÍDER DO GINÁSIO\nPOKéMON: MORTY\fO Místico Vidente\ndo Futuro.",
  ["49:497e"] = "TEATRO DE DANÇA DE\nECRUTEAK.",
  ["49:4996"] = "TORRE QUEIMADA\fEla foi destruída\npor um fogo\vmisterioso.\fFique longe,\npois é inseguro.",
  ["49:4b65"] = "Olá, garotinho!\nVejo que é novo na\vCIDADE MAHOGANY.\fComo é novato,\nvocê deve\vexperimentar o\vótimo DOCERAIVA!\fAgora, ele pode\nser seu por apenas\v¥300! Quer um?",
  ["49:4c03"] = "Bom! Muito bom!",
  ["49:4c14"] = "Não tem o valor\nnecessário.",
  ["49:4c31"] = "Oh, tudo bem…",
  ["49:4c41"] = "Não tem lugar\npara isso.",
  ["49:4c5f"] = "O DOCERAIVA já\nacabou.\fEncomendarei mais.\fNão me atrapalhe,\ngarotinho.",
  ["49:4ca2"] = "Você quer ver\no ritual dos\vGYARADOS no LAGO?",
  ["49:4cda"] = "As MAGIKARPS\nretornaram ao LAGO\vDA RAIVA.\fIsso deve ser uma\nboa notícia para\vos pescadores de\vlá.",
  ["49:4d33"] = "Como chegou a esse\nponto, dedique-se\vpara fazer coisas\vimportantes.\fVocê deve ir ao\nnorte e checar o\vLAGO DA RAIVA\vagora.",
  ["49:4daf"] = "Visite a Loja da\nVovó.\fEla vende coisas\nque ninguém tem.",
  ["49:4deb"] = "CIDADE MAHOGANY\fBem-vindo Ao Lar\nDos Ninjas.",
  ["49:4e1b"] = "Enquanto visita a\nCIDADE MAHOGANY,\vexperimente o\vDOCERAIVA!",
  ["49:4e4e"] = "CIDADE MAHOGANY\fLÍDER DO GINÁSIO\nPOKéMON: PRYCE\fO Professor Do\nInverno Rígido.",
  ["49:5063"] = "Esse lago é cheio\nde GYARADOS e\vnada mais…\fIsso porque as\nMAGIKARPS são\vforçadas a\vevoluir…",
  ["49:50c0"] = "Você veio aqui\ndevido aos boatos?\fVocê é {PLAYER}?\nEu sou LANCE, um\vtreinador como\vvocê.\fEu ouvi boatos,\nentão eu vim aqui\vinvestigar…\fEu vi a maneira\nque batalha,\v{PLAYER}.\fPosso lhe dizer\nque é um treinador\vcom grandes\vhabilidades.\fSe não se\nimportar, poderia\vme ajudar a\vinvestigar?",
  ["49:5155"] = "batalha,\v{PLAYER}.\fPosso lhe dizer\nque é um treinador\vcom grandes\vhabilidades.\fSe não se\nimportar, poderia\vme ajudar a\vinvestigar?",
  ["49:51d2"] = "LANCE: Descobri! \fParece que as\nMAGIKARPS do LAGO\vsão forçadas a\vevoluir.\fUm misterioso\nprograma de rádio\vvindo de MAHOGANY\vé o responsável.\fEstarei te\naguardando,\v{PLAYER}!",
  ["49:527d"] = "Oh… Bem, se\nmudar de idéia,\vvenha me ajudar.",
  ["49:52b1"] = "LANCE: Hm? Você\nvai me auxiliar?",
  ["49:52eb"] = "{PLAYER} obteve uma\nESCAMA RUBRA.",
  ["49:5304"] = "Os GYARADOS estão\nnervosos!\fIsso não é bom!",
  ["49:532d"] = "Hahah!\nAs MAGIKARPS estão\vmordendo!",
  ["49:5350"] = "Ouvi dizer que\nesse lago foi\vfeito por rituais\vde GYARADOS.\fQueria saber se\nisso tem haver\vcom seu poder\vdestrutivo.",
  ["49:53c7"] = "Meus olhos estão\nme enganando?\fEu vi um GYARADOS\nvermelho no lago…\fPensava que\nos GYARADOS eram\vazuis!",
  ["49:5690"] = "WESLEY: Olá, como\nvai você? Como\vsabe, hoje é\vQuarta-feira.\fSou WESLEY, das\nQuartas.",
  ["49:56e9"] = "Prazer em\nconhecê-lo.\fLeve uma\nlembrancinha.",
  ["49:5717"] = "WESLEY: A\nFAIXAPRETA melhora\vos golpes do tipo\vluta.",
  ["49:5750"] = "WESLEY: Como me\nachou, você deve\vter conhecido meus\virmãos e irmãs.\fOu você apenas\nteve sorte?",
  ["49:57b5"] = "WESLEY: Hoje não\né Quarta. É uma\vpena.",
  ["49:57e3"] = "LAGO DA RAIVA,\ntambém chamado de\vLAGO DO GYARADOS.",
  ["49:580f"] = "CASA DOS\nPESCADORES.",
  ["49:5994"] = "Perdão.\fNossa LÍDER\nDO GINÁSIO está\vtreinando na\vcaverna aqui\vatrás. \fNão faço idéia\nde quando ela\vvoltará.",
  ["49:5a01"] = "Nossa LÍDER\nDO GINÁSIO o\vespera.\fPorém, seria\nimpossível para\vum treinador\vcovarde vencê-la.",
  ["49:5a54"] = "vencê-la.",
  ["49:5a6b"] = "Você derrotou\nnossa LÍDER DO\vGINÁSIO?\fIsso é incrível!\fCom sua força,\nvocê deve se\vdar bem na\vLIGA POKéMON.",
  ["49:5ad0"] = "Só usuários de\ndragões podem\vtreinar aqui.\fSaia por favor.",
  ["49:5b0e"] = "Como CLAIR, a\nmestra em dragões,\vpermitiu, você\vpode entrar.",
  ["49:5b4e"] = "Meu rádio está\nquebrado?\fE depois eu só\nrecebia esse\vestranho sinal.",
  ["49:5b87"] = "Aroo! Vozes na\nminha cabeça!\fHã? Estou ouvindo\no rádio!",
  ["49:5bc1"] = "Você fará\nseus POKéMONS\vesquecerem alguns\vgolpes?",
  ["49:5bf5"] = "Serei um usuário\nde dragões como\va CLAIR.",
  ["49:5c1f"] = "SANTOS: …\fÉ Sábado…\fSou SANTOS dos\nSábados…",
  ["49:5c4f"] = "Leve isso aqui…",
  ["49:5c63"] = "SANTOS: …\fTALÃOENCANTO.\fGolpes\ntipo fantasma\vmelhorarão.\fVai\nimpressioná-lo…",
  ["49:5cae"] = "SANTOS: …\fTe vejo em outro\nSábado…\fEu não terei mais\nnenhum presente…",
  ["49:5cf8"] = "SANTOS: Hoje não é\nSábado…",
  ["49:5d16"] = "Uau, você\natravessou o\vCAMINHO DE GELO?\fVocê é\num treinador\vcorajoso!",
  ["49:5d5f"] = "VILA BLACKTHORN\fUm Harmônico Lugar\nnas Montanhas.",
  ["49:5d89"] = "VILA BLACKTHORN\fLÍDER DO GINÁSIO\nPOKéMON: CLAIR\fA abençoada\ntreinadora de\vPOKéMONS dragões.",
  ["49:5dd1"] = "CASA DO APAGADOR\nDE TÉCNICAS.",
  ["49:5de7"] = "TOCA DO DRAGÃO\nACIMA.",
  ["49:5dfb"] = "DICAS DO TREINADOR\fUm POKéMON\nsegurando o\vGRÃOMILAGRE vai se\vcurar de todos os\vseus problemas de\vestado.",
  ["49:5f27"] = "MONTE PRATEADO.",
  ["49:d600"] = "e\ngolpes que eu não\vsabia que ele\vtinha.\fIsso me confundiu\npor completo.",
  ["49:ea00"] = "m POKéMONS na\vclasse!",
  ["4a:4613"] = "ROTA 26\fLIGA POKéMON\fPORTÃO DE\nRECEPÇÃO.",
  ["4a:486a"] = "Ei!",
  ["4a:4870"] = "Sabe o que acabou\nde fazer?\fVocê deu seu\nprimeiro passo em\vKANTO.\fOlhe o MAPA da sua\nPOKé GEAR e\vconfira.",
  ["4a:4955"] = " Eu só\nqueria falar\valgo legal.",
  ["4a:4c7e"] = "CACHOEIRA DE TOHJO\fA conexão entre\nos continentes\vKANTO e JOHTO.",
  ["4a:4d53"] = "ROTA 28.",
  ["4a:4ed2"] = "POKéMON se\nescondem no mato.\fNunca se sabe\nquando saltam…",
  ["4a:4f0a"] = "Já te vi umas\nvezes. Quantos\fPOKéMON você já\npegou?\fQuer que eu mostre\ncomo pegar\vPOKéMON?",
  ["4a:4f78"] = "É assim que se\nfaz.\fSe enfraquecer\nantes, o POKéMON\vé mais fácil.",
  ["4a:4fc2"] = "Ah. Tudo bem.\fEnfim, se quer\npegar POKéMON,\fvocê tem que\nandar bastante.",
  ["4a:500e"] = "Hã? Quer que eu\nmostre como\vpegar POKéMON?",
  ["4a:503f"] = "E aí. Como estão\nseus POKéMON?\fSe estão fracos\ne sem preparo,\ffique fora do\nmato.",
  ["4a:5097"] = "Viu aqueles\nbarrancos? Dá medo\vpular deles.\fMas dá para ir a\nNEW BARK sem\fpassar pelo\nmato.",
  ["4a:5104"] = "Quis dar uma\npausa, e salvei\fpara guardar meu\nprogresso.",
  ["4a:5177"] = "Estou esperando\nPOKéMON que\fsó aparecem à\nnoite.",
  ["4a:51a7"] = "Estou esperando\nPOKéMON que\fsó aparecem de\nmanhã.",
  ["4a:51dd"] = "TUSCANY: Creio eu\nque esta é a\fprimeira vez que\nnos vemos?\fPermita-me que eu\nme apresente.\fSou TUSCANY, de\nterça-feira.",
  ["4a:5200"] = "z que nos encotramos?\fPermita que eu me apresente a você.\fEu sou TUSCANY da Terça.",
  ["4a:525a"] = "Como apresentação,\naceite este\fpresente, um\nPINK BOW.",
  ["4a:529a"] = "TUSCANY: Não acha\nque ele é mesmo\vadorável?\fEle fortalece\nataques normais.\fTenho certeza que\nserá útil.",
  ["4a:5312"] = "TUSCANY: Conhece\nMONICA, minha\virmã mais velha?\fOu meu irmão\ncaçula, WESLEY?\fSou a segunda de\nsete filhos.",
  ["4a:5384"] = "TUSCANY: Hoje não\né terça-feira.\vQue pena…",
  ["4a:53b9"] = "ROUTE 29\fCHERRYGROVE CITY -\nNEW BARK TOWN",
  ["4a:53e4"] = "ROUTE 29\fCHERRYGROVE CITY -\nNEW BARK TOWN",
  ["4a:55ad"] = "Vai, RATTATA!\fTACKLE!",
  ["4a:55c3"] = "O quê? Esta é uma\nbatalha séria!\vMe deixe em paz!",
  ["4a:5600"] = "lha e agora\vestou procurando\vPOKéMONS.\fAh! Você é novato!\nVamos batalhar!",
  ["4a:57f0"] = "A casa do\nMR.POKéMON? Fica\vum pouco adiante.",
  ["4a:581a"] = "Todo mundo se\ndiverte lutando!\vFaça o mesmo!",
  ["4a:584a"] = "Não sou treinador\fMas se olhar nos\nolhos de um,\vprepare-se.",
  ["4a:5891"] = "ROUTE 30\fVIOLET CITY -\nCHERRYGROVE CITY",
  ["4a:58ba"] = "CASA DO MR.POKéMON\nEm frente!",
  ["4a:58db"] = "LAR DE MR.POKéMON",
  ["4a:58ec"] = "DICA AO TREINADOR\fNão roube POKéMON\ndos outros!\fPOKé BALLS só se\njogam em POKéMON\vselvagens!",
  ["4a:5b1e"] = "DARK CAVE…\fSe um POKéMON\niluminasse, eu\vexploraria.",
  ["4a:5bf8"] = "… Hnnn… Hã?\fAndei demais hoje\nprocurando\vPOKéMON.\fMeus pés doem e\nestou com sono…\fSe eu fosse um\nPOKéMON selvagem,\vseria fácil…\f…Zzzz…",
  ["4a:5c80"] = "…Zzzz… Hã?\fO que é isso? Tem\nMAIL para mim?",
  ["4a:5caf"] = "{PLAYER} entregou\no POKéMON que\vsegurava a MAIL.",
  ["4a:5cd9"] = "Vejamos…\f…DARK CAVE leva\na outra estrada…\fBom saber\ndisso.\fObrigado por\ntrazer isto.\fMeu amigo é gente\nboa, e você\vtambém é!\fQuero fazer algo\nde bom em troca\vtambém!\fJá sei! Quero que\nfique com isto!",
  ["4a:5dbb"] = "TM50 é NIGHTMARE.\fÉ um golpe cruel\nque rói devagar\fo PS de um inimigo\nadormecido.\fOoooh…\nQue medo…\fNão quero ter\npesadelos.",
  ["4a:5e46"] = "Esta MAIL não é\npara mim.",
  ["4a:5e5e"] = "Por que este\nPOKéMON é raro?\fEle não tem\nMAIL nenhuma.",
  ["4a:5e97"] = "O quê? Você não\nquer nada?",
  ["4a:5eb6"] = "Se eu levar esse\nPOKéMON de você,\fo que vai usar\nna batalha?",
  ["4a:5efa"] = "Achei um bom\nPOKéMON na DARK\vCAVE.\fVou criar ele\npara encarar o\vFALKNER.\fEle é o líder do\nGINÁSIO de VIOLET",
  ["4a:5f6a"] = "ROUTE 31\fVIOLET CITY -\nCHERRYGROVE CITY",
  ["4a:5f93"] = "DARK CAVE",
  ["4a:875b"] = "ha possa\vmudar as coisas\vpara mim.",
  ["4a:9749"] = " fique\nconvencido, a\vKATE é poderosa!",
  ["4a:a000"] = " nariz!",
  ["4a:ab41"] = "Eu conheço minhas\nfraquezas.",
  ["4a:c800"] = ", eu\vacalmo os meus\vnervos!",
  ["4a:d100"] = "   Não me atrapalhe.\nEstou segurando\vnum POKéMON\vaquático!",
  ["4b:42a5"] = "Espera aí!\nQual é a pressa?",
  ["4b:42c0"] = "{PLAYER}, né?\nUm cara de óculos\festava procurando\npor você.\fVá ver você mesmo.\nEle espera por\fvocê no CENTRO\nPOKéMON.",
  ["4b:43c5"] = "Você já foi ao\nGINÁSIO POKéMON?\fDá para testar seu\nPOKéMON e você\vmesmo lá.\fÉ um rito de\npassagem para todo\vtreinador!",
  ["4b:4400"] = "N\vno GINÁSIO.\fTodos treinadores\nprecisam ir até\vlá!",
  ["4b:443a"] = "Você tem bons\nPOKéMON aí.\fDeve ser do treino\nque você deu\fneles por\nVIOLET CITY.\fO treino no\nGINÁSIO deve ter\fajudado bastante.\nSem dúvida.\fComo lembrança de\nVIOLET CITY, leve\visto.\fAumenta a força\ndos ataques de\vplanta.",
  ["4b:452a"] = "O que viveu em\nVIOLET CITY\fdeve ser útil na\nsua jornada.",
  ["4b:456e"] = "Que tal levar\nesta gostosa e\fnutritiva\nSLOWPOKETAIL?\fPara você agora,\nsó ¥1.000.000!\fVai querer!",
  ["4b:45e4"] = "Tsc! Pensei que\na molecada de hoje\vtinha dinheiro…",
  ["4b:4600"] = "hoje eram\vricos…",
  ["4b:4611"] = "Não quer? Então\nfora daqui. Xô!",
  ["4b:4bc0"] = "WROOOAR!\nGENTE FOGE QUANDO\fEU RUJO! MAS VOCÊ\nVEIO ATRÁS!\fISSO ME AGRADA!\nAGORA PEGUE ISTO!",
  ["4b:4c19"] = "WROOOAR!\nÉ O ROAR!\fATÉ POKéMON FOGEM\nDE UM BOM ROAR!",
  ["4b:4c4e"] = "FRIEDA: Oba!\nÉ sexta-feira!\fSou a FRIEDA de\nsexta!\fPrazer!",
  ["4b:4c91"] = "Aqui, um POISON\nBARB para você!",
  ["4b:4caf"] = "FRIEDA: Dê a um\nPOKéMON que tenha\vataques venenosos\fOh!\fÉ cruel!\fVai se espantar\ncom o quanto\vmelhora eles!",
  ["4b:4d27"] = "FRIEDA: Oi! Que\ndia você gosta?\fAmo sexta-feira.\nSem dúvida!\fVocê não acha\nótimo também?",
  ["4b:4d8c"] = "FRIEDA: Hoje não\né sexta-feira?\fÉ tão sem graça\nquando não é!",
  ["4b:4dc7"] = "ROUTE 32\fVIOLET CITY -\nAZALEA TOWN",
  ["4b:4deb"] = "RUINS OF ALPH\nENTRADA LESTE",
  ["4b:4e08"] = "UNION CAVE\nEm frente",
  ["4b:503e"] = "ROTA 33.",
  ["4b:54ea"] = "Quem está aí?\nE quem você é?",
  ["4b:550f"] = "Você é poderoso,\ngarotinho!",
  ["4b:552a"] = "Sim, não vi nada\nerrado hoje.\fVocê é bom, fique\nfora de encrencas!",
  ["4b:5570"] = "Estou patrulhando\nà procura de\vpessoas suspeitas.",
  ["4b:5800"] = "orte. Eu não\vtive chance.\fEi! Você merece\nisso.",
  ["4b:58b1"] = "ROTA 34\fCIDADE GOLDENROD-\nCIDADE AZALEA.\fFLORESTA ILEX\nEntre algum lugar.",
  ["4b:58f6"] = "DICAS DO TREINADOR\fNovos Grãos nascem\nem árvores todo\vdia.\fLembre-se dos\nGRÃOS gerados por\vcada árvore.",
  ["4b:5946"] = "s por\vcada árvore.",
  ["4b:595a"] = "CRIATÓRIO POKéMON \fNos deixe treinar\nseus POKéMONS!",
  ["4b:6037"] = "Perigos espreitam\nà noite!",
  ["4b:6053"] = "Droga!",
  ["4b:605c"] = "Você sabe que à\nnoite é pura\vadrenalina,\vnão é?\fMas não se exceda!",
  ["4b:60a3"] = "Seu POKéMON\nparece forte.\fVocê pode ir à\ntodo lugar com\vsegurança!",
  ["4b:60e1"] = "ROTA 35.",
  ["4b:6321"] = "É uma árvore\nestranha. Usar o\vPOTE SQUIRT?",
  ["4b:6346"] = "{PLAYER} usou o\nPOTE SQUIRT.",
  ["4b:6360"] = "Aquela árvore não\ngosta do POTE\vSQUIRT!\fA árvore estranha\natacou!",
  ["4b:63a7"] = "Wa-hey!\fEu ia destruir\naquela árvore\fcom a força dos\nmeus braços.\fMas não consegui!\nQue fiasco!",
  ["4b:6408"] = "Você destruiu\naquela árvore\vvelha?\fIsso é muito\nlegal! \fLeve isso aqui.",
  ["4b:6464"] = "Aparenta ser o\nQUEBRA PEDRA.\fVocê pode quebrar\npedras com um\vsimples uso de\vforça.\fSe tiver pedras\nno seu caminho,\vapenas dê um fim\vnelas!",
  ["4b:64f0"] = "Uma árvore rara\nestá na rota para\va CIDADE GOLDEN-\vROD.\fEla me impede de\nfazer compras.\fAlgo deve ser\nfeito acerca\vdisto.",
  ["4b:6568"] = "Aquela árvore\ndesapareceu sem\vnenhum rastro.\fOh! A árvore era\nmesmo um POKéMON?",
  ["4b:6600"] = " pudesse\vcontar o que meu\voponente pensa.",
  ["4b:66cc"] = "ARTHUR: Quem é\nvocê?\fEu sou ARTHUR da\nQuinta.",
  ["4b:66f9"] = "Ei. Leve isso com\nvocê.",
  ["4b:6713"] = "ARTHUR: Um POKéMON\nque usa golpes do\vtipo pedra deve\vsegurar isto.\fEle melhora\nos ataques do tipo\vpedra.",
  ["4b:6776"] = "ARTHUR: Eu sou\nARTHUR da Quinta.\fFui o segundo a\nnascer de sete\vcrianças.",
  ["4b:67bf"] = "ARTHUR: Hoje não\né Quinta. Que\vtristeza.",
  ["4b:67f0"] = "ROTA 36.",
  ["4b:67fa"] = "RUÍNAS ALFA\nENTRADA NORTE.",
  ["4b:6818"] = "DICAS DO TREINADOR\fO estado dos\nPOKéMONS variam,\vmesmo em espécies\vdiferentes. Seus\vestados podem ser\vparecidos a\vprincípio, porém,\vas diferenças\vficarão aparentes\vquando eles\vcrescerem.",
  ["4b:68ba"] = "DICAS DO TREINADOR\fUse CAVAR para\nretornar à entrada\vde qualquer lugar.\fÉ bem conveniente\npara explorar\vcavernas e pontos\vturísticos.",
  ["4b:9000"] = "paz jovem\ncomo você deveria\vnadar.\fNão SURFE em cima\ndo seu POKéMON.",
  ["4b:9700"] = "s me\nmantém fora do\valcance daquela\vilha.",
  ["4b:c600"] = "\fSe os tipos\nforem diferentes,\fum POKéMON mais\nalto pode perder.\fSaiba quais tipos\nsão fortes e\ffracos contra o\ntipo do seu.",
  ["4b:c957"] = "ro?",
  ["4b:ca00"] = "e\vPOKéMONS pássaros\vlendários?",
  ["4b:cc00"] = "S, e eu\vposso ver que você\vé também.",
  ["4b:d24a"] = "isa que já\vme aconteceu\vfoi descobrir\vPOKéMONS.",
  ["4b:d346"] = "espeito.",
  ["4b:da00"] = "gares\ndesconhecidos e\vconheça pessoas…\fEstes são\nmotivos para\vviajar.",
  ["4b:e755"] = "ia.\fQuando jovem, fui\na JOHTO para\vtreinar.\fVocê se parece\nmuito comigo,\vquando eu era\vapenas um jovem.\fEi. Quero que\nfique com este\vitem.\fAchei em JOHTO.",
  ["4c:422d"] = "SUNNY: Oi! Eu sou\nSUNNY do Domingo.\fIsso significa\nque hoje é\vDomingo!",
  ["4c:4269"] = "Me disseram para\nte dar isso se eu\vte visse.",
  ["4c:4294"] = "SUNNY: Aquela\ncoisa…\fHum…\f… O que era\naquilo…\f…\fOh! Agora eu\nlembrei!\fUm POKéMON que\nsabe golpes\velétricos deve\vsegurar isso.\fMinha irmã MÔNICA\ndisse que isso\vmelhora golpes do\vtipo elétrico!",
  ["4c:4300"] = "e que isso\vmelhora golpes do\vtipo elétrico!",
  ["4c:4336"] = "SUNNY: Meus irmãos\nsão: MÔNICA,\vTUSCANY, WESLEY,\vARTHUR, FRIEDA e\vSANTOS.\fTodos eles são\nmais velhos que\veu!",
  ["4c:43a8"] = "SUNNY: Hoje não\né Domingo? Hum…\vEu esqueci!",
  ["4c:43d1"] = "ROTA 37.",
  ["4c:48b2"] = "ROTA 38\fCIDADE OLIVINE-\nCIDADE ECRUTEAK.",
  ["4c:48d9"] = "DICAS DO TREINADOR\fSe seu POKéMON\nestá tentando\vevoluir, você pode\vimpedi-lo.\fAperte o botão B\ndurante a\vevolução.\fIsso assustará\no POKéMON e o\vimpedirá de\vevoluir.",
  ["4c:495a"] = "hoje.",
  ["4c:4d5a"] = "ROTA 39\fCIDADE OLIVINE-\nCIDADE ECRUTEAK.",
  ["4c:4d81"] = "FAZENDA MOOMOO\fAprecie Nosso\nLeite Delicioso e\vFresquinho!",
  ["4c:4dad"] = "DICAS DO TREINADOR\fUse a CABEÇADA nas\nárvores para\vagitá-las e fazer\vum POKéMON cair. \fDiferentes tipos\nde POKéMONS\vcairão das\várvores.\fUse a CABEÇADA em\ntoda árvore que\vavistar!",
  ["4c:5183"] = "Embora você não\nconsiga ver daqui,\vCIANWOOD está após\vo mar.",
  ["4c:51c4"] = "MÔNICA: Fico feliz\nem conhecê-lo.\vEu sou MÔNICA da\vSegunda.",
  ["4c:51f4"] = "Como prova da\nnossa amizade, eu\vlhe darei um\vpresente.",
  ["4c:522a"] = "MÔNICA: É um\nitem que melhora o\vpoder dos golpes\vdo tipo voador.\fVocê deve equipar\num POKéMON pássaro\vcom este item.",
  ["4c:529a"] = "MÔNICA: Meus\nirmãos estão em\vtodos os lugares.\fTente achar todos\neles!",
  ["4c:52f5"] = "MÔNICA: Eu acho\nque hoje não é\vSegunda. Que pena…",
  ["4c:5300"] = " horrível.",
  ["4c:5325"] = "ROTA 40\fCIDADE CIANWOOD-\nCIDADE OLIVINE.",
  ["4c:5648"] = "\fEu vi esse\ngigante POKéMON\vvoando nas ilhas.\fEstavam espalhadas\npenas das suas\vasas prateadas.",
  ["4c:5700"] = "s me\nmantém fora do\valcance daquela\vilha.",
  ["4c:5955"] = "onheço algo\nbom!\fO leite da FAZENDA\nMOOMOO é famoso\vpelo sabor.",
  ["4c:5dee"] = "ROTA 42\fCIDADE ECRUTEAK-\nCIDADE MAHOGANY.",
  ["4c:5e16"] = "MONTANHA MORTEIRO\fCAVERNA com\nCACHOEIRAS dentro.",
  ["4c:5e3a"] = "MONTANHA MORTEIRO\fCAVERNA com\nCACHOEIRAS dentro.",
  ["4c:5e57"] = "       ROTA 42\fCIDADE ECRUTEAK-\nCIDADE MAHOGANY.",
  ["4c:9200"] = "reino\nPOKéMONS?\fPorque eles estão\nlá!",
  ["4c:9300"] = "o.",
  ["4c:c34f"] = "ém o\nCOME SONHOS\f…\fZzz…",
  ["4c:ca41"] = "gar…   \fBom, o que você\nquer? Quer me\vdesafiar ou é\voutra coisa?\f…Eu odeio dizer\nisso, mas estou\vsem ânimo para\vbatalhar agora.\fDê uma olhada ao\nseu redor…\fUm vulcão entrou\nem eurupcão, e\visso fez uma\vcidade inteira\vdesaparecer.\fNós podemos vencer\ne perder com os\vPOKéMONS.\fSe não ficarmos\natentos, podemos\vperder em um\vsegundo.\f…\fAs coisas\nfuncionam desse\vmodo…\fMas, eu ainda sou\num treinador.\fSe eu vir um\noponente forte,\vfico com vontade\vde batalhar.\fSe quiser batalhar\ncomigo, venha ao\vGINÁSIO DE\vVERIDIANA.\fLá eu aceitarei\no seu desafio.",
  ["4c:cd4c"] = "ais\nleve na água.",
  ["4c:df00"] = "ound para\ntodos.\fCASA DE JOGOS DE\nCELADON.",
  ["4c:e100"] = "tes locais,\vo CAMINHO\vSUBTERRÃNEO foi\vselado por tempo\vindeterminado.\fPOLÍCIA DE\nCELADON.",
  ["4d:435c"] = "-me\vcontar a você!",
  ["4d:456f"] = "ROTA 43\fLAGO DA RAIVA-\nCIDADE MAHOGANY.",
  ["4d:4596"] = "ROTA 43\fLAGO DA RAIVA-\nCIDADE MAHOGANY.",
  ["4d:45bd"] = "DICAS DO TREINADOR\fTodos POKéMONS têm\nvantagens\ve desvantagens\vdependendo do seu\vtipo.\fVocê pode vencer\num POKéMON de\vnível maior usando\vo tipo adequado.\fSaiba os tipos que\nsão fortes ou\vfracos contra o\vseu POKéMON.",
  ["4d:4900"] = "a\vgrande.\fEu juro, ele tinha\nuns 5 metros de\valtura!",
  ["4d:4c00"] = "S, e eu\vposso ver que você\vé também.",
  ["4d:4d96"] = "ROTA 44\fCAMINHO DE GELO\nacima.",
  ["4d:4daf"] = "ROTA 44\fCIDADE MAHOGANY-\nVILA BLACKTHORN",
  ["4d:5256"] = "e aconteceu\vfoi descobrir\vPOKéMONS.",
  ["4d:5490"] = "ROTA 45\nMONTANHAS NA\vFRENTE.",
  ["4d:57aa"] = "ROTA 46\nMONTANHAS NA\vFRENTE",
  ["4d:588a"] = "Você visitou o\nGINÁSIO PEWTER?\fO LÍDER usa\nPOKéMONS do tipo\vpedra.",
  ["4d:58c8"] = "A noite, CLEFAIRYS\nvêm brincar fora\vdo MONTE LUA.\fMas nem sempre.",
  ["4d:590e"] = "Oh, você percorreu\na distância de\vJOHTO até aqui?\fIsto melhora a\nmemória.\fQuando jovem, fui\na JOHTO para\vtreinar.\fVocê se parece\nmuito comigo,\vquando eu era\vapenas um jovem.\fEi. Quero que\nfique com este\vitem.\fAchei em JOHTO.",
  ["4d:59f2"] = "Vá a novos lugares\ndesconhecidos e\vconheça pessoas…\fEstes são\nmotivos para\vviajar.",
  ["4d:5a47"] = "CIDADE PEWTER\fA Cidade Da Pedra\nCinza.",
  ["4d:5a66"] = "CIDADE PEWTER\fLÍDER DO GINÁSIO\nPOKéMON: BROCK\fO Treinador Dos\nPOKéMONS Sólidos.",
  ["4d:5aa6"] = "Há um aviso\naqui…\fO MUSEU DE CIÊNCIA\nDE PEWTER está\vfechado para\vreformas…",
  ["4d:5af1"] = "Há um aviso aqui…\n \fA LOJA DE\nPRESENTES está\vaberta!",
  ["4d:5b24"] = "Bem-vindo a\nCIDADE PEWTER!",
  ["4d:5d80"] = "ROTA 2\fCIDADE VERIDIANA-\nCIDADE PEWTER.",
  ["4d:5da5"] = "CAVERNA DO\nDIGLETT.",
  ["4d:8300"] = "veio este\nTM?\fIsto é\nfantasmagórico!\fEi, pode ficar\ncom este TM.",
  ["4d:8944"] = "scaria…",
  ["4d:9549"] = "\npéssimo nisso.\fEu só espirro\nágua por todos os\vcantos.",
  ["4d:c25c"] = "de\vaprender isso na\vminha aula de\vjaponês.",
  ["4d:ce00"] = "amos fazer uma\nbatalha justa!",
  ["4d:d443"] = "blema na USINA\vDE ENERGIA for\vresolvido.",
  ["4d:d656"] = "m\vuma batalha.\fTenho certeza que\nas INSÍGNIAS dos\vGINÁSIOS de KANTO\vvão ajudá-lo.",
  ["4d:d700"] = "E\vSURGE\fO Trovão\nAmericano.",
  ["4d:d841"] = "roblema na USINA\vDE ENERGIA for\vresolvido.",
  ["4d:dc50"] = " primeira vez\vme deixa muito\vancioso.",
  ["4d:e200"] = "CONFUSÃO!",
  ["4e:4062"] = "Ei, garoto! Acabo\nde tomar duas\vdoses de café e\vestou sem sono.\fPreciso falar com\nalguém, pode ser\vcom você mesmo.\fPode não parecer,\nmas já fui um\vperito em capturar\vos POKéMONS.\fVocê acredita\nem mim?",
  ["4e:412c"] = "Bom, bom. Sim, eu\nera algo fora do\vcomum, deixe-me\vcontar a você!",
  ["4e:4174"] = "O quê?\nSeu pirralho!\fSe eu fosse um\npouco mais jovem,\veu lhe mostraria\vumas coisas!",
  ["4e:41ce"] = "Este GINÁSIO, não\ntinha LÍDER até\vrecentemente.\fUm jovem de PALLET\nse tornou LÍDER,\vmas ele sempre\vviaja.",
  ["4e:423b"] = "Vai batalhar com\no LÍDER?\fBoa sorte, pois\nvocê vai precisar.",
  ["4e:4281"] = "Uah! Devo ter\ncochilado no sol.\f…Tive um sonho\nque um DROWNZEE\vcomia o meu sonho.\fMisterioso, hein?\fHã? O que é isto?\fDe onde veio este\nTM?\fIsto é\nfantasmagórico!\fEi, pode ficar\ncom este TM.",
  ["4e:4343"] = "O TM42 contém o\nCOME SONHOS\f…\fZzz…",
  ["4e:4367"] = "Ouvi dizer que\nhá muitos itens no\vchão da FLORESTA\vDE VERIDIANA.",
  ["4e:43ac"] = "CIDADE VERIDIANA\fO Paraíso\nEternamente Verde.",
  ["4e:43d8"] = "CIDADE VERIDIANA\fLÍDER DO GINÁSIO\nPOKéMON: …\fO resto do texto\né ilegível…",
  ["4e:441d"] = "Bem-vindo a\nCIDADE VERIDIANA,\vo portal do\vPLANALTO ÍNDIGO.",
  ["4e:4456"] = "CASA DO TREINADOR\fO Clube Para\nGrandes Batalhas.",
  ["4e:44fc"] = "LIGA POKéMON\fENTRADA DA ESTRADA\nDA VITÓRIA.",
  ["4e:4650"] = "ROTA 1\fCIDADE PALLET-\nCIDADE VERIDIANA.",
  ["4e:46c2"] = "Estou criando\nPOKéMONS também.\fEles servem como\nseguranças.",
  ["4e:46fb"] = "A tecnologia é\nincrível!\fVocê pode trocar\nPOKéMONS através\vdo tempo como\ve-mail.",
  ["4e:4746"] = "CIDADE PALLET \fLocal Calmo de Paz\ne Pureza.",
  ["4e:4778"] = "CASA DO ASH.",
  ["4e:4785"] = "LABORATÓRIO DE\nPESQUISA DO\vPROFESSOR CARVA-\vLHO.",
  ["4e:479c"] = "CASA DO GARY.",
  ["4e:4900"] = "r!\fVamos batalhar!",
  ["4e:49a7"] = "Quem é você?\fBem, é óbvio que\nvocê é um\vtreinador…\fMeu nome é GARY.\fEu já fui o\nCAMPEÃO, mas foi\vpor pouco tempo…\fAquele intrometido\ndo ASH tomou o\vmeu lugar…   \fBom, o que você\nquer? Quer me\vdesafiar ou é\voutra coisa?\f…Eu odeio dizer\nisso, mas estou\vsem ânimo para\vbatalhar agora.\fDê uma olhada ao\nseu redor…\fUm vulcão entrou\nem eurupcão, e\visso fez uma\vcidade inteira\vdesaparecer.\fNós podemos vencer\ne perder com os\vPOKéMONS.\fSe não ficarmos\natentos, podemos\vperder em um\vsegundo.\f…\fAs coisas\nfuncionam desse\vmodo…\fMas, eu ainda sou\num treinador.\fSe eu vir um\noponente forte,\vfico com vontade\vde batalhar.\fSe quiser batalhar\ncomigo, venha ao\vGINÁSIO DE\vVERIDIANA.\fLá eu aceitarei\no seu desafio.",
  ["4e:4c48"] = "Tem um aviso aqui…\fO GINÁSIO CINNABAR\nse mudou para as\vILHAS SEAFOAM.\fBLAINE.",
  ["4e:4c97"] = "ILHA CINNABAR\fA Cidade Quente\ndo Ardente Desejo.",
  ["4e:4e97"] = "O que essa placa\ndiz?\fGINÁSIO CINNABAR\nLÍDER: BLAINE.",
  ["4e:5100"] = "AS SEAFOAM…\fNossa, meu\nnamorado é um\vhomenzarrão!\fQue tolo!",
  ["4e:51da"] = "Perdão. A estrada\nestá fechada para\vobras.\fSe quiser ir à\nCINNABAR, é melhor\vvocê ir pelo sul\vda CIDADE PALLET.",
  ["4e:524f"] = "Eu estou todo\nsuado. Hora de\vnadar!",
  ["4e:5270"] = "Quem sabe quanto\ntempo eu levaria\vpara mover esta\vpedra…",
  ["4e:52a8"] = "A obra da estrada\nfinalmente acabou.\fAgora eu posso ir\npescar de novo.",
  ["4e:52e7"] = "ROTA 19\fCIDADE FUCHSIA-\nILHAS SEAFOAM.",
  ["4e:5310"] = "Tome cuidado se\nestiver indo nadar\vaté as ILHAS\vSEAFOAM.\fPOLÍCIA DE\nFUCHSIA.",
  ["4e:53eb"] = "Uma pessoa da\nELITE QUATRO era\vo LÍDER DO GINÁSIO\vDE FUCHSIA.",
  ["4e:5429"] = "A filha de KOGA\no sucedeu como\vLÍDER DO GINÁSIO\vdepois de entrar\vna ELITE QUATRO.",
  ["4e:5479"] = "A ZONA DO SAFARI\nestá fechada…\fÉ triste, sabendo\nque é a principal\vatração de\vFUCHSIA.",
  ["4e:54c8"] = "CIDADE FUCHSIA\fObserve! É a\nPaixão Rosa!",
  ["4e:54f0"] = "CIDADE FUCHSIA\fLÍDER DO GINÁSIO\nPOKéMON: JANINE\fA Venenosa Mestra\nNinja.",
  ["4e:5531"] = "Há um aviso aqui…\fO ESCRITÓRIO DA\nZONA DO SAFARI\vestará fechado até\vsegunda ordem.",
  ["4e:557b"] = "ZONA DO SAFARI\nCASA DO DIRETOR.",
  ["4e:5596"] = "O DIRETOR está\nviajando afora.\fPortanto, a ZONA\nDO SAFARI estará\vfechada.",
  ["4e:55dd"] = "Não bagunce.\fPor favor, leve\nseu lixo com você.",
  ["4e:57c8"] = "ROTA 18\fCIDADE CELADON-\nCIDADE FUCHSIA.",
  ["4e:5aa6"] = "ESTRADA DE\nCICLISMO.\fSempre Inclinada!",
  ["4e:5b3a"] = "Este POLIWRATH é\nmeu amigo.\fEu me pergunto se,\nele evoluirá num\vsapo POKéMON.",
  ["4e:5b9b"] = "Eu perdi novamente\nnestas máquinas…\fNós meninas,\ntambém jogamos.\fVocê deve checá-\nlas também.",
  ["4e:5c00"] = "Os GRIMERS\ntêm aparecido\vultimamente.\fVeja aquela lagoa\nem frente à esta\vcasa.\fOs GRIMERS vivem\nlá agora.\fDe onde será que\nvieram?\fIsto é um problema\nsério…",
  ["4e:5c99"] = "Uau! Este GINÁSIO\né ótimo!\fSó meninas podem\nentrar!",
  ["4e:5cd2"] = "Quer saber um\nsegredo?\fA MANSÃO de\nCELADON tem porta\vnos fundos.",
  ["4e:5d00"] = "porta\vnos fundos.",
  ["4e:5d12"] = "Estão realizando\numa competição lá\vno restaurante.\fSó vou assistir,\nou irei sair de lá\vbem gordo…",
  ["4e:5d7a"] = "A LOJA DE\nDEPARTAMENTOS DE\vCELADON possui a\vmelhor seleção de\vmercadorias.\fSe você não\nencontrar lá, não\vachrá em nenhum\voutro lugar.\fEstou falando como\nvendedor.",
  ["4e:5e18"] = "Olhar para o chão\nenquanto caminho\vme faz ficar\vtonta.",
  ["4e:5e52"] = "CIDADE CELADON\fA Cidade Dos\nSonhos Arco-íris.",
  ["4e:5e7b"] = "CIDADE CELADON\fLÍDER DO GINÁSIO\nPOKéMON: ERIKA\fA Princesa Amante\nda Natureza.",
  ["4e:5ebb"] = "Encontre o que\nprocura na LOJA de\vCELADON!",
  ["4e:5ee6"] = "MANSÃO CELADON.",
  ["4e:5ef7"] = "O playground para\ntodos.\fCASA DE JOGOS DE\nCELADON.",
  ["4e:5f2a"] = "DICAS DO TREINADOR\fA SUPER DEFESA\nprotege os\vPOKéMONS de\vataques ESPECIAIS\vcomo de água e de\vfogo.\fCompre seus itens\nna LOJA DE\vDEPARTAMENTOS DE\vCELADON!",
  ["4e:5f4d"] = "a.",
  ["4e:6081"] = "O que é esse\naviso?\f… Treinadores\nrudes estão\vfazendo batalhas\vno CAMINHO\vSUBTERRÂNEO.\fDevido ao número\nde queixas dos\vresidentes locais,\vo CAMINHO\vSUBTERRÃNEO foi\vselado por tempo\vindeterminado.\fPOLÍCIA DE\nCELADON.",
  ["4e:614f"] = "A porta está\ntrancada…",
  ["4e:9151"] = "ão queria\nperder…",
  ["4e:a158"] = " mas\vparece divertido.",
  ["4e:d84f"] = "em CERULEANA!",
  ["4e:e54d"] = "Qsrei\num segredo.\fMas primeiro, nós\nbatalharemos!",
  ["4f:4300"] = "ansar um\vpouco.",
  ["4f:437c"] = "ROTA 15\fCIDADE FUCHSIA-\nCIDADE LAVANDA.",
  ["4f:4921"] = "DICAS DO TREINADOR\fOlhe! Bem ali, ao\nlado esquerdo do\vposto.",
  ["4f:4960"] = "ROTA 13\fAo NORTE, PONTE DO\nSILÊNCIO.",
  ["4f:4982"] = "Ao NORTE, CIDADE\nLAVANDA.\fAo OESTE, CIDADE\nFUCHSIA.",
  ["4f:4c40"] = "rou de\vfuncionar.",
  ["4f:4cf7"] = "ROTA 12\fAo NORTE, CIDADE\nLAVANDA.",
  ["4f:4d18"] = "PONTO DE PESCA.",
  ["4f:4fc6"] = "ROTA 11.",
  ["4f:5048"] = "Existem muitos\nprédios, não é?\fEssa é a TORRE DE\nRÁDIO DE KANTO.",
  ["4f:5080"] = "O continente\nKANTO tem muitos\vprogramas de\vrádio de ótima\vqualidade.",
  ["4f:50a2"] = "As pessoas vêm de\ntodos as lugares\vpara pagar devotos\vàs almas de\vPOKéMONS.",
  ["4f:50f2"] = "Para acordar\nPOKéMONS adormeci-\vdos, você deve ter\va POKé FLAUTA. \fTodo treinador tem\nque saber disso!",
  ["4f:513d"] = "CIDADE LAVANDA\fA Nobre Cidade\nRoxa.",
  ["4f:5162"] = "ESTAÇÃO DE RÁDIO\nDE KANTO\fSeus Programas\nFavoritos No Ar\vo Dia Todo!",
  ["4f:51a7"] = "VOLUNTÁRIO DE\nLAVENDER\fCASA DOS POKéMONS.",
  ["4f:51c6"] = "CASA DA ALMA\fDeixe as Almas\ndos POKéMONS\vDescansarem em\vPaz.",
  ["4f:5308"] = "O PORTO DE\nVERMILION é a rota\vlitorânea do\vcotinente KANTO.\fLuxuosos navios de\ntodo o mundo vêm\vpara cá.",
  ["4f:5362"] = "Meu POKéMON está\npreparando o\vterreno para a\vconstrução.\fMas eu não tenho\ndinheiro para\viniciar o projeto…",
  ["4f:53d5"] = "O MACHOP rosna\nenquanto achata a\vsuperfície.",
  ["4f:5400"] = "ície.",
  ["4f:540d"] = "Existem oito\nGINÁSIOS em KANTO.\fEsta grande\nconstrução é o\vGINÁSIO POKéMON\vde VERMILION.",
  ["4f:5457"] = "O SNORLAX está\ndormindo em paz…",
  ["4f:5477"] = "A POKéGEAR foi\ncolocada em\vfrente ao SNORLAX\vdorminhoco…\f… O SNORLAX\nacordou!",
  ["4f:54bb"] = "Treinadores\nhabilidosos se\vreúnem em KANTO.\fOs líderes de\nGINÁSIO são muito\vfortes.\fNão será nada\nfácil derrotá-los.",
  ["4f:551e"] = "Você começou a\ncolecionar as\vINSÍGNIAS dos\vGINÁSIOS de KANTO?\fEstá achando os\ntreinadores daqui\vbem poderosos?",
  ["4f:557b"] = "Eu acho que\nem breve você\vconquistará todos\vos GINÁSIOS de\vKANTO.\fDeixe me saber se\nvocê colecionou\vtodas as oito\vINSÍGNIAS.",
  ["4f:55e6"] = "Parabéns!\fVocê colecionou\ntodas as INSÍGNIAS\vdos GINÁSIOS de\vKANTO.\fEu vou\nrecompensá-lo pelo\vseus esforços.",
  ["4f:563d"] = "Ter uma variedade\nde tipos de\vPOKéMONS deve lhe\vdar vantagens em\vuma batalha.\fTenho certeza que\nas INSÍGNIAS dos\vGINÁSIOS de KANTO\vvão ajudá-lo.",
  ["4f:56ac"] = "CIDADE VERMILION\fO Porto dos Raros\nPôr-do-Sóis.",
  ["4f:56da"] = "CIDADE VERMILION\fLÍDER do GINÁSIO\nPOKéMON: TENENTE\vSURGE\fO Trovão\nAmericano.",
  ["4f:5700"] = "E\vSURGE\fO Trovão\nAmericano.",
  ["4f:571b"] = "CLUBE dos FÃS\nPOKéMON \fTodos os FÃS\nPOKéMON são bem\vvindos!",
  ["4f:5741"] = "CAVERNA DO DIGLETT",
  ["4f:5751"] = "PORTO DE VERMILION\nENTRADA.",
  ["4f:5820"] = "A estrada ficará\nfechada até o\vproblema na USINA\vDE ENERGIA for\vresolvido.",
  ["4f:5864"] = "CAMINHO\nSUBTERRÂNEO\fCIDADE CERULEANA-\nCIDADE VERMILION.",
  ["4f:5923"] = "Uma pequena menina\nque é ótima em\vimitar pessoas\vmora aqui.\fEla até\nimita pessoas\vque estiver\vconversando.\fÉ bem confuso.",
  ["4f:59a3"] = "A garota imitadora\nparece infeliz.\fEla disse que\nperdeu sua BONECA\vfavorita-CLEFAIRY.",
  ["4f:59f6"] = "Você veio do\ncontinente JOHTO?\fVocê poderia\nretornar à sua\vcasa se o TRÊM\vMAGNETO estivesse\vfuncionando.",
  ["4f:5a44"] = "Você veio do\ncontinente JOHTO?\fVocê pode retornar\nà sua casa com o\vTRÊM MAGNETO agora\vque ele está\vfuncionando.",
  ["4f:5a94"] = "Eu fui ao GINÁSIO\nquerendo batalhar\vcontra os\vtreinadores…\fEle se virou e eu\ntropecei no\vGINÁSIO sem uso\vacima.\fCara, eu estava\ntão atrapalhado.",
  ["4f:5b24"] = "Esta é a\nCORPORAÇÃO SILPH,\vfamosa pelo seus\vprodutos POKéMON.\fNo passado, a\nEQUIPE ROCKET\vqueria a empresa\vpor esse motivo.",
  ["4f:5b4f"] = "No passado, a\nEQUIPE ROCKET\vqueria a empresa\vpor esse motivo.",
  ["4f:5b92"] = "Chew… Chew…\fSoube que há um\ngrande problema na\vUSINA DE ENERGIA.\fChew… Chew…",
  ["4f:5be1"] = "Chew… Chew…\fSoube que houve um\ngrande problema na\vUSINA DE ENERGIA.\fChew… Chew…\nCansei disso!",
  ["4f:5c3b"] = "Ir a um estádio\npela primeira vez\vme deixa muito\vancioso.",
  ["4f:5c7b"] = "Existe um lugar\nem VERIDIANA\vchamado CASA DO\vTREINADOR, onde\vmuitos treinadores\vse reúnem.",
  ["4f:5cdb"] = "Nossa cidade foi\ndestacada num\vprograma de rádio.\fÉ bom ouvir\nelogios da sua\vcidade, mas é bem\vembaraçoso também.",
  ["4f:5d4d"] = "CIDADE SAFFRON\fO Brilhante Centro\nComercial Dourado.",
  ["4f:5d7c"] = "CIDADE SAFFRON\nLÍDER DO GINÁSIO\vPOKéMON: SABRINA\fA Mestra\ndos POKéMONS\vpsíquicos!",
  ["4f:5dbf"] = "Sejam todos Bem\nVindos!\fGINÁSIO DE LUTA.",
  ["4f:5de0"] = "CORPORAÇÃO SILPH\nSALAS DE\vESCRITÓRIO.",
  ["4f:5dfb"] = "CASA DO SENHOR\nPSÍQUICO.",
  ["4f:5e0f"] = "CIDADE SAFFRON\nESTAÇÃO DO TRÊM\vMAGNETO.",
  ["4f:5f1e"] = "A estrada estará\nfechada até o\vproblema na USINA\vDE ENERGIA for\vresolvido.",
  ["4f:5f62"] = "CAMINHO\nSUBTERRÂNEO\fCIDADE CERULEANA-\nCIDADE VERMILION.",
  ["4f:5f93"] = "O que é isso?\fCasas para vender…\nNinguém mora aqui.",
  ["4f:60b0"] = "A USINA DE ENERGIA\nde KANTO é em\vdireção ao fim da\vROTA 9.\fOcorreu um tipo de\nacidente lá.",
  ["4f:610c"] = "Você está\ncolecionando todos\vos tipos de\vPOKéMONS?\fDeve ser um grande\ndesafio, mas\vparece divertido.",
  ["4f:6170"] = "A PENÍNSULA\nao norte é um\vbom lugar para\vencontros.\fAs garotas adoram!",
  ["4f:61c2"] = "Meu SLOWBRO e eu\nfazemos uma ótima\vcombinação!",
  ["4f:61f1"] = "SLOWBRO, mostre-me\nsua CONFUSÃO!",
  ["4f:6216"] = "Eu sou um grande\nfã do GINÁSIO\vde CERULEANA da\vMISTY.",
  ["4f:623d"] = "Eu vi esse rapaz\nsuspeito indo\vem direção à\vPENÍNSULA DE\vCERULEANA.",
  ["4f:6271"] = "Ali existia uma\ncaverna que dentro\vdela havia um\vPOKéMON com força\vincrível.",
  ["4f:62b6"] = "O quê?\fMeu ACHA ITENS\nestá respondendo…",
  ["4f:62da"] = "CIDADE CERULEANA\fUma Misteriosa\nAura Azul a\vEnvolve.",
  ["4f:630d"] = "CIDADE CERULEANA\fLÍDER do GINÁSIO\nPOKéMON: MISTY\fA Mais Bela\nSereia.",
  ["4f:6349"] = "Há um aviso aqui…\fA LOJA de\nBICICLETAS se\vmudou para a\vCIDADE GOLDENROD\vem JOHTO…",
  ["4f:6394"] = "Tem um aviso aqui…\fAcabar com os atos\ncriminosos e\vtornar a cidade\vum lugar mais\vamigável e alegre!\fPOLÍCIA DE\nCERULEANA.",
  ["4f:6403"] = "PENÍNSULA DE\nCERULEANA ACIMA.",
  ["4f:6418"] = "A porta está\ntrancada.",
  ["4f:9300"] = "narei mais…",
  ["4f:9a4a"] = "igo,\ncara!",
  ["4f:a045"] = " mas\vvocê ganhou mesmo\vassim.\fComo prometi, você\nganhou um prêmio.",
  ["4f:c400"] = "MON do tipo\vAÇO.\fEu não sei muita\ncoisa desse\vPOKéMON.",
  ["4f:c746"] = "escar!?\vIncompreensível!",
  ["4f:d800"] = "ve existir um\ngolpe que o\vPOKéMON use quando\vcongelado.",
  ["50:437d"] = "ROTA 9\fCIDADE CERULEANA-\nT→NEL DE PEDRA.",
  ["50:443b"] = "Ei, garoto!\fEu sou um membro\nda EQUIPE ROCKET!\fEu vim de outro\npaís.\fSou o treinador\nnúmero um!\fEu pensei se,\neu parasse o\vfornecimento de\venergia, as\vpessoas entrariam\vem pânico.\fMinha missão é\nsecreta, e eu não\vvou contar a você!\fMas, se você me\nvencer, eu lhe\vcontarei o\vsegredo.\fEi, garoto!\nA batalha começou!",
  ["50:4574"] = "Arrrgh! Não,\nnão, não posso\vacreditar!\fVocê é forte\ndemais!\fEu não sou páreo\npara ti!",
  ["50:45cd"] = "Certo. Vou\nlhe contar meu\vsegredo.\fA PARTE DA MÁQUINA\nque roubei, está\vescondida no\vGINÁSIO DE\vCERULEANA.\fEu coloquei dentro\nda água.\fOlhe na água\ncentral do\vGINÁSIO.\fGaroto, não me\nesqueça!\fA EQUIPE ROCKET\num dia derrotará\vti. \fMeus amigos virão\nde JOHTO sim\vsenhor.\fEles farão uma\nvingança.",
  ["50:4600"] = "NA\nque roubei, está\vescondida no\vGINÁSIO DE\vCERULEANA.\fEu coloquei dentro\nda água.\fOlhe na água\ncentral do\vGINÁSIO.\fGaroto, não me\nesqueça!\fA EQUIPE ROCKET\num dia derrotará\vti. \fMeus amigos virão\nde JOHTO sim\vsenhor.\fEles farão uma\nvingança.",
  ["50:46f3"] = "…\fO que disse?\nTchau tchau EQUIPE\vROCKET?\fSua fala foi\nquebrada?\fOh, não! O que\ndevo fazer a\vpartir de agora?",
  ["50:48e7"] = "MISTY: Aww! Por\nque você tem que\vaparecer e nos\vatrapalhar agora!\fVocê sabe como\nchamamos pessoas\vcomo você?\fPestinhas!\fMe ouviu bem!\f…\f… Oh? Essas\nINSÍGNIAS que\vvocê tem… São as\vINSÍGNIAS DOS\vGINÁSIOS DE JOHTO?\vVocê tem oito,\ventão deve ser um\vbom treinador.\fCerto, venha\nao GINÁSIO DE\vCERULEANA.\fFicarei feliz em\ndesafiá-lo.\fEu sou MISTY, a\nLÍDER DE GINÁSIO\vem CERULEANA!",
  ["50:4900"] = " tem que\vaparecer e nos\vatrapalhar agora!\fVocê sabe como\nchamamos pessoas\vcomo você?\fPestinhas!\fMe ouviu bem!\f…\f… Oh? Essas\nINSÍGNIAS que\vvocê tem… São as\vINSÍGNIAS DOS\vGINÁSIOS DE JOHTO?\vVocê tem oito,\ventão deve ser um\vbom treinador.\fCerto, venha\nao GINÁSIO DE\vCERULEANA.\fFicarei feliz em\ndesafiá-lo.\fEu sou MISTY, a\nLÍDER DE GINÁSIO\vem CERULEANA!",
  ["50:4a00"] = "IO DE\vCERULEANA.\fFicarei feliz em\ndesafiá-lo.\fEu sou MISTY, a\nLÍDER DE GINÁSIO\vem CERULEANA!",
  ["50:4d1c"] = "Você teve uma\nbatalha a mais do\vque esperava, mas\vvocê ganhou mesmo\vassim.\fComo prometi, você\nganhou um prêmio.",
  ["50:4d7e"] = "Após ver como\nvocê batalha, eu\vquero ver como eu\vme saio.\fO que acha?\nDeixe-me testá-lo.",
  ["50:4dde"] = "Nunca tive uma\nbatalha tão boa!",
  ["50:4e01"] = "Foi uma grande\nbatalha!\fVocê e seus\nPOKéMONS são\vincrivelmente\vfortes!",
  ["50:4e48"] = "CABANA DO MAR \fCASA DO BILL.",
  ["50:5124"] = "PRAÇA DO MONTE LUA\fSuba as escadas.",
  ["50:5311"] = "PRAÇA DO MONTE LUA\fSuba as escadas.",
  ["50:5675"] = "A porta está\ntrancada…",
  ["50:5682"] = "A ferida do\nvoador.\fÉ impossível de\nler…",
  ["50:571c"] = "USINA DE ENERGIA\nDE KANTO.",
  ["50:5831"] = "ROTA 10\fCIDADE CERULEANA-\nCIDADE LAVANDA.",
  ["50:588f"] = "PLANALTO ÍNDIGO\fO Ultimo Objetivo\npara os\vtreinadores!\fQUARTEL GENERAL\nDA LIGA POKéMON.",
  ["50:5a00"] = "L\nDA LIGA POKéMON.",
  ["50:8057"] = "\numas pedras.",
  ["50:8500"] = "ente.",
  ["50:9c4f"] = "nou?\fVi vários homens\nde preto no LAGO\vDA RAIVA…",
  ["50:9d00"] = " quando\vevoluem, mas\vaprendem golpes\vmais lentamente.",
  ["50:c500"] = "anhã, as\nCÁPSULAS DO TEMPO\vvão funcionar em\vtodos CENTROS\vPOKéMONS.\fTenho que\nir rápido para\vGOLDENROD e ver\vmeus pais.\fTchau-tchau!",
  ["50:cb00"] = "ou boa\vcom POKéMONS\vtambém.",
  ["51:400e"] = "Os marinheiros\nsão generosos.\fEle ensinou FORÇA\nao meu POKéMON.\fEle agora move\numas pedras.",
  ["51:4067"] = "Existe uma pessoa\nna CIDADE\vCIANWOOD, que fica\vapós o mar.\fEu o ouvi falando\nsobre seu POKéMON\vraro.",
  ["51:419a"] = "…Obrigado pela\nsua ajuda lá\vno FAROL…\fMas isto é muito\ndiferente.\fPermita-me que eu\napresente-me.\n    \fEu sou JASMINE,\na LÍDER DO\vGINÁSIO.\fEu uso POKéMONS do\ntipo AÇO. Você\vsabe algo sobre\vestes POKéMONS?\fÉ um tipo de\nPOKéMON que foi\vdescoberto a\vpouco. \f…Eu já vou\ncomeçar…",
  ["51:429c"] = "…Você é o melhor\ntreinador, pois\vpossui habilidades\v e compaixão.\fConforma a lei\nda LIGA, eu lhe\vconcedo esta\vINSÍGNIA.",
  ["51:431b"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA\vMINERAL do GINÁSIO\vda CIDADE OLIVINE.",
  ["51:4335"] = "A INSÍGNIA MINERAL\ncria a DEFESA do\vPOKéMON.\fPor favor pegue\nisto…",
  ["51:4386"] = "…Você pode ensinar\nao POKéMON o\vRABO DE FERRO.",
  ["51:43b2"] = "Hum… Não sei\ncomo dizer, mas\vboa sorte amigo.",
  ["51:43e3"] = "JASMINE usa um\nnovo tipo de\vPOKéMON do tipo\vAÇO.\fEu não sei muita\ncoisa desse\vPOKéMON.",
  ["51:4432"] = "Isto é incrivel!\nPOKéMONS do tipo\vAÇO hein?\fNão sei por que\neu não encontro\vestes POKéMONS.",
  ["51:445a"] = "Não sei por que\neu não encontro\vestes POKéMONS.",
  ["51:4489"] = "JASMINE, a LÍDER\nDO GINÁSIO, está\vno FAROL.\fEla está ajudando\num POKéMON doente.\fSe você está\nquerendo\vdesafiá-la, seja\vmuito paciente.",
  ["51:4583"] = "Quando meu POKéMON\nadoece, o\vFARMACEUTICO em\vECRUTEAK faz\vremédios para mim.",
  ["51:4624"] = "No caminho para\nCIANWOOD, existem\vquatro ilhas\vdesertas.\fAs crianças ruins\nsão levadas para\vlá como castigo!",
  ["51:4692"] = "Toda vez que me\nencrenco, papai\vsempre me assusta.",
  ["51:472a"] = "OLIVINE está no\nmar!\fE se está no mar,\nexistem milhões\vde peixes aqui!\fEu pesquei aqui\ndurante 30 anos.\fVocê gostaria de\nenfrentar uns\vpeixes?",
  ["51:47bc"] = "Ah, hahah!\nNós arrumamos um\vnovo pescador!",
  ["51:47e8"] = "Peixes não são\nencontrados só\vno mar.\fEles estão onde\nexiste água.",
  ["51:482d"] = "O quêê? Você não\ncurte pescar!?\vIncompreensível!",
  ["51:4860"] = "Como vão as\ncoisas, meu amigo?",
  ["51:48bd"] = "Bom! Seu POKéMON\nparece estar sendo\vbem treinado!\fMas eles não tem\nforça para mover\vpedregulhos.\fEi, use isto e\nensine FORÇA a\veles!\fVocê precisa da\nINSÍGNIA DO\vGINÁSIO de\vGOLDENROD para\vpoder usá-lo.",
  ["51:4980"] = "No mar, a única\ncoisa com que\vvocê pode contar,\vé com você mesmo!\fEstou orgulhoso\ndo meu POKéMON!",
  ["51:49e0"] = "Cruzar o mar?\nEntão escute isto!\fHá redemoinhos na\nágua a caminho de\vCIANWOOD.     \fSeu POKéMON deve\nconhecer um golpe \vque acabe com os\vredemoinhos.",
  ["51:4aaa"] = "Seu POKéMON\nconhece um golpe\vaquático que\vtransporta pessoas\vna água?",
  ["51:4aec"] = "Meu namorado me\nmandou o\vBUTTERFREE do\vexterior.\fEle trouxe uma\ncarta dele!\fQuer saber o que\nhavia nela?\fVamos ver… Não!\nÉ secreto!",
  ["51:4bb0"] = "De onde você disse\nque veio?\fCIDADE NEW\nBARK?\fO PROFESSOR ELM\nmora lá, não é?\fVocê andou\nbastante até\vchegar aqui.",
  ["51:4d04"] = "A MOOMOO está\ndoente.\fEla precisa de\nmuitos GRÃOS.",
  ["51:4d30"] = "Nós estamos\nalimentando a\vMOOMOO!",
  ["51:4d56"] = "Seu mugido está\nfraco…",
  ["51:4d77"] = "Dar um GRÃO à\nMILTANK?",
  ["51:4d91"] = "{PLAYER} deu um\nGRÃO à MILTANK.",
  ["51:4dad"] = "A MILTANK ficou um\npouco saudável.",
  ["51:4dd1"] = "A MILTANK ficou\nmais saudável!",
  ["51:4df0"] = "A MILTANK está\ntotalmente curada!",
  ["51:4e11"] = "{PLAYER} não possui\nGRÃOS…",
  ["51:4e24"] = "{PLAYER} não deu\nGRÃO à MILTANK.\fA MILTANK parece\ntriste.",
  ["51:4f0d"] = "Minha MILKTANK\nnão está dando\vmais leite.\fEssa FAZENDA tem\num leite famoso.\fQuase todos querem\nbeber.\fEla te dá muito\nleite se alimentá-\vla com muitos\vGRÃOS.",
  ["51:4fb7"] = "O que você acha do\nLEITE MOOMOO?\fEle me orgulha e\nme alegra.     \fDê ele a um\nPOKéMON para\vrestaurar seu PS.\fTe vendo ele por\n¥500.",
  ["51:5031"] = "Aqui está! Beba-o\ne aproveite!",
  ["51:5050"] = "Desculpe-me,\nfilho!\fSem dinheiro, sem\nvenda!",
  ["51:506f"] = "Eu percebi que sua\nBOLSA está cheia,\vfilho.",
  ["51:508e"] = "Você não o quer?\nVolte outra hora,\vcerto?",
  ["51:50b3"] = "É melhor eu ir\ntirar leite.",
  ["51:50cd"] = "Até para KANTO\nnosso leite vai.\fSe a nossa MILTANK\nnão produzir mais\vleite, nós vamos\vter problemas.",
  ["51:512d"] = "Você curou nosso\nMILTANK, rapaz. Agora ela dá LEITE\nMOOMOO de novo.\vEu tenho algo bom\vpara você.",
  ["51:519e"] = "Isso é o RONCAR.  \fÉ um golpe raro\nque só funciona\venquanto o POKéMON\vestiver dormindo.\fVocê decide como\nvai usar isso,\vrapaz.",
  ["51:526c"] = "Ouvi dizer que um\nGYARADOS vermelho\vapareceu no LAGO.\fÉ estranho, porque\naté GYARADOS\vcomuns são raros\vno lago…",
  ["51:52de"] = "Meu programa de\nrádio favorito?\vÉ a M→SICA\vPOKéMON.",
  ["51:530d"] = "Eu me divirto\nescutando ao\vrádio…\nÉ bem engraçado.",
  ["51:545d"] = "Os POKéMONS\ntêm muitas\vexperiências em\vsuas vidas, como\vnós. \fEu, também, vi e\npassei por muitas\vcoisas na minha\vvida.\fTenho mais\nexperiência e\vmostrarei o que eu\vquero dizer.\fEstive com\nPOKéMONS desde\vantes de você\vnascer.\fNão perco\nfacilmente.\fEu, PRYCE, o\ntreinador do\vinverno, mostrarei\vmeu poder!",
  ["51:5583"] = "Ah, estou\nimpressionado com\vvocê.\fCom sua força,\nsei que você\vpassará por todos\vos obstáculos da\vvida.\fVocê merece essa\nINSÍGNIA!",
  ["51:560b"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA\vGLACIAL do GINÁSIO\vda CIDADE\vMAHOGANY.",
  ["51:5625"] = "Essa INSÍGNIA\nmelhorará o estado\vESPECIAL dos\vPOKéMONS.\fTambém permite\nseus POKéMONS\vusarem o\vREDEMOINHO para\vatravessar grandes\vredemoinhos.\fE isso… É um\npresente meu para\vvocê!",
  ["51:56bf"] = "Esse TM contém\nVENTO GELADO.\fEle causa danos\ne reduz a\vvelocidade.\fIsso demonstra a\ndureza do inverno.",
  ["51:5729"] = "Quando o gelo e a\nneve derretem, a\vprimavera chega.\fVocê e seu POKéMON\nestarão sempre\vjuntos por muitos\vanos.\fAproveite esse\ntempo de união!",
  ["51:5a8f"] = "PRYCE é um\nveterano que\vtreina POKéMONS\vpor mais de 50\vanos.\fEle diz ser bom em\ncongelar os\voponentes como\vgolpes do tipo\vgelo.\fQuer dizer que\nvocê deve\vderretê-lo com sua\vquente ambição!",
  ["51:5b45"] = "PRYCE é algo, mas\nvocê é algo mais!\fEssa foi a quente\nbatalha que trouxe\va tona o espaço\vdas gerações!",
  ["51:5c32"] = "Como é? A EQUIPE\nROCKET retornou?\fVi vários homens\nde preto no LAGO\vDA RAIVA…",
  ["51:5c83"] = "Eu impeço meus\nPOKéMONS de\vevoluírem cedo.\fAssim aprendem\ngolpes mais cedo\vdo que aprenderiam\vevoluídos.",
  ["51:5ce8"] = "Os POKéMONS ficam\nmais fortes quando\vevoluem, mas\vaprendem golpes\vmais lentamente.",
  ["51:5d88"] = "A MONTANHA\nMORTEIRO é um\vlabirinto.\fCuidado para não\nse perder.",
  ["52:406c"] = "Só entrará na\nTORRE ESTRANHA se\vtiver a INSÍGNIA\vDO GINÁSIO\vECRUTEAK.\fPerdão mas terá\nque sair.",
  ["52:40cc"] = "Só entrará na\nTORRE ESTRANHA se\vtiver a INSÍGNIA\vDO GINÁSIO\vECRUTEAK.\fAh! É a INSÍGNIA!\nVocê pode ir à\vTORRE!",
  ["52:413f"] = "A TORRE ESTRANHA\nà frente foi feita\vcomo um lar para\vo POKéMON voador.",
  ["52:417d"] = "A TORRE ESTRANHA\ntremeu!\fUm POKéMON deve\nter retornado ao\vtopo!",
  ["52:41b9"] = "Duas torres…\nDois POKéMONS…\fMas quando uma\nqueimou, ambos\vPOKéMONS voaram e\vnunca retornaram.",
  ["52:4304"] = "Oi, sou BILL. E\nquem é você?\fHmm, {PLAYER}, hã?\nVocê veio na hora\vcerta.",
  ["52:434e"] = "Terminei os\núltimos ajustes na\vminha CÁPSULA DO\vTEMPO.\fVocê sabe que\nPOKéMONS podem ser\vtrocados, né?\fMinha CÁPSULA DO\nTEMPO foi feita\vpara habilitar\vtrocas com o\vpassado.\fMas você não pode\nmandar nada que\vnão tenha no\vpassado.\fSe fize-lo, o PC\nno passado vai ter\vproblemas.\fEntão você deve\nremover tudo que\vainda não existia\vno passado.\fSimplesmente, não\nmande novos golpes\vou novos POKéMONS\vna CÁPSULA DO\vTEMPO.\fNão se preocupe.\nEu já fiz os\vajustes.\fAmanhã, as\nCÁPSULAS DO TEMPO\vvão funcionar em\vtodos CENTROS\vPOKéMONS.\fTenho que\nir rápido para\vGOLDENROD e ver\vmeus pais.\fTchau-tchau!",
  ["52:4581"] = "O jeito que as\nGAROTAS KIMONO\vdançam é\vexplendido!\fDo jeito que\nelas usam seus\vPOKéMONS!",
  ["52:45d6"] = "MORTY, o LÍDER DO\nGINÁSIO, é tãão\vlegal.\fSeus POKéMONS são\nbem fortes também.",
  ["52:461c"] = "LAGO DA RAIVA…\fA aparição de\nenxames de\vGYARADOS…\fParece uma\nconspiração. Eu\vsei!",
  ["52:46d3"] = "Isso ocorreu\nquando eu era\vjovem.\fO céu de repente\nficou preto.\fUm POKéMON voador\ngigante bloqueou\vo Sol.\fQueria saber qual\nPOKéMON era?\fEra tipo um\npássaro com um\vdragão.",
  ["52:4782"] = "Será que um\nPOKéMON daquele\vtamanho é real?\fSe for, ele\ndeve ser muito\vpoderoso.",
  ["52:4b94"] = "As GAROTAS KIMONO\ndançam muito bem\ve são excelentes\vtreinadoras\vPOKéMON.\fEu sempre desafio\nelas, mas eu nunca\vconsigo ganhar…",
  ["52:4c1b"] = "Rapaz! Se puder\nderrotar todas as\vGAROTAS KIMONO, eu\vlhe darei um\vpresente.",
  ["52:4c5e"] = "A maneira que\nvocê batalhou,\vfoi como assistir\và uma dança.\fFoi uma festa rara\nde se ver.\fQuero que pegue\nisso. Não se\vpreocupe, Leve\visso.",
  ["52:4cdf"] = "Isso é o SURFE.\fÉ um golpe que\npermite o POKéMON\vnadar através da\vágua.",
  ["52:4d19"] = "Queria que meus\nPOKéMONS fossem\velegantes como as\vGAROTAS KIMONO…",
  ["52:4d68"] = "Aquele homem está\nsempre com seu\vRHYDON.\fDiz que quer um\nPOKéMON que dance\ve surfe.\fEle está tentando\nter um POKéMON que\vfaça Nado\vSincronizado?",
  ["52:4dee"] = "As GAROTAS KIMONO\nsão tão bonitas…\fMas elas têm que\npassar por\vum rigoroso\vtreinamento.\fE elas devem\naprender a seguir\vos costumes antes\vde aparecer em\vpúblico. \fMas se ama algo,\nqualquer coisa é\vpossível.",
  ["52:4ebd"] = "É um extravagente\npainel decorado\vcom flores.",
  ["52:4f8c"] = "Meu EEVEE evoluiu\nem um ESPEON.\fMas o EEVEE do meu\namigo virou um\vUMBREON.\fPor que será? Nós\ndois treinávamos\vo EEVEE do mesmo\vjeito…",
  ["52:5019"] = "Se você usar o\nREVIVE, um POKéMON\vque desmaiou\vvai acordar\vrapidamente.",
  ["52:516b"] = "Que bom você ter\nvindo.\fAqui em ECRUTEAK,\nos POKéMONS foram\vhonrados.\fDizem que\nPOKéMONS lendários\vvão aparecer para\vo treinador\vverdadeiramente\vforte.\fEu acredito\nnesse conto,\ventão treinei\vsecretamente\vaqui toda minha\vvida.\fComo resultado\nposso ver o que\voutros não vêem.\fSó um pouco mais.\fCom um pouco mais,\neu poderia prever\vo futuro no qual\veu conheceria o\vPOKéMON lendário.\fVocê me ajudará a\nalcançar esse\vnível!",
  ["52:52f4"] = "Não sou boa o\nbastante ainda…\fCerto, essa\nINSÍGNIA DA NÉVOA\vé sua.",
  ["52:532d"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vNÉVOA DO GINÁSIO\vDA CIDADE DE\vECRUTEAK.",
  ["52:5343"] = "Por ter a INSÍGNIA\nDA NÉVOA, os\vPOKéMONS acima do\vNÍVEL 50 vão te\vobedecer.\fE também os\nPOKéMONS que sabem\vo SURFE poderão\vusá-lo a qualquer\vhora.\fLeve isso também.",
  ["52:53d6"] = "É a BOLA SOMBRIA.\fEla causa danos\ne reduz a DEFESA\vESPECIAL.\fUse-a se lhe\nagradar.",
  ["52:5400"] = "reduz a DEFESA\vESPECIAL.\fUse-a se lhe\nagradar.",
  ["52:542f"] = "Eu vejo…\fSua jornada te\nlevou para lugares\vdistantes.\fE você\ntestemunhou muito\vmais que eu.\fEu te invejo por\nisso…",
  ["52:56d2"] = "Os treinadores\naqui têm motivos\vsecretos.\fSe vencer, eles\ndevem contar\vlhe profundos\vsegredos de\vECRUTEAK.",
  ["52:573c"] = "Uau, {PLAYER}.\nVocê foi demais.\fEu me agachei no\ncanto livre do\vpuro terror!",
  ["52:58cc"] = "Ah. Você está numa\njornada com o seu\vPOKéMON?\fBem, o que é uma\njornada sem uma\vCaça ao Tesouro?\fEstou certo ou\nestou certo?",
  ["52:5945"] = "Bom! Você entendeu\no verdadeiro\vespírito de uma\vjornada.\fGosto disso! Leve\nisso com você.",
  ["52:599e"] = "Existem\nvários objetos\vespalhados que não\vsão visíveis.\fUse o ACHA ÍTENS\npara ver se tem ou\vnão um item perto\vde você.        \fEle não mostra o\nlugar exato,\ventão você terá\vque procurar.\fAh sim, dizem que\nexistem itens na\vTORRE QUEIMADA DE\vECRUTEAK.",
  ["52:5a95"] = "…Cada um deve ter\nseu gosto…",
  ["52:5ab6"] = "HISTÓRIA DE\nECRUTEAK.\fQuer ler?",
  ["52:5adc"] = "Em ECRUTEAK, havia\nduas torres.\fCada uma era o\nalojamento de\vpoderosos POKéMONS\vvoadores.\fMas uma das torres\nqueimou até o\vchão.\fOs dois POKéMONS\nnunca mais foram\vvistos desde\ventão…\fFicar lendo?",
  ["52:5b92"] = "ECRUTEAK era\ntambém a casa dos\vtrês POKéMONS que\vcorriam pela\vcidade.\fDizia-se que eles\nforam nascidos da\vágua, do relâmpago\ve do fogo.\fMas eles não\npuderam conter\vseus poderes\vexcessivos.\fDizem que eles\ncorrem como o\vvento por dentro\vda grama.",
  ["53:40f3"] = "Sou CLAIR.\nA maior mestra\vem dragões\vdo mundo.\fEu venço até a\nELITE QUATRO da\vLIGA POKéMON.\fVocê ainda deseja\nme desafiar?\f…Bom. Vamos lá!\nComo treinadora,\vusarei meu poder\vmáximo contra\vqualquer oponente!",
  ["53:41cf"] = "Eu fui derrotada?\nEu não acredito.\vDeve haver algo de\verrado…",
  ["53:4207"] = "Eu não admitirei\nisso.\fEu posso ter\nperdido, mas você\vainda não está\vpronto para a\vLIGA POKéMON.\fEu sei. Você\ndeve passar pelo\vDesafio do Dragão.\fAtrás deste\nGINÁSIO tem um\vlugar chamado de\vTOCA DO DRAGÃO.\fVá lá e traga-me\na PRESA DO DRAGÃO.\fEsse é o teste\npara ser aceito\vcomo um usuário de\vdragões.\fSe conseguir\nfazer isso, eu vou\vconsiderá-lo como\vum treinador\vconceituado.\fAté lá, não\nvou entregar a\vINSÍGNIA.",
  ["53:4391"] = "CLAIR: Qual o\nproblema?\fEssa missão não\nserá difícil para\vti, a não ser que\vsua vitória foi\vfalsa.",
  ["53:43f0"] = "CLAIR: Você não\nfoi à TOCA DO\vDRAGÃO.\fTentando\ntrapacear…\fEstou desapontada\ncom você.",
  ["53:4451"] = "CLAIR: Você\nprovou a mim que\vé competente.\fEu quero que leve\nisse TM.",
  ["53:44a7"] = "Isso contém o\nSOPRO DRAGÃO.\fIsso não tem nada a\nver como o meu\vsopro.    \fSe não\vquiser, vocÊ não\vé obrigado a\vlevar.",
  ["53:4525"] = "Então você\ncolecionou todas\vas INSÍGNIAS.\fSua destinação é\na LIGA POKéMON no\vPLANALTO ÍNDIGO.\fVocê sabe como\nchegar lá?\fDaqui, vá à\nCIDADE NEW BARK.\fDepois SURFE ao\nleste. Aquela rota\vé bem difícil.\fNão se atreva a\nperder na LIGA\vPOKéMON!\fCaso o faça, me\nsentirei pior\vainda do que ter\vperdido para\vvocê!",
  ["53:47fa"] = "Oi! Seja bem\nvindo!\fÉ uma grande\njornada, mas\vestamos quase\vacabando.\fConte comigo.\fCLAIR usa POKéMONS\ndragões do tipo\vmístico e sagrado.\fVocê não\npode feri-los\vfacilmente.\fComo sabe, eles\nsão supostamente\vfracos contra\vgolpes do tipo\vgelo.",
  ["53:48e8"] = "Você foi ótimo ao\nderrotar CLAIR!\fO que falta agora\né o desafio da\vLIGA POKéMON.\fVocê está no\ncaminho de se\vtornar o CAMPEÃO\vPOKéMON!",
  ["53:4c64"] = "CLAIR e LANCE\ntreinaram aqui\vpara melhorar\vsuas técnicas\vcomo treinadores\vPOKéMON.",
  ["53:4d20"] = "Você não pode\ncomprar o REVIVE\vTOTAL.\fEle restaura o\nPOKéMON desmaiado\vpor completo.\fAtenção, Ele não\nrestaura o PP,\vnecessário para\vos golpes.",
  ["53:4d9f"] = "O REPELENTE 03\nafasta POKéMONS\vfracos de você.\fÉ o REPELENTE mais\nduradouro.",
  ["53:4e3b"] = "Dentro do PLANALTO\nÍNDIGO está a\vLIGA POKéMON.\fSoube que\nos melhores\vtreinadores vão lá\vde todos os cantos\vdo país.",
  ["53:4eb3"] = "Eu tinha ensinado\num golpe ao meu\vPOKéMON.\fEntão eu o levei\nao APAGADOR DE\vTÉCNICAS para\vfazê-lo esquecer\vum golpe HM.",
  ["53:4fa7"] = "O BLAINE DO\nGINÁSIO CINNABAR\vaparentemente vive\vsozinho numa\vcaverna das ILHAS\vSEAFOAM.",
  ["53:4ff1"] = "Já tem um ano que\no vulcão entrou em\veurupção.",
  ["53:507c"] = "O vulcão de\nCINNABAR entrou\vem eurupção.\fEle lançou pedras\nque bloquearam a\vROTA 19 por tempo\vindeterminado.\fSerá que as pes-\nsoas de CINNABAR\vestão seguras…",
  ["53:50fc"] = "Nenhum habitante\nde CINNABAR foi\vferido pela eurup-\vção vulcânica.\fIsto é ótimo!",
  ["53:51ba"] = "BLAINE: Waaah!\fMeu GINÁSIO em\nCINNABAR foi\vqueimado.\fMeus POKéMONS tipo\nfogo e eu estamos\vsem casa devido ao\vvulcão.\fWaaah!\fMas eu estou de\nvolta ao negócios\vcomo LÍDER DE\vGINÁSIO aqui nessa\vcaverna.\fSe você me\nderrotar, eu te\vdarei uma\vINSÍGNIA.\fÉ melhor você ter\num CURA FOGO!",
  ["53:52b8"] = "Parebéns!\fEu me queimei…\fVocê ganhou uma\nINSÍGNIA DO\vVULCÃO.",
  ["53:52f5"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DO\vVULCÃO do GINÁSIO\vdas ILHAS SEAFOAM.",
  ["53:530f"] = "BLAINE: Eu perdi\ndesta vez, mas\vna próxima eu\vvencerei.\fQuando eu\nreconstruir meu\vGINÁSIO em\vCINNABAR nós\vteremos uma\vrevanche.",
  ["53:538e"] = "BLAINE: Meus\nPOKéMONS de fogo\vserão ainda mais\vfortes. Aguarde e\vverá!",
  ["53:53cb"] = "Você!\f…Hã? Já acabou?\fDesculpe-me,\namigo!\fO GINÁSIO CINNABAR\nfoi destruído e eu\vnão sabia onde te\vachar.\fMas, você é bem\nforte até sem os\vmeus avisos. Sabia\vque ganharia!",
  ["53:5477"] = "Um GINÁSIO POKéMON\npode ser em todo\vlugar que tenha um\vLÍDER DE GINÁSIO.\fNão precisa ser um\nprédio.",
  ["53:5521"] = "…Você veio de\nlonge…\fAqui eu meditei.\nDentro de mim, um\vnovo poder foi\vdespertado.\fDeixe-me dividir\nmeu poder com o\vseu POKéMON. Leve\visso, garoto.",
  ["53:55b4"] = "Pode sentir?\nÉ o PODER OCULTO!\fEle libera o poder\ndo POKéMON para\vatacar.\fLembre-se disso:\nseu tipo e poder\vdepende do POKéMON\vque estiver\vusando.",
  ["53:5649"] = "Eu estou\nmeditando…",
  ["53:5704"] = "O LAGO DA RAIVA é\numa cratera feita\vpelos rituais dos\vGYARADOS.\fA cratera se\nencheu com a água\vda chuva e formou\vum LAGO.\fEssa história é\npassada desde o\vTataravô do meu\vavô.\fAli era um lugar\nque se podia\vpegar MAGIKARPS\vlivremente, mas…\fEu não entendo\no que está\vacontecendo no\vlago.",
  ["53:5823"] = "O LAGO está\nestranho desde\vquando os homens\vde preto chegaram.",
  ["53:5866"] = "O LAGO DA RAIVA\nvoltou ao normal.\fAs MAGIKARPS\nvoltaram.\fAinda posso\nrealizar meu sonho\vde ver a maior\vMAGIKARP do\vmundo.  \fVocê tem uma VARA?\fPor favor,\najude-me se puder.",
  ["53:5914"] = "Ah, você tem uma\nMAGIKARP.\fVamos ver o\ntamanho dela.",
  ["53:594d"] = "Uau! Essa é\nincrível!\fEu tiro meu chapéu\npara você!\fEssa é uma\nlembrança!",
  ["53:5999"] = "O recorde que é o\nimportante.\fConsidere como um\nbônus!",
  ["53:59d7"] = "Uau! Essa é\nincrível!\f…Não queria dizer\nisso, mas eu já\vvi outras que são\vbem maiores.",
  ["53:5a32"] = "Como? Isso não é\numa MAGIKARP!",
  ["53:5a4f"] = "Oh… Então não tem\numa muito boa para\vme mostrar?\fTalvez na próxima.",
  ["53:5af5"] = "Só pessoas\nencaminhadas ao\vLAGO DA RAIVA\vpassaram aqui bem\vtarde.",
  ["53:5b3b"] = "Atualmente ninguém\nvai ao LAGO DA\vRAIVA.",
  ["53:5ca8"] = "Parado ai,\nsenhor!\fO pedágio é ¥1000\npara atravessar.",
  ["53:5ce1"] = "Obrigado, senhor!",
  ["53:5cf2"] = "Então pague o que\ntiver.",
  ["53:5d13"] = "He-he-he. Estamos\nficando ricos.\fTodo mundo quer\nver o que está\vacontecendo no\vLAGO DA RAIVA.",
  ["53:5d6d"] = "Eu fui expulso do\nmeu posto por\vesses caras de\vpreto.\fEles esqueceram\nisso.\fIsso me deixa\ninconfortável.\vPoderia levar\visso?",
  ["53:5dff"] = "Use este portão\npara não andar na\vgrama.",
  ["53:c047"] = "usados até\vse seu POKéMON\vdesmaiar.",
  ["54:4005"] = "Você está\ncolecionando as\vINSÍGNIAS DOS\vGINÁSIOS DE KANTO?",
  ["54:405a"] = "Eu soube que uma\npessoa sombria\vestá escondida.\fNão ficarei\nparado caso ele\vseja um ladrão.",
  ["54:40c3"] = "Nós já fomos\nassaltados por\vladrãos no passa-\vdo.",
  ["54:414d"] = "Meu marido vive\nfeliz com os\vPOKéMONS que\vconseguiu em\vtrocas.",
  ["54:418a"] = "Ah… Estou muito\nfeliz…",
  ["54:4218"] = "A ROTA 9 vai para\no leste. A USINA\vDE ENERGIA está\vno final.",
  ["54:4257"] = "O TRÊM MAGNETO\nanda a cerca de\v544 km/h.\fEle percorre entre\nKANTO e JOHTO em\vpouquíssimo tempo.\fEle realmente\ntorna JOHTO\vacessível.",
  ["54:4453"] = "Opa! Me desculpe!\nVocê não se\vmachucou, né?\fEstou muito\nocupado, não tenho\vtempo para\vconversar com\vvocê.\fSeria ruim se\nalguém me visse\vaqui!",
  ["54:44cc"] = "Oh não! Você já me\nviu. Eu cometi um\vgrande erro!",
  ["54:44fd"] = "Ei, você! Esqueça\nque me viu, certo?\fVocê não me viu,\nnão me ouviu e nem\vsabe de nada,\vcerto?    \fTchau, garoto!\nAté breve!",
  ["54:4568"] = "Perdão, estarei\nfora por enquanto.\vMISTY, LÍDER DO\vGINÁSIO",
  ["54:459a"] = "Como a MISTY saiu,\nnós ficaremos\vinativos.\vTREINADORES DO\vGINÁSIO.",
  ["54:45cc"] = "MISTY: Eu estava\nte esperando,\vpestinha!\fMesmo que você\ntenha muitas\vINSÍGNIAS DOS\vGINÁSIOS DE JOHTO,\vé melhor não me\vsubestimar.\fMeus POKéMONS do\ntipo água são bem\vpoderosos!",
  ["54:4664"] = "MISTY: Você é\nrealmente bom…\fEu admito que você\né habilidoso…\fAqui está. É a\nINSÍGNIA DA\vCASCATA.",
  ["54:46c0"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vCASCATA DO\vGINÁSIO DA CIDADE\vCERULEANA.",
  ["54:46da"] = "MISTY: Existem\nmuitos treinadores\vfortes em JOHTO?\vAssim como você?\fUm dia eu\nviajarei, então eu\vpoderei batalhar\vcom muitos\vtreinadores\vhabilidosos.",
  ["54:48ff"] = "Você! CAMPEÃO em\nprogresso!\fComo MISTY tinha\nsaído, eu saí\vpara me divertir\vtambém. He-he-he.",
  ["54:4952"] = "Uau, você me\nmostrou como é\vpoderoso.\fComo sempre, foi\numa demonstração\vde uma grande\vbatalha!",
  ["54:4a25"] = "Você enfrentará\nmuitos treinadores\va caminho da\vPENÍNSULA DE\vCERULEANA.\fEles querem\ntestar as próprias\vhabilidades com\voutros treinado-\vres.",
  ["54:4a9e"] = "A MISTY é talvez\na única pessoa na\vcidade capaz de\vderrotar os\vtreinadores da\vPENÍNSULA DE\vCERULEANA.",
  ["54:4b49"] = "Um CENTRO POKéMON\nperto da carverna?\fDeve ser bem útil.",
  ["54:4b7e"] = "O GERENTE DA\nUSINA DE ENERGIA\vestá procurando\vpor um poderoso\vtreinador POKéMON.\fEle precisa de\nalguém que o\vajude a recuperar\valgo que foi\vroubado.",
  ["54:4bf6"] = "Eu ouvi dizer que\na EQUIPE ROCKET\vtinha se mudado\vpara JOHTO e\vtornou a falir.\fEu não sabia nada\ndisso!",
  ["54:4c64"] = "Quando você vai\npara fora, é\vpossível enxergar\vo telhado de uma\vgrande construção.\fÉ a USINA DE\nENERGIA DE KANTO.",
  ["54:4e31"] = "Um ladrão assaltou\na USINA DE\vENERGIA…\fOnde parará este\nmundo?",
  ["54:4e73"] = "Eu telefonei de\nCERULEANA.\fParece que um\nsujeito estranho\vestá aprontando\vpor lá.",
  ["54:4ed0"] = "Eu poderia pedir\nsua cooperação?",
  ["54:4ef3"] = "Nós teremos que\najustar o nosso\vsistema de\vsegurança.",
  ["54:4f20"] = "Alguém roubou uma\nparte essencial\vpara o gerador.\fSem essa parte,\no gerador fica\vtotalmente inútil!",
  ["54:4f89"] = "O gerador está\nconsertado e\vfuncionado.\fAgora, está\ndistribuindo a\veletricidade!",
  ["54:4fca"] = "Essa USINA DE\nENERGIA foi\vabandonada no\vpassado.\fNós a recuperamos\npara ela fornecer\venergia para que\vo TRÊM MAGNETO\vfuncionasse!",
  ["54:5040"] = "O gerador está\nfuncionando de\vnovo agora!",
  ["54:505f"] = "O GERENTE DA\nUSINA DE ENERGIA\vestá lá na frente.\fMas desde quando\nalguém quebrou o\vgerador, ele está\vfurioso…",
  ["54:50d0"] = "Desde quando o\ngerador foi\vconsertado, o\vGERENTE está bem\vfeliz.",
  ["54:5113"] = "O TRÊM MAGNETO\ngasta bastante\veletricidade.\fEle não pode se\nmexer se o novo\vgerador não\vfuncionar.",
  ["54:5176"] = "Que bom!\nFinalmente o\vTRÊM MAGNETO está\vfuncionando de\vnovo.",
  ["54:51b5"] = "GERENTE: Eu, eu\nestou pronto para\vdestruir alguém!\fQuem ousaria\nquebrar meu\vgerador?\fEu gastei muito\ntempo nele!\fSe eu pegá-lo,\nele vai testar\vmeu SUPER CANHÃO!",
  ["54:5259"] = "GERENTE: Eu não o\nperdoarei!\fO culpado pode\nchorar e se\vdesculpar, mas eu\vvou martelá-lo!\fHahahaha!",
  ["54:52bf"] = "GERENTE: Ah! Bom!\fA PARTE perdida\ndo meu amado\vgerador!\fFoi você quem\nachou?",
  ["54:5315"] = "Haha! Obrigado!\fEi! Leve esse TM\ncomo recompensa!",
  ["54:5345"] = "GERENTE: O TM07\né o meu SUPER\vCANHÃO.\fÉ uma poderosa\ntécnica!\fNão é o que\ntodos consideram\vcorreto, mas ele\vpossui uma batida\vforte!",
  ["54:53c6"] = "GERENTE: Meu amado\ngerador!\fFica enviando\neletricidade para\vfora!",
  ["54:5612"] = "Hã? Você conhece\nBILL? Ele é meu\vneto e está em\vJOHTO.\fEle trabalha com\ncomputadores\venquanto eu cuido\vda casa dele.",
  ["54:5676"] = "Se você tiver esse\nPOKéMON, eu\vpoderia vê-lo?",
  ["54:56a4"] = "Vai me mostrar?\nComo é bondoso!",
  ["54:56c8"] = "Você não tem? Que\npena…",
  ["54:56ea"] = "Ah, então esse é\n{STRBUF}?\fNão é lindo?\nÉ muita gentileza\vda sua parte.",
  ["54:5725"] = "Obrigado!\fIsso é um presente\npara você.",
  ["54:5752"] = "Venha me visitar\noutra hora.",
  ["54:576e"] = "Obrigado por me\nmostrar tantos\vPOKéMONS bonitos.\fEu realmente\nadorei.\fEstou feliz por\nter vivido tanto.",
  ["54:57d5"] = "Hã? Esse não é o\nPOKéMON que eu\vmencionei.",
  ["54:5804"] = "Me neto BILL me\ncontou sobre um\vPOKéMON que tem\vuma grande língua.",
  ["54:5843"] = "Ah, meu neto me\nfalou de um\vPOKéMON verde e\vveloz que tem\vfolhas crescendo\vna sua cabeça.",
  ["54:5897"] = "Você conhece um\nPOKéMON do mar que\vtem uma esfera\vvermelha no seu\vcorpo?\fUm que é pontudo\ncomo uma estrela?\fOuvi dizer que ele\naparece à noite.\fEu realmente\nqueria vê-lo.",
  ["54:5942"] = "O BILL me contou\nsobre um POKéMON\vque é muito fiel\vao seu treinador.\fDizem que ele tem\num bom RUGIDO.",
  ["54:599b"] = "Ouvi falar sobre\num lindo POKéMON\vque tem seis\vcaudas.\fEu adoraria abraçar\num lindo POKéMON\vcomo esse.",
  ["54:59f5"] = "Você conhece\naquele POKéMON\vpopular e fofinho\vque tem um\vcorpo amarelo\ve bochechas\vvermelhas.\fEu adoraria saber\ncomo ele é antes\vde evoluir.",
  ["54:8c48"] = " pegar\vPOKéMONS que as\vcomuns POKé BOLAS.\fMas as de KURT\ndevem superá-las.",
  ["54:ca00"] = " \fUm POKéMON mesmo\nfraco pode ganhar\fmuita experiência\nnas batalhas.\fColoque o POKéMON\nfraco no topo da\vlista.\fTroque-o\nrápido! \fAssim, POKéMONS\nfracos ficam\vfortes!",
  ["54:f200"] = "m\vconsideração.",
  ["55:4013"] = "Seus POKéMONS\nsabem golpes\vde HM?\fEsses golpes podem\nser usados até\vse seu POKéMON\vdesmaiar.",
  ["55:4067"] = "O PC DO BILL\nguarda até 20\vPOKéMONS por BOX.",
  ["55:4092"] = "Você sabe algo\nsobre os FRUTOS?\fAbra uma fenda,\ndeixe o FRUTO oco\ve depois encaixe-o\vnum dispositivo\vespecial.\fAgora pode\ncapturar POKéMONS\vcom ele.\fOs FRUTOS eram\nusados como\vPOKé BOLAS.",
  ["55:41ed"] = "Todos SLOWPOKES\ndesapareceram da\vcidade.\fO protetor da\nfloresta deve\vestar nervoso com\vnós…\fIsso deve ser um\nsinal ruim.\fDevemos ficar em\nalerta.",
  ["55:4276"] = "Os SLOWPOKES\nvoltaram.\fMas meu aprendiz\nnão voltou da\vFLORESTA ILEX.\fOnde será que\nesse preguiçoso\vestá?",
  ["55:42ec"] = "Você sozinho\nperseguiu a EQUIPE\vROCKET e foi à\vFLORESTA ILEX?\fQue técnicas!\nGostei disso!\vVenha treinar\vconosco.",
  ["55:4359"] = "Para onde foram\ntodos SLOWPOKES?\vSerá que estão\vbrincando por aí?",
  ["55:439e"] = "Perdão, esqueci\nde agradecê-lo.\fEsse é o CARVÃO\nque eu fiz.\fPOKéMONS do tipo\nfogo ficariam\vfelizes ao segurar\visso.",
  ["55:440c"] = "Os SLOWPOKES\nvoltaram, e você\vainda achou um\vFARFETCH'D.\fVocê é o mais\nlegal!",
  ["55:44c6"] = "Não há SUPER BOLA\naqui. Terá que\vusar POKé BOLAS.\fQueria que KURT\nfizesse algumas\vdessas BOLAS para\vmim.",
  ["55:452f"] = "A SUPER BOLA é\nmelhor para pegar\vPOKéMONS que as\vcomuns POKé BOLAS.\fMas as de KURT\ndevem superá-las.",
  ["55:47ee"] = "Hã? Quem é você?\f{PLAYER}, né? Quer\nque eu faça umas\vBOLAS?\fPerdão, mas você\nterá que esperar.\fConhece a EQUIPE\nROCKET?\fAh, tudo bem.\fMesmo assim lhe\ncontarei.\fA EQUIPE ROCKET é\numa gangue que usa\vPOKéMONS para o\vseu trabalho sujo.\fParece que eles\nfaliram a três\vanos atrás.\fPorém, eles estão\nno POÇO, tirando\vos RABOS DOS\vSLOWPOKES para\vvender!\fEu vou lhes dar\numa lição sobre a\vdor!\fAguentem,\nSLOWPOKES, o velho\vKURT já está indo!",
  ["55:4990"] = "KURT: Oi, {PLAYER}!\fVocê se cuidou\ncomo um verdadeiro\vherói no POÇO.\fGosto do seu\nestilo!\fFicaria honrado ao\nfazer BOLAS para\vum treinador como\vvocê.\fÉ tudo que tenho\nagora, mas leve-a.",
  ["55:4a44"] = "KURT: Eu faço\nBOLAS com FRUTOS.\fPegue-os nas\nárvores e tragá-os\vpara mim.\fEu farei BOLAS\npara você.",
  ["55:4ab1"] = "KURT: Você tem\nFRUTOS para mim?\fÓtimo! Vou\ntransformá-los em\vBOLAS.",
  ["55:4af4"] = "KURT: Levarei um\ndia para lhe fazer\va BOLA.\fVenha buscar\ndepois.",
  ["55:4b37"] = "KURT: Oh…\nQue humilhacão.",
  ["55:4b53"] = "KURT: Estou\ntrabalhando. Não\vme atrapalhe!",
  ["55:4b76"] = "KURT: Ah, {PLAYER}!\nEu terminei a sua\vBOLA. Aqui está!",
  ["55:4ba5"] = "KURT: Ela ficou\nexcelente.\fTente capturar\nPOKéMONS com ela.",
  ["55:4bde"] = "Os SLOWPOKES\nsumiram… Será\vque pessoas ruins\vos levaram?",
  ["55:4c1a"] = "Vovô já foi…\nQue solidão…",
  ["55:4c38"] = "O SLOWPOKE que meu\npai me deu voltou!\fSua CALDA está\ncrescendo também!",
  ["55:4c7e"] = "Papai trabalha\nna SILPH onde\vestuda as POKé\vBOLAS.\fTenho que ficar\nem casa com o\vvovô e o SLOWPOKE.",
  ["55:4cee"] = "O jovem PROFESSOR\nCARVALHO?",
  ["55:4d03"] = "Uma estátua do\nprotetor da\vFLORESTA.",
  ["55:4e83"] = "Sou BUGSY!\fNunca perco quando\nuso POKéMONS\vinsetos.\fMinha pesquisa me\ntornará uma\vautoridade em\vPOKéMONS insetos!\fDeixe-me\ndemonstrar o que\veu aprendi com os\vmeus estudos.",
  ["55:4f26"] = "Uau, demais! Você\né ótimo com os\vPOKéMONS!\fTenho muito\na pesquisar ainda.\fVocê venceu. Leve\na INSÍGNIA DA\vCOLMÉIA.",
  ["55:4f8c"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vCOLMÉIA DO\vGINÁSIO DA CIDADE\vAZALEA.",
  ["55:4fa3"] = "Você conhece os\nbenefícios da\vINSÍGNIA DA\vCOLMÉIA?\fSe a tiver, os\nPOKéMONS acima do\vNÍVEL 30 vão te\vobedecer.\fPOKéMONS que\naprenderam o\vCORTA, vão poder\vusar este golpe\vfora das batalhas\vtambém.\fEi, quero que leve\nisso também.",
  ["55:5060"] = "TM49 contém\nCORTE F→RIA.  \fSe você não errar,\nesse ataque fica\vcada vez mais\vforte.\fQuanto maior for\na batalha, melhor \vo ataque ficará.  \fIsso não é ótimo?\nFui eu quem\vdescobriu isso!",
  ["55:50fe"] = "POKéMONS insetos\nsão complexos.\fTem muitos\nmistérios a\vexplorar.\fEstude seu\nfavorito por\vcompleto.",
  ["55:53fc"] = "Ei, desafiante!\fBUGSY é jovem, mas\nseu conhecimento\vde POKéMONS\vinsetos é\vincrível!\fSeria mais difícil\nsem meu aviso.\fVamos ver…\nPOKéMONS insetos\vnão gostam de\vfogo.\fGolpes de\nPOKéMONS AVES são\vsuper efetivos.",
  ["55:54bf"] = "Parabéns! Isso\nfoi um ótimo\vchoque de jovens\vtreinadores\vtalentosos.\fO futuro POKéMON\nserá brilhante com\vgente como vocês!",
  ["55:5600"] = "mais! Você\né ótimo com os\vPOKéMONS!\fTenho muito\na pesquisar ainda.\fVocê venceu. Leve\na INSÍGNIA DA\vCOLMÉIA.",
  ["55:9d51"] = "m\vna rádio!",
  ["55:ae53"] = "\nagora?",
  ["55:da52"] = "m\vuma boa seleção de\vprodutos.\fMas há itens que\nsão apenas\vavaliáveis como\vprêmios da CASA\vDE JOGOS.",
  ["56:400f"] = "Quando você pega\num POKéMON novo,\vele é fraco.\fMas com o tempo\nele vai ficar\vforte.\fÉ importante\ntratar POKéMON com\vcarinho.",
  ["56:4090"] = "POKéMON podem\nsegurar itens como\vPOTION e ANTIDOTE\fMas parece que não\nsabem usar\fitens feitos por\ngente.",
  ["56:41e0"] = "Sou FALKNER, líder\ndo GINÁSIO POKéMON\vde VIOLET!\fDizem que dá para\ncortar as asas de\fPOKéMON voadores\ncom um choque\velétrico…\fNão vou permitir\ntal insulto às\vaves POKéMON!\fVou lhe mostrar o\npoder de verdade\fdas magníficas\naves POKéMON!",
  ["56:42b7"] = "…Droga! As aves\nqueridas do meu\vpai…\fTudo bem.\nPegue isto.\fÉ a ZEPHYRBADGE\noficial da LIGA\vPOKéMON.",
  ["56:431c"] = "{PLAYER} recebeu\na ZEPHYRBADGE.",
  ["56:4335"] = "A ZEPHYRBADGE\naumenta o ataque\vdos seus POKéMON.\fEla também deixa\no POKéMON usar\fFLASH, se souber,\na qualquer hora.\fTome, leve isto\ntambém.",
  ["56:43b5"] = "Usando uma TM, o\nPOKéMON aprende\fna hora um golpe\nnovo.\fPense antes de\nagir: uma TM só\vserve uma vez.\fA TM31 tem\nMUD-SLAP.\fEla reduz a\nmira do inimigo\fenquanto causa\ndano.\fOu seja, é defesa\ne ataque ao mesmo\vtempo.",
  ["56:44a2"] = "Há GINÁSIOS\nPOKéMON em cidades\vmais à frente.\fVocê devia testar\nsua habilidade\vnesses GINÁSIOS.\fVou treinar mais\nforte para virar\fo maior mestre de\naves!",
  ["56:4666"] = "Ei! Não sou\ntreinador, mas dou\vum conselho!\fAcredite em mim!\nSe você acredita,\fo sonho de ser\ncampeão acontece.\fAcredita?\nEntão escute.\fO tipo planta é\nfraco contra o\ftipo voador. Não\nesqueça disso.",
  ["56:4735"] = "Boa batalha!\nContinue assim e\fvocê vira CAMPEÃO\nnum piscar!",
  ["56:48a8"] = "Su sou EARL!\fOs POKéMONS são\nmuito legais!\fVou ensiná-lo\na ser um melhor\vtreinador!\fO que deseja\nsaber? Quer ser um\vvencedor, não é?",
  ["56:492a"] = "Bom! Eu vou\nensiná-lo!\fNa batalha, o\nPOKéMON\vtopo de lista\vserá o primeiro!\fMudando a ordem,\nvocê pode\vfacilitar a\vbatalha!\fQuer ouvir\nmais dicas?",
  ["56:49be"] = "Então quer saber\ncomo treinar\vPOKéMONS bem?",
  ["56:49e8"] = "Bom! Eu vou\nensiná-lo!  \fUm POKéMON mesmo\nfraco pode ganhar\fmuita experiência\nnas batalhas.\fColoque o POKéMON\nfraco no topo da\vlista.\fTroque-o\nrápido! \fAssim, POKéMONS\nfracos ficam\vfortes!",
  ["56:4a9e"] = "Oh! Que bom aluno\nvocê é!\fJá te ensinei\ntudo que sei.\fVocê é ótimo\ncom POKéMONS!",
  ["56:4aed"] = "Estou aprendendo\ndicas sobre os\vPOKéMONS.\fEu devo copiar o\nque está no quadro\vtambém.",
  ["56:4b47"] = "Troquei meu\nmelhor POKéMON\vcom o cara ao\vlado.",
  ["56:4b74"] = "Hã? O POKéMON\nque eu peguei\vestá segurando\valgo!",
  ["56:4ba6"] = "Um POKéMON\nsegurando um\vfruto vai se\vcurar sozinho.\fOs POKéMONS podem\nsegurar vários\vitens…\fÉ melhor eu anotar\ntudo isso…",
  ["56:4c1f"] = "O quadro mostra\nos estados dos\vPOKéMONS que mudam\vnas batalhas.",
  ["56:4c6b"] = "O POKéMON\nenvenenado\vperde PS pouco\va pouco.\fFora das\nbatalhas eles\vperdem PS a\vmedida que você\vanda. \fUse ANTÍDOTO\npara curá-los.",
  ["56:4ced"] = "A paralisia\ntorna lento\vou impede o\vPOKéMON de agir.\fPermanece após\nas lutas. Use o\vDESPARALISIA.",
  ["56:4d4f"] = "Seu POKéMON não\npode atacar\vdormindo.\fO POKéMON\nadormecido não\vdesperta após\vas batalhas.\fDesperte-o com um\nACORDADOR.",
  ["56:4dc2"] = "O fogo tira PS\npouco a pouco.\fEle também piora o\nataque.\fO fogo ataca após\nas batalhas.\fPara curar, use o\nCURA FOGO.",
  ["56:4e38"] = "Se seu POKéMON se\ncongelar, ele não\vfará nada.\fFicará congelado\napós as\vbatalhas.\fCure-o com um\nCURA GELO.",
  ["56:4ea3"] = "É o caderno do\ngaroto…\fCapturar POKéMONS\nusando POKé BOLAS.\fPode ficar com\naté 6 POKéMONS na\vequipe.\fLer mais?",
  ["56:4f04"] = "Antes de jogar a\nPOKéBOLA, deixe o\valvo fraco.\fOs POKéMONS com\nveneno ou\vqueimados são mais\vfáceis de pegar.\fLer mais?",
  ["56:4f74"] = "Alguns movimentos\ncausam confusão.\fA confusão pode\nfazer o POKéMON se\vatacar.\fFugindo, ele\nfica curado da \vconfusão.\fLer mais?",
  ["56:4ff4"] = "Quem pega e usa\nos POKéMON nas\vbatalhas, são\vtreinadores\vPOKéMON.\fEles devem\nvisitar GINÁSIOS\vPOKéMON e\vderrotar outros\vtreinadores.\fA outra página\nestá vazia!\fGaroto: Opa…\fNão escrevi\nmais nada…",
  ["56:5167"] = "Ela usa nomes de\nsuas comidas\vprediletas.\fEla faz isso nos\napelidos dos\vPOKéMONS pelo que\veu percebi.",
  ["56:51cb"] = "Chamo o meu PIDGEY\nde MORANGO!",
  ["56:51e9"] = "MORANGO: Pijji!",
  ["56:52c2"] = "Há quanto tempo,\n{PLAYER}!\fO PROFESSOR ELM\nme pediu para\vachá-lo.\fEle quer um\nfavorzinho.\fDeseja levar este\nOVO POKéMON?",
  ["56:5332"] = "Ele descobriu que\no POKéMON não\vchocará até\vcrescer dentro\vdo OVO.    \fTem que estar\njunto com POKéMONS\fativos para\nchocar.\f{PLAYER}, você\né o único que\fpodemos confiar.\fAvise ao PROFESSOR\nELM quando o OVO\vchocar!",
  ["56:5400"] = "Ah não. Você está\ncheio de POKéMONS\vai com você. \fVou esperá-lo\naqui enquanto\vlibera espaço.",
  ["56:545f"] = "Mas o PROFESSOR\nELM te pediu…",
  ["56:547f"] = "{PLAYER}, vai\nficar com o\vOVO?",
  ["56:549a"] = "Um tal de BILL\nfez o SISTEMA DE\vARMAZENAR OS\vPOKéMONS.",
  ["56:54cd"] = "Foi há três anos\natrás.\fA EQUIPE ROCKET\nroubava e mal-\vtratava os\vPOKéMONS.\fMas a justiça\nvenceu. Um jovem\vacabou com eles.",
  ["56:5549"] = "Os POKéMONS são\nespertos!\fNão obedecem a\num treinador sem\vrespeito.\fSem as INSÍGNIAS\ncorretas, eles\vfarão apenas o que\vquiserem.",
  ["56:5628"] = "Os POKéMONS troca-\n\ndos crescem\vrapidamente. \fCaso não tenha\nas INSÍGNIAS\vcorretas,\veles podem\vdesobedecê-lo.",
  ["56:56c7"] = "RUÍNAS ALFA\fUm Ponto Turístico\nbem livre.\fTente mover as\npedras do painel!",
  ["56:5712"] = "Está estudando as\nRUÍNAS?\fHá cientistas\nenvolvidos nisso.",
  ["56:574e"] = "Há desenhos no\npainel de pedra.\fEu tentei\nmovê-los.\vO que eles devem\vser?",
  ["56:5814"] = "Esse é um ponto\nde pesca.\fVocê viu pessoas\npescando? O que \vachou?\fVocê quer uma\ndas minhas VARAS?",
  ["56:5879"] = "Eh, é bom ouvir\nisso.\fAgora é um\npescador também!",
  ["56:58ac"] = "Pescar é ótimo!\fSe tiver água,\nseja no mar ou\vem outro lugar,\vuse a sua VARA.",
  ["56:58fd"] = "Oh. Isso é bem\ndesapontador…",
  ["56:591e"] = "Ei, meu jovem.\nComo eles mordem?",
  ["56:5943"] = "O que devo fazer\no meu POKéMON\vsegurar?\fTalvez algo que\nmelhore o seu\vATAQUE…",
  ["56:5a70"] = "Com licença,\namigo!\fPode me fazer um\nfavor?\fVocê pode entregar\neste POKéMON com\vuma CARTA a um\vcolega na ROTA 31?",
  ["56:5adb"] = "Você irá? Ótimo!\nObrigado!\fMeu amigo é meio\ngordo, e dorme o\vtempo todo!\fVocê o reconhecerá\ncom facilidade!",
  ["56:5b4b"] = "{PLAYER} recebeu o\nPOKéMON com uma\vCARTA.",
  ["56:5b69"] = "Você pode ler,\nmas não a perca!\vROTA 31!\fExiste uma\nárvore misteriosa\vbloqueando a\vpassagem.\fSerá que eu, fui\nbem claro agora?",
  ["56:5be9"] = "Não pode carregar\nmais POKéMONS…",
  ["56:5c07"] = "Ah… Não tem\nproblema…",
  ["56:5c1e"] = "Obrigado, rapaz!\nVocê fez a entrega\vpara mim!\fEu tenho algo\npara te ajudar!",
  ["56:5c6c"] = "Meu amigo estava\ndormindo, certo?\fEh, o que eu digo?",
  ["56:5c9d"] = "Uma árvore\nestranha está\vbloqueando a\vestrada.\fEla se mexe caso\nfale com ela!\fEla se transforma\nem um POKéMON se\vvocê usar o POTE\vSQUIRT nela!",
  ["56:5d2d"] = "Eu gosto da\nmelodia POKéMON\vque eles tocam\vna rádio!",
  ["56:5ef2"] = "Hoje é {STRBUF}.\nSignifica que\vo Concurso\vCaça-Inseto é\vhoje.\fAs regras são\nsimples.\fUsando um dos seus\nPOKéMONS, pegue um\vPOKéMON inseto\vpara ser julgado.\fDeseja participar?",
  ["56:5fa4"] = "Aqui estão as\nBOLASPARQUE para o\vevento.",
  ["56:5fce"] = "{PLAYER} recebeu\n20 BOLASPARQUE.",
  ["56:5fe9"] = "Quem pegar o\nPOKéMON inseto\vmais poderoso será\vo vencedor.\fVocê tem 20\nminutos.\fSe você ficar sem\nBOLASPARQUE, o\vevento acaba.\fVocê pode ficar\ncom o último\vPOKéMON que\vcapturou.\fSaia e capture o\nPOKéMON inseto\vmais poderoso que\vpuder encontrar!",
  ["56:60cd"] = "Opa…\fVocê tem mais do\nque um POKéMON.\fVocê terá que usar\no {STRBUF}, seu \fprimeiro POKéMON\nna sua equipe.\fTudo certo, rapaz?",
  ["56:613e"] = "Bom, ficaremos\ncom os outros\vPOKéMONS enquanto\vcompetir.",
  ["56:619e"] = "Escolha o\nPOKéMON a ser usado no\vconcurso e volte\vaqui mais tarde.",
  ["56:61e3"] = "Certo. Contaremos\ncom você na\vpróxima vez.",
  ["56:620f"] = "Opa…\fO primeiro POKéMON\nna sua equipe não\vpode batalhar.\fTroque-o pelo\nPOKéMON que quiser\vusar e volte aqui\voutra hora.",
  ["56:6283"] = "Opa…\fTanto sua equipe\nquanto seu BOX\vestão cheios.\fVocê não tem lugar\npara colocar o\vPOKéMON inseto que\vpegou.\fLibere espaço na\nsua equipe ou no\vBOX e retorne\vaqui.",
  ["56:6326"] = "Opa…\fO primeiro POKéMON\nda sua equipe é\vum OVO.\fTroque-o pelo\nPOKéMON que deseja\vutilizar no\vconcurso e retorne\vaqui outra hora.",
  ["56:63a1"] = "Você ainda tem\n{STRBUF} minuto(s)\vsobrando.\fDeseja parar\nagora?",
  ["56:63e2"] = "Certo. Aguarde na\nCabine do Norte\vpara a divulgação\vdos vencedores.",
  ["56:642a"] = "Bom, volte lá e\nfique até o fim\vdo concurso.",
  ["56:6456"] = "O concurso de hoje\nacabou.\fEsperamos\nque participe\vfuturamente.",
  ["56:649b"] = "Fazemos Concursos\nregularmente no\vPARQUE.\fVocê deve\nparticipar.",
  ["56:64df"] = "Quando acontecerá\no próximo Concurso\vCaça-Inseto?",
  ["56:6515"] = "O Concurso\nCaça-Inseto\vacontece às\vTerças, Quintas e\vaos Sábados.\fAlém de ganhar um\nprêmio por apenas\vparticipar, você\vtambém fica com o\vPOKéMON que você\vcapturou.",
  ["56:660d"] = "Não queria\nsaber quem fez\valgo como isso?\vE por que?",
  ["56:6648"] = "Você viu aquela\nárvore estranha\vna estrada?\fIsso explica\npor que muitos\vturistas visitam\vas RUÍNAS ALPH.",
  ["56:69c0"] = "Hoje é {STRBUF}.\nSignifica que\vo Concurso\vCaça-Inseto é\vhoje.\fAs regras são\nsimples.\fUsando POKéMONS\nseus, pegue um\vPOKéMON inseto\vpara ser julgado.\fDeseja participar?",
  ["56:6a70"] = "Aqui estão as\nBOLAS PARQUE para\vo Concurso.",
  ["56:6a9a"] = "{PLAYER} recebeu 20\nBOLAS PARQUE.",
  ["56:6ab5"] = "Quem pegar o\nPOKéMON inseto\vmais forte, será\vo vencedor.\fVocê tem 20\nminutos.\fSe ficar sem BOLAS\nPARQUE, o jogo\vacaba.\fVocê ficará com o\núltimo POKéMON que\vpegar.\fVá e capture o\nPOKéMON inseto\vmais forte que\vachar!",
  ["56:6b99"] = "Opa…\fVocê tem mais\ndo que um POKéMON.\fTerá que\nusar {STRBUF}, o\vprimeiro POKéMON\vna sua equipe.\fEstá tudo bem com\nvocê?",
  ["56:6c0a"] = "Ótimo. Vamos ficar\ncom seus outros\vPOKéMONS enquanto\vvocê compete.",
  ["56:6c3e"] = "{PLAYER} deixou\nseus POKéMONS com\vo ORGANIZADOR DO\vCONCURSO.",
  ["56:6c6a"] = "Escolha o POKéMON\na ser usado no\vconcurso e venha\vme ver.",
  ["56:6caf"] = "Certo. Esperamos\nque você participe\vno futuro.",
  ["56:6cdb"] = "Opa… O primeiro\nPOKéMON na sua\vequipe não pode\vbatalhar.\fTroque-o por outro\nPOKéMON que\vdesejar e volte\vaqui depois.",
  ["56:6d4f"] = "Opa… Sua equipe\ne seu BOX do\vcomputador estão\vcheios.\fVocê não tem lugar\npara colocar o\vPOKéMON que\ncapturar.\fLibere espaço na\nsua equipe ou\nem seu BOX do\vcomputador e volte\vaqui depois.",
  ["56:6df2"] = "Opa… Seu primeiro\nPOKéMON na equipe\vé um OVO.\fTroque-o pelo\vPOKéMON que\vdesejar e depois\vvolte aqui.",
  ["56:6e6d"] = "Você ainda tem\n{STRBUF} minuto(s)\vsobrando.\fDeseja parar\nagora?",
  ["56:6eac"] = "Certo. Espere aqui\npara o anúncio dos\vvencedores.",
  ["56:6ee7"] = "Certo. Fique lá\naté terminar.",
  ["56:6f12"] = "O concurso de hoje\njá acabou.\fEsperamos que\nparticipe no\vfuturo.",
  ["56:6f57"] = "Alguns POKéMONS\nsó podem ser\vencontrados aqui\vno PARQUE.",
  ["56:6f80"] = "DON: Uau, você me\nsuperou. Você é\vótimo.",
  ["56:6fab"] = "DON: A sorte tem\num grande papel\vnisso.\fVocê nunca sabe\nqual POKéMON vai\vaparecer.",
  ["56:6ff6"] = "ED: Eu invejo\nvocê. Eu não fui\vcapaz desta vez.",
  ["56:7027"] = "ED: Será que você\nganharia com um\vPOKéMON grande?",
  ["56:7049"] = "NICK: Bom\ntrabalho! Eu vou\vtreinar melhor meu\vPOKéMON.",
  ["56:707d"] = "NICK: Talvez você\nobtenha uma\vpontuação maior\vcom um POKéMON de\vuma cor incomum.",
  ["56:70c1"] = "WILSON: Você é o\nvencedor? O que\vvocê capturou?",
  ["56:70f1"] = "WILSON: Bem, eu\nestou satisfeito\vporque eu capturei\vo POKéMON que eu\vdesejava.",
  ["56:7135"] = "BENNY: Parabéns!\nVocê conquistou\vmeu respeito.",
  ["56:7163"] = "BENNY: Eu peguei\num SCYTHER\vanteriormente, mas\veu não ganhei.",
  ["56:7197"] = "BARRY: Aquele\nPOKéMON que você\vcapturou… é\vincrível!",
  ["56:71c4"] = "BARRY: É fácil\nvencer quando se\vpega um POKéMON\vinseto de nível\valto.\fMas acho que\neles levam outros\vfatores em\vconsideração.",
  ["56:7232"] = "CINDY: Você\nvenceu? Isso é\vótimo!\fLigaria se\nprocurasse\vPOKéMONS insetos\vcomigo?",
  ["56:727f"] = "CINDY: Eu\nrealmente amo\vPOKéMONS insetos!",
  ["56:729f"] = "JOSH: Eu… eu não\nacredito que perdi\vesse concurso…",
  ["56:72d0"] = "JOSH: Ouvi dizer\nque alguém já\vvenceu com um\vCATERPIE!",
  ["56:7302"] = "SAMUEL: Na próxima\neu ganharei.",
  ["56:7327"] = "SAMUEL: Droga.\nAchei que eu tinha\vido melhor…",
  ["56:7356"] = "KIPP: Poderia me\ndar conselhos?\fQuero estudar seu\nestilo.",
  ["56:7396"] = "KIPP: Eu estudo\nmuito, mas não é\vo bastante para\vvencer.",
  ["56:74dd"] = "Opa… Sua BOLSA\nestá cheia.\fVamos guardar o\nseu prêmio, mas\vsó até o fim deste\vdia.\fLibere espaço\ve depois venha\vreceber o seu\vprêmio.",
  ["56:9c45"] = " esse prêmio.\fFaça um POKéMON\nsegurar.",
  ["56:a000"] = " dos\vPOKéMONS.",
  ["57:4122"] = "Oi! Sou WHITNEY!\fTodo mundo gosta\nde POKéMONS,  \vinclusive eu!\fOs POKéMONS são\nsuper bonitos!\fVocê quer\nbatalhar?\vVou te avisar,\veu sou boa!",
  ["57:41a5"] = "Hã?…\f…Buaaaaaaa!\nVocê mentiu!\fVocê não devia\nlutar sério!\vSua, sua,\vcriança!",
  ["57:41f5"] = "Buaaaah!\nBuaaaaa!\f…Droga, hic…\n…Mentiroso!",
  ["57:4223"] = "…Sniff…\fO quê?\nO que você quer?\fA INSÍGNIA?\fCerto.\nEu esqueci.\fLeve a INSÍGNIA\nPLANA.",
  ["57:4278"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA PLANA\vDO GINÁSIO DA\vCIDADE GOLDENROD.",
  ["57:4290"] = "A INSÍGNIA PLANA\npermite ao\vPOKéMON usar o HM\vFORÇA fora de\vbatalhas.\fTambém melhora a\nVELOCIDADE do\vPOKéMON.\fAh, leve isto\ntambém!",
  ["57:4307"] = "É o ATRAI!\fIsso faz com que o\nPOKéMON use seu\vCHARME!\fNão é perfeito\npara facilmente\vpegar POKéMONS?",
  ["57:44de"] = "Oh, não. Você fez\nWHITNEY chorar.\fTudo bem, ela\njá parou.\fSempre chora\nquando perde!",
  ["57:4644"] = "Oi! Seja\nBem-vindo!\fEste GINÁSIO é a\ncasa dos POKéMONS\vdo tipo normal.\fEu recomendo usar\nPOKéMONS lutadores\vna batalha!",
  ["57:46b1"] = "Você venceu?\nÓtimo.\fEstava ocupado\nadmirando-as!",
  ["57:4791"] = "…Poxa…\nMe mudei para cá,\vmas não consigo\vvender. Por que\vserá?\fVocê pode pegar\numa BICICLETA e\vfazer propaganda?",
  ["57:4802"] = "Serio?\nÓtimo!\fMe dê seu nome\ne número, que\vte empresto uma\vBICICLETA, amigo.",
  ["57:4852"] = "{PLAYER} pegou\na BICICLETA.",
  ["57:4869"] = "Minhas BICICLETAS\nsão de primeira,\vsobem até\vladeiras.",
  ["57:48a2"] = "…Poxa…\nHá poucas pessoas\vgenerosas!",
  ["57:48f7"] = "Poxa, uma\nBICICLETA nova!",
  ["57:49ad"] = "Se você tratar\nseus POKéMONS\vbem, eles irão\vte amar também.\fDeixe-me ver o seu\n{STRBUF}…",
  ["57:4a06"] = "Ele parece\nrealmente feliz.\fEle te ama\nmuito!",
  ["57:4a36"] = "Tenho certeza,\nque ele confia\vmuito em você.",
  ["57:4a98"] = "Muito atraente.",
  ["57:4aa9"] = "Você devia\ntrata-lo melhor.\fEle quase não\nluta!",
  ["57:4adb"] = "Ele parece não\ngostar de você.\vIsso parece ruim.",
  ["57:4b0e"] = "Eu continuo\nperdendo nas\vbatalhas.\fE meu POKéMON\nfica desmaiado.\fPor isto ele não\ngosta muito de\vmim!",
  ["57:4b71"] = "Quando eu uso um\nartigo no meu\vPOKéMON, ele fica\valegre!",
  ["57:4c7e"] = "BILL: Olá,\n{PLAYER}!\fFaça-nos um favor\ne leve esse EEVEE.\fEle veio aqui\nquando eu estava\vajustando a\vCÁPSULA DO TEMPO.\fAlguém deve cuidar\ndele, mas eu não\vtenho tempo.\fPosso\vcontar com você\vpara isso,\v{PLAYER}?",
  ["57:4d49"] = "BILL: Eu sabia!\nHora de ir, herói!\fVocê é um grande\namigo, rapaz!\fBem, eu conto com\nvocê. Cuide muito\vbem dele.",
  ["57:4db5"] = "{PLAYER} recebeu\nEEVEE!",
  ["57:4dc8"] = "BILL: O PROFESSOR\nELM afirma que o\vEEVEE pode evoluir\vde várias e\vdesconhecidas\vmaneiras.",
  ["57:4e09"] = "Opa! Você não pode\nlevar mais\vPOKéMONS!",
  ["57:4e34"] = "Oh… O que fazer\nagora?",
  ["57:4e49"] = "BILL: Eu fazia\nexperiências com\vTELETRANSPORTA-\vDORES.\fEu devo fazer uma\ncontinuação.",
  ["57:4e93"] = "Ah, você coleciona\nPOKéMONS?\fMeu filho BILL é\num perito.\fEle teve que\npartir para o\vCENTRO POKéMON na\vCIDADE ECRUTEAK!",
  ["57:4efa"] = "Estou tão feliz\nem ver meu filho\vde novo.",
  ["57:4f1d"] = "Você é um\ntreinador?\fEu tenho um\nnúmero de telefone\vútil para você.",
  ["57:4f58"] = "{PLAYER} gravou\no número do BILL.",
  ["57:4f72"] = "Meu irmão fez o\nsistema de guardar\vPOKéMONS no PC.\fEu iria te dar o\ntelefone do BILL…",
  ["57:4fc5"] = "Você não pode\ngravar mais\vnúmeros.",
  ["57:4fe8"] = "Meu irmão mais\nvelho, BILL, fez\vo sistema de\varmazenar POKéMONS\vno PC.",
  ["57:50d7"] = "O trêm não\nchegou…\fEu sei!\nOs passageiros\vvão me pedir\vexplicações.\fEle não funciona.",
  ["57:512e"] = "Em breve\npartiremos para\vSAFFRON.\fVocê deseja\nembarcar?",
  ["57:5164"] = "Eu posso ver seu\nPASSE?\fCerto. É por aqui,\nsenhor.",
  ["57:51a0"] = "Perdão. Você não\ntem um PASSE.",
  ["57:51c3"] = "Nós esperamos\nvê-lo novamente!",
  ["57:51de"] = "Nós chegamos à\nGOLDENROD.\fNós esperamos\nvê-lo de novo.",
  ["57:5217"] = "Eu sou o\nPRESIDENTE.\fMeu sonho foi\nconstruir um trêm\vque fosse mais\vveloz que todos\vPOKéMONS.\fEle aproxima\nJOHTO de KANTO.",
  ["57:5311"] = "Oh, você é melhor\nque WHITNEY.\fSabe algo sobre\na árvore maluca?\fSe você molhá-la\ncom o POTE SQUIRT,\vela atacará.\fMas se você tiver\nINSÍGNIAS, vai dar\vtudo certo.",
  ["57:53b6"] = "Lalala lalalala.\nTomem muita água \vmeus amores!",
  ["57:53e9"] = "Quando eu reguei\naquela árvore da\vROTA 36, ela\vsaltou!\fAcho que ela é\num POKéMON.\fMas WHITNEY, nossa\n\nLÍDER DO GINÁSIO,\vpoderia derrotar\vesse estranho\vPOKéMON.",
  ["57:5485"] = "Sabe algo sobre\na árvore maluca?\fSe você regá-la,\nele dá um pulo\vem você!",
  ["57:5513"] = "O COLISEU, no\nandar superior de\vqualquer CENTRO\vPOKéMON, foi feito\vpara batalhas\vconectadas.\fOs recordes de\nbatalhas ficam\vexpostos na\vparede, então não\vposso pensar em\vperder.",
  ["57:5597"] = "Eu queria saber\nquantos POKéMONS\vhá no mundo.\fO PROFESSOR\nCARVALHO, a três\vanos atrás, disse\vque havia 150\vtipos diferentes.",
  ["57:5614"] = "Um POKéMON de\nnível mais alto\vnem sempre ganha.\fPois, ele pode ser\nfraco contra um\vtipo de POKéMON.\fAcho que não\nexiste um POKéMON\vforte contra todos\vos tipos.",
  ["57:56fe"] = "Uma vez quando\nestava batalhando,\vmeu POKéMON não\vtinha poderes.\fOs PONTOS de\nPODER, ou PP,\vcriam um tipo\vde ataque!",
  ["57:576f"] = "As vezes, um\nPOKéMON saúdavel\vé incapaz de\vutilizar um\vataque.\fSe isto acontecer,\nleve-o a um CENTRO\vPOKéMON ou lhe\vdê um artigo.",
  ["57:5a38"] = "Bem-vindo à LOJA\nDE DEPARTAMENTOS\vDE GOLDENROD!",
  ["57:5a5c"] = "A LOJA DE\nDEPARTAMENTOS tem\vuma boa seleção de\vprodutos.\fMas há itens que\nsão apenas\vavaliáveis como\vprêmios da CASA\vDE JOGOS.",
  ["57:5abf"] = "Hoje eu vim fazer\ncompras de novo!",
  ["57:5adf"] = "Minha mãe é boa em\npechinchar.\fEla sempre compra\ncoisas baratas.",
  ["57:5b25"] = "1º ANDAR-RECEPÇÃO\f2º-LOJA DO\nTREINADOR\f3º-ITENS DE\nBATALHAS\f4º-LOJA DE\nREMÉDIOS\f5º-LOJA DE TM\f6º-PRAÇA DO\nTELHADO.",
  ["57:5cb7"] = "A POKéGEAR pode\narmazenar até dez\vtelefones.\fÉ difícil escolher\nos números que\vficarão.",
  ["57:5d0d"] = "Eu ganhei meu ABRA\nna CASA DE JOGOS.\fAgora é meu melhor\nparceiro.",
  ["57:5d49"] = "Está LOJA me faz\nperceber que\vGOLDENROD é uma\vgrande cidade.\fOs produtos aqui\nnão se encontram\vem nenhum lugar!",
  ["57:5dba"] = "Seu amigo de\nviagem.\f2º ANDAR-\nLOJA DO TREINADOR.",
  ["57:5e5e"] = "Eu, eu sou muito\nimpaciente!\fEu uso RAPIDEZ\nX nas batalhas\vpara acelerar o\vPOKéMON.",
  ["57:5ea7"] = "Ei, quando\nbatalha, você usa\vo ESPECIAL X?\fÉ incrível!\fEle melhora o\nESPECIAL do\vPOKéMON!",
  ["57:5f09"] = "Para quem quer\nvencer!\f3º ANDAR-ITENS DE\nBATALHA.",
  ["57:5f9d"] = "Ei. Eu adoro\nPOKéMONS fortes.\fEu dou PROTEÍNA\naos POKéMONS para\vaumentar seus\vATAQUES!",
  ["57:5fe7"] = "O FERRO aumenta a\nDEFESA dos\vPOKéMONS.",
  ["57:6009"] = "Alguns POKéMONS só\nevoluem se forem\vtrocados através\vdo CABO LINK.\fEu sei quatro:\nMACHOKE, KADABRA,\vHAUNTER e, hum,\vGRAVELER.\fDizem que ainda\nhá outros\vPOKéMONS.",
  ["57:60a2"] = "Melhore seu\nPOKéMON\f4º ANDAR-LOJA DE\nREMÉDIOS.",
  ["57:61d8"] = "Olá. Oh, seu\nPOKéMON…",
  ["57:61ef"] = "É muito atraído a\nvocê.\fEsse golpe deve\nser perfeito para\vum par como vocês.",
  ["57:623b"] = "É adorável!\fVocê deve\nensiná-lo bons\vgolpes TM.",
  ["57:626d"] = "Esse parece mau.\nQue tal esse TM\vpara ele(a)?",
  ["57:6297"] = "Certamente há TMs\nque são perfeitos\vpara os seus\vPOKéMONS.",
  ["57:62d6"] = "ITEM SECRETO.\fCom um pequeno\nbip, você ganha\vpresentes!",
  ["57:630e"] = "A opção ITEM\nSECRETO requer um\vGame Boy Color.",
  ["57:6342"] = "Aos domingos, uma\nsenhora vem ver os\vPOKéMONS.\fEla até faz\ndoações de TMs!",
  ["57:6388"] = "Você não pode\nrenomear os\vPOKéMONS trocados.\fOs nomes são os\nreflexos dos\vsentimentos que os\vex-treinadores\vtinham por eles.",
  ["57:63f9"] = "Equipe o seu\nPOKéMON\f5º ANDAR-LOJA DE\nTM.",
  ["57:6560"] = "Uma Máquina de\nVenda!\vOlhe o MENU.",
  ["57:6584"] = "Click! Saiu uma\nlata de\v{STRBUF}!",
  ["57:65a7"] = "Opa, quantia\ninsufuciente.",
  ["57:65c0"] = "Não há mais espaço\npara isso.",
  ["57:65e0"] = "Você ouve o CANAL\nda SORTE?\fSe você quiser\nganhar, troque\vPOKéMONS com o\vmáximo de pessoas\vpossíveis para ter\vvários N→MEROS DE\vIDENTIFICAÇÃO.",
  ["57:665f"] = "Se estiver\ncansado, beba as\vbebidas da máquina\vde venda.\fOs seus POKéMONS\nvão adorar também!",
  ["57:66af"] = "Descanse Das\nCompras!\f6º ANDAR-PRAÇA DO\nTELHADO.",
  ["57:6ab5"] = "Bem-vindo!\fNós trocamos suas\nmoedas por ótimos\vprêmios!",
  ["57:6af0"] = "De qual prêmio\nvocê gosta?",
  ["57:6b0d"] = "{STRBUF}.\nEstá certo?",
  ["57:6b22"] = "Aqui está!",
  ["57:6b30"] = "Perdão! Precisa\nde mais moedas!",
  ["57:6b4d"] = "Perdão! Não pode\ncarregar mais.",
  ["57:6b6e"] = "Bom, guarde suas\nmoedas e volte\vdepois!",
  ["57:6b9a"] = "Oh? Você não tem\num COFRE.",
  ["57:6bba"] = "Eu sempre jogo\nnesta máquina.\fAcho que ela paga\nmais que as\voutras.",
  ["57:6c03"] = "Eu amo esta nova\nMÁQUINA de JOGO.\fÉ mais difícil\nque aquelas da\vCIDADE CELADON.",
  ["57:6c59"] = "A vida é jogar.\nEu jogarei até\vacabar minhas\vmoedas!",
  ["57:6c90"] = "Cartões…\fEu prefiro usar o\ncartão, porque\vé mais difícil de\vperder, não acha?\fPorém o pagamento\né menor.",
  ["57:6cfc"] = "Eu não saio,\naté ganhar!",
  ["57:6d16"] = "Eu ensinei\nTEMPORAL ao meu\vPOKéMON.\fFoi duro conseguir\nmoedas para isto,\vmas valeu a pena,\vcara.",
  ["57:6d72"] = "Eu não ganhava nas\nMÁQUINAS nem\vjogando CARTAS.\fEu fiquei\nirritado, e acabei\vdeixando meu COFRE\vcair no SUBTERRÂ-\vNEO.",
  ["57:6f2c"] = "A FLORESTA ILEX\né grande. Cuidado.\vNão se perca.",
  ["57:6f5c"] = "A FLORESTA é\nobservada pelo seu\vprotetor.\fNão faça\ntravessuras!",
  ["57:6ffe"] = "Ah, querido. Você\nestá completando\va POKéDEX?\fDeve ser difícil\nse o POKéMON não\vaparecer.\fTente usar esse\nTM.",
  ["57:7057"] = "É o ODOR DOCE.\fUse isso em\ntodo lugar que\vapareçam POKéMONS!\fIsso vai\natrai-los.",
  ["57:70b6"] = "Você viu o\nsantuário em honra\vdo protetor da\vfloresta?\fEle vigia a\nFLORESTA há muito\vtempo.\fEu acho que ele é\num POKéMON do tipo\vgrama.",
  ["57:71b8"] = "Vovô procurava\npor você.",
  ["57:c700"] = " jeito que\na CLEFAIRY balança\vos dedos quando\vtenta usar o\vMETRÔNOMO.\fÉ tão adorável!",
  ["59:400b"] = "Eu sou o PESCADOR\nLÍDER, eu comando\vos IRMÃOS\vPESCADORES.\fVocê conhece o\nPESCADOR WILTON?\fEle pesca na\nROTA 44.\fEle me deu uma\nincrível dica no\vtelefone.\fGraças a ele, eu\ncapturei uma\vgrande quantidade\vde POKéMONS muito\vraros.\fFoi um dia e\ntanto!",
  ["59:40fa"] = "É uma foto de\npessoas pescando…\fElas estão se\ndivertindo…",
  ["59:4177"] = "Um POKéMON\ndorminhoco está\ndescançando em\vfrente à CAVERNA\vDO DIGLETT.\fÉ uma ótima\noportunidade para\vpegá-lo, mas como\vvai acordá-lo.",
  ["59:41ef"] = "Havia um\nPOKéMON dorminhoco\vdescansando em\vfrente à CAVERNA\vDO DIGLETT.  \fMas parece que\nele desapareceu.",
  ["59:4255"] = "O NAVIO VELOZ é um\nexcelente local\vpara treinadores\vse encontrarem e\vbatalharem.",
  ["59:4292"] = "Oh? Você possui\nINSÍGNIAS que eu\vnunca tinha visto\vantes!\fAh, agora eu\nentendi!\fVocê as obteve no\ncontinente JOHTO.",
  ["59:43d8"] = "Eu sou o\nPRESIDENTE do\vCLUBE DOS FÃS\vPOKéMON.\fEu criei em torno\nde 150 POKéMONS.\fEu sou muito\nexigente quando se\vtrata de POKéMONS.\fVocê veio aqui só\npara ouvir sobre\vos meus POKéMONS?",
  ["59:4468"] = "Ótimo!\fPreste atenção!\fBom… o\nmeu favorito é o\vRAPIDASH.\fEle é… lindo…\namável… esperto…\vprestativo…\vfantástico… Oh…\fVocê também acha?…\nBastante…\vselvagem… bonito…\vgentil… eu o amo!\fO abraço… quando…\ndurmo… é morno e\vmacio…\fOh, é…\nespetacular…\vencantador…\ve simplesmente\vdivino…\fOpa! Olhe as\nhoras!\fEu gastei muito\ndo seu tempo!",
  ["59:4594"] = "Obrigado por me\nescutar.\fEu quero que\naceite isso!",
  ["59:45c9"] = "É o DOCE RARO que\ntorna o POKéMON\vmais poderoso.\fEu prefiro\nfortaceler meu\vPOKéMON com\vbatalhas, portanto\vvocê pode levá-lo.",
  ["59:4637"] = "Olá, {PLAYER}!\fVocê veio aqui\npara saber sobre\vo meu POKéMON de\vnovo?\fNão?\fOh… Eu tenho mais\ncontos para\vcontar…",
  ["59:468f"] = "Que pena…\fVolte aqui se\nquiser escutar.",
  ["59:46c4"] = "Nosso PRESIDENTE é\nmuito oral quando\vse trata de\vPOKéMONS…",
  ["59:46f7"] = "Eu amo o jeito que\na CLEFAIRY balança\vos dedos quando\vtenta usar o\vMETRÔNOMO.\fÉ tão adorável!",
  ["59:4756"] = "Eu amo a CLEFAIRY,\nmas eu nunca\vcapturei uma.\fEu a substituo\npela BONECA que\veu achei.",
  ["59:47b1"] = "Oh, eu entendi.\nA garota que\vperdeu essa BONECA\vestá triste…\fPoderia levar esta\nBONECA àquela\vpobre garotinha?\fEu capturarei uma\nCLEFAIRY para\vmim um dia.\fSem dúvidas!",
  ["59:4861"] = "{PLAYER} recebeu a\nBONECA.",
  ["59:4875"] = "Você verá!\fEu ainda terei\numa verdadeira\vCLEFAIRY como\vamiga.",
  ["59:48af"] = "Sua BOLSA está\nmuito cheia.",
  ["59:48ca"] = "Olhe a minha\ncorajosa BAYLEEF!\fA folha em sua\ncabeça é tão\vlinda!",
  ["59:4908"] = "É uma CLEFAIRY?\fHã?\fAh, bem. É uma\nBONECA CLEFAIRY.",
  ["59:4953"] = "Vamos escutar com\nrespeito à todos\vos treinadores.",
  ["59:4980"] = "Quem falar com\narrogância, será\vrespondido da\vmesma forma!",
  ["59:4a17"] = "Você sabe algo\nsobre o TRÊM\vMAGNETO?\fÉ uma estrada de\nferro que vai à\vGOLDENROD no\vcontinente JOHTO.",
  ["59:4a6d"] = "Eu quero ir à\nSAFFRON para ver\vo TRÊM MAGNETO.",
  ["59:4ae2"] = "A EQUIPE ROCKET\nnão está mais em\vKANTO.\fIsso me deixa\nfeliz.",
  ["59:4b21"] = "Estou pensando em\nir fazer compras\vem SAFFRON.",
  ["59:4b8b"] = "No passado, os\nDIGLETTS cavaram\vum largo túnel que\vvai à uma cidade\vdistante.",
  ["59:4c99"] = "SURGE: Ei,\ngarotinho!\fTenho que cuidar\nde você.\fPode não ser muito\nesperto em me\vdesafiar, mas \vtudo bem!\fQuando se trata\nde POKéMONS\velétricos, eu sou\vo número um!\fEu nunca perdi no\ncampo de batalha.\fVou derrotá-lo\ncomo fiz com\vmeus inimigos na\vguerra!",
  ["59:4d8a"] = "SURGE: Arrrgh!\nVocê é poderoso!\vCerto garoto. Você\vlevará a INSÍGNIA\vDO TROVÃO.",
  ["59:4dc9"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DO\vTROVÃO do GINÁSIO\vDA CIDADE\vVERMILION.",
  ["59:4de3"] = "SURGE: A INSÍGNIA\nDO TROVÃO melhora\va velocidade do\vPOKéMON.\fPense nisso como\nprova de que me\vderrotou.\fSe sente\norgulhoso?",
  ["59:4e55"] = "SURGE: Ei, garoto!\nContinua agindo\vfeito lesma por\vaí?\fMeus POKéMONS e eu\nainda somos os\vmelhores!",
  ["59:5069"] = "Ei! CAMPEÃO em\nprogresso. Você\vteve sorte desta\vvez.\fO TENENTE SURGE é\nbem cauteloso.\fEle fez armadilhas\npor todo GINÁSIO.\fMas, he-he-he, as\narmadilhas estão\vdesativadas.\fVocê facilmente\nalcançará o\vTENENTE SURGE.",
  ["59:5131"] = "Uau! Essa foi uma\nbatalha elétrica!\fCertamente me\ndeixou nervoso.",
  ["59:5170"] = "Não há nada aqui\nalém de lixo.",
  ["59:5250"] = "Bem-vindo à CIDADE\nSAFFRON, lar do\vTRÊM MAGNETO!\f…É o que eu\nnormalmente digo,\vmas o TRÊM\vMAGNETO não está\vfuncionando agora.\fNão há\neletricidade\vporque existe algo\vde errado com a\vUSINA DE ENERGIA.",
  ["59:531d"] = "O TRÊM MAGNETO é a\ncoisa mais famosa\vaqui na CIDADE\vSAFFRON.",
  ["59:53bb"] = "Oi!\fASH tem estado\nfora há muito\vtempo.\fEle não telefona,\nentão não tenho\vidéia de onde ele\vestá nem do que\vfaz agora.\fDizem que nenhuma\npalavra é prova\vde que ele está\vbem.\fEstou preocupada.",
  ["59:547c"] = "Se ele estiver\ndoente ou\vmachucado?\fEle é um garoto.\fEstou orgulhosa\nporque ele faz o\vque ele quer.",
  ["59:54e3"] = "Eles tem programas\nque não passa lá\vem JOHTO…",
  ["59:554b"] = "{PLAYER} jogou\nNINTENDO 64.\fMelhor parar, não\nhá tempo a perder!",
  ["59:5582"] = "Parece que isto\nnão é usado há\vmuito tempo.",
  ["59:562b"] = "DAISY: Oi! Meu\nirmão menor é\vLÍDER do GINÁSIO\vda CIDADE\vVERIDIANA.\fPorém, ele\nviaja bastante,\vprejudicando mui-\vtos treinadores.",
  ["59:56b1"] = "DAISY: Oi! Tudo\nbem? \fEstou indo\vtomar um chá.\fGostaria de\njuntar-se a mim?\fOh, seus POKéMONS\nestão meio sujos. \fGostaria que eu\nlimpasse um?",
  ["59:573f"] = "DAISY: Qual deles\ndevo limpar?",
  ["59:5761"] = "DAISY: Certo,\ndeixarei ele limpo\vnum instante.",
  ["59:57f5"] = "DAISY: Eu sempre\ntomo chá nesta\vhora.\fVenha tomar um.",
  ["59:582f"] = "DAISY: Você não\nquer se limpar um\vpouco?\fCerto, tomaremos\num chá.",
  ["59:5872"] = "DAISY: Desculpe,\nmas eu não posso\vlimpar OVOS.",
  ["59:5922"] = "CARVALHO: Ah,\n{PLAYER}!\fFoi bom você ter\nandado todo esse\vcaminho em KANTO.\fO que achou dos\ntreinadores daqui?\fBem fortes, né?",
  ["59:599d"] = "Como vai indo sua\nPOKéDEX?\fVamos ver…",
  ["59:59c3"] = "Se ficar por aqui,\nespero que me\vvisite novamente.",
  ["59:5b9d"] = "CARVALHO: Hum?\nNão está\vcolecionando as\vINSÍGNIAS DE\vKANTO?\fOs LÍDERES DE\nKANTO são tão\vfortes quanto os\vde JOHTO.\fEu acho que você\ndeve desafiá-los.",
  ["59:5c37"] = "CARVALHO: Ah,\nestá colecionando\vas INSÍGNIAS DE\vKANTO.\fDeve ser dureza,\nmas sua\vexperiência lhe\vajudará.\fVenha me ver\nquando pegar todas\velas.\fTerei um presente\npara você.\fTreine bastante,\n{PLAYER}!",
  ["59:5cf6"] = "O programa de\nrádio SHOW DO\vCARVALHO não passa\vem KANTO.\fÉ uma vergonha, eu\nqueria escutá-lo.",
  ["59:5d54"] = "Graças ao seu\ntrabalho na\vPOKéDEX, a\vpesquisa do\vPROFESSOR está\vindo muito bem.",
  ["59:5da2"] = "Não diga a\nninguém,\nmas o\vSHOW DO\vCARVALHO não é\vpassa ao vivo.",
  ["59:5de5"] = "Aperte START para\nabrir o MENU.",
  ["59:5e04"] = "A opção SALVAR\nestá no MENU.\fUse-a periodi-\ncamente.",
  ["59:5e40"] = "Não há nada por\naqui…",
  ["59:5e59"] = "Existe uma\nmensagem de e-mail\vno PC.\fPROFESSOR CARVA-\nLHO, como vai\vsua pesquisa?\fAinda estou\nconfuso.\fOuvi dizer\nque {PLAYER} está\vtentando promover\vseu próprio nome.\fFico feliz em\nsaber disto.\fELM da CIDADE NEW\nBARK :-)",
  ["5a:400f"] = "NIDORAN, trema!",
  ["5a:40cb"] = "BROCK: Uau, não\né normal o desafio\vde um treinador\vde JOHTO.\fSou BROCK, o LÍDER\nDO GINÁSIO DE\vPEWTER.\fSou perito em\nPOKéMONS pedra.\fMeus POKéMONS são\nresistentes a\vmuitos ataques\vfísicos.\fSerá difícil\ncausar algum dano\vneles.\fVamos começar!",
  ["5a:41b6"] = "BROCK: Os\npoderosos ataques\vdos seus POKéMONS\vsuperaram a minha\vdefesa rochosa…\fVocê é mais forte\ndo que esperei.\fVá em frente,\nleve a INSÍGNIA.",
  ["5a:4238"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vPEDRA DO GINÁSIO\vDA CIDADE PEWTER.",
  ["5a:4252"] = "BROCK: {PLAYER},\nObrigado.\fGostei de batalhar\ncom você, embora\vesteja chateado.\fA INSÍGNIA DA\nPEDRA fará seus\vPOKéMONS ficarem\vmais poderosos.",
  ["5a:42d5"] = "BROCK: O mundo é\nenorme.\fExistem outros\ntreinadores fortes\vcomo você.\fSó espere e verá. \fEu vou ficar muito\nmais forte também.",
  ["5a:4469"] = "Ei! CAMPEÃO em\nprogresso! Você\vestá agitando.\fEstá batalhando\ncom os LÍDERES DE\vKANTO?\fEles são fortes\ne dedicados como\vos LÍDERES DOS\vGINÁSIOS DE JOHTO.",
  ["5a:4502"] = "Ei! CAMPEÃO em\nprogresso!\fEste GINÁSIO não\nlhe deu trabalho.\fO modo como\nbatalhou foi muito\vinspirador.\fFalo com\nseriedade.",
  ["5a:45d3"] = "Oi! Veja o meu\nGYARADOS!\fEu evolui ele\nde um MAGIKARP.\fEu não sei como\nele ficou tão\vforte.",
  ["5a:4635"] = "Existia um velho\nmisterioso que\vvendia MAGIKARP.\fEle dizia que as\nMAGIKARPS do\vLAGO DA RAIVA\veram excelentes.",
  ["5a:46fc"] = "…Sim, o\nGINÁSIO em\vCINNABAR fechou.\fEu estou pasma.\fSim?\nEstou no telefone.\vVá embora!",
  ["5a:4770"] = "A maioria dos\nPOKéMONS ficam\vsonolentos se o\vJIGGLYPUFF cantar.\fExistem vários\ngolpes que só são\vusados quando o\vPOKéMON adormece.",
  ["5a:485a"] = "Gosto de dormir\ncom o rádio\vligado…\f…Zzz…",
  ["5a:4a24"] = "Na LIGA POKéMON,\nvocê será testado\vpela ELITE QUATRO.\fVocê deve derrotar\ntodos.\fSe perder,\nvocê terá que\vbatalhar desde o\vcomeço!",
  ["5a:4aa1"] = "Espere.\fVocê receberá o\ndesafio da LIGA\vPOKéMON agora?\fIsso não vai\nacontecer.\fMeus POKéMONS\ntreinados de mane-\vira incrível vão\vderrotá-lo.\f{PLAYER},\neu desafiarei\vvocê!",
  ["5a:4b50"] = "…Droga…\nAinda não posso\vvencer…\fEu devo pensar\nmais nos meus\vPOKéMONS…\fTsc! Tente não\nperder!",
  ["5a:4ba9"] = "\fCerto, Eu perdi…",
  ["5a:4be1"] = "Ah! Está\ndesafiando a ELITE\vQUATRO?\fTem certeza que\nestá pronto?\fSe precisar de\ntreinar mais, meu\vABRA pode\vajudá-lo.\fEle pode\ntransportá-lo para\vcasa.\fQuer ir à sua casa\nagora?",
  ["5a:4c93"] = "Certo. Ilustre sua\ncasa na sua mente…",
  ["5a:4cbd"] = "Bom, te desejo a\nmelhor sorte!",
  ["5a:4ddd"] = "Bem-vindo à LIGA\nPOKéMON, {PLAYER}.\fPermita-me que eu\nme apresente.\vEu sou WILL.\fEu treinei ao\nredor do mundo,\vtornando meus\vPOKéMONS psíquicos\vpoderosos.\fE, por último, eu\nfui aceito como\vmembro da ELITE\vQUATRO.\fEu só consigo\nfazer progressos!\fPerder não é uma\nopção!",
  ["5a:4ed8"] = "Eu… não…\nacredito…",
  ["5a:4ef0"] = "Mesmo sendo\nderrotado, eu não\vmudarei minha\vidéia.\fContinuarei\nbatalhando até\vsuperar todos os\vtreinadores!\fAgora,\n{PLAYER}, mexa-se\ve experimente\va verdadeira\vferocidade da\vELITE QUATRO.",
  ["5a:503f"] = "Hahahahahaha!\fEu sou KOGA da\nELITE QUATRO.\fVivo nas sombras,\nsou um ninja!\fMeu estilo\nintricado vai\vconfundir e\vdestrui-lo!\fConfusão, sono,\nveneno…\fPrepare-se para\nser vítima da\vminha técnica\vsinistra!\fHahahahahaha!\fOs POKéMONS não\nsão apenas força\vbruta, você em\vbreve entenderá!",
  ["5a:5155"] = "Ah! Você provou o\nseu valor!",
  ["5a:5176"] = "Eu submeti você a\ntudo que eu podia.\fMas a minha\ntentativa falhou.\fEu devo afiar\nminhas técnicas.\fVá à próxima sala,\ne teste as suas\vhabilidades!",
  ["5a:52aa"] = "Eu sou BRUNO da\nELITE QUATRO.\fEu sempre treino\nao máximo porque\veu acredito em\vnosso potencial.\fÉ assim que nos\ntornamos fortes.\fVocê pode resistir\nnosso poder?\fHm? Não vejo medo\nem ti.\fVocê parece\ndeterminado.\fPerfeito para\nbatalhar!\fPronto, {PLAYER}?\fVocê se curvará ao\nnosso poder\vopressor!",
  ["5a:53cf"] = "Por quê? Como eu\npude perder?",
  ["5a:53e8"] = "Como eu perdi, eu\nnão tenho o\vdireito de dizer\vnada…\fVá em frente e\nencare o seu\vpróximo desafio!",
  ["5a:54d3"] = "Eu sou KAREN da\nELITE QUATRO.\fVocê é {PLAYER}?\nAdoro batalhar.\fEu uso POKéMONS\nsombrios.\fAcho que suas\nimagens selvagens\vassustam os\vPOKéMONS.\vE eles são fortes.\fJá sabe como\nderrotá-los?\vSó não dê moleza\vpara mim.\fVamos lá.",
  ["5a:55a4"] = "Bem, você é forte.\nGosto disto num\vtreinador.",
  ["5a:55d5"] = "POKéMONS fortes.\nPOKéMONS fracos.\fIsto é só a\npercepção egoísta\vdas pessoas.\fOs treinadores\nverdadeiramente \vbons podem\vtreinar quaisquer\vPOKéMONS.\fGosto do seu\nestilo.\vVocê entende o que\vé importante.\fVá, o nosso\ncampeão o espera.",
  ["5a:5816"] = "LANCE: Eu estava\nlhe esperando.\f{PLAYER}!\nEu sabia que\vcom as suas\vhabilidades você \vconseguiria \vchegar aqui.\fNão precisa falar\nnada agora.\fNós batalharemos\npara ver qual de \vnós dois é o mais\vpoderoso.\fComo o treinador\nmais poderoso, e\vcomo o CAMPEÃO DA\vLIGA POKéMON…\fEu, LANCE o mestre\nde POKéMONS\vdragões, aceito\vseu desafio!",
  ["5a:5953"] = "…Acabou.\nMas estou meio\vestranho.\fNão estou zangado\npela luta, acho\vque estou feliz.\fFeliz já que\nacompanhei a\vformação de um\vnovo CAMPEÃO!",
  ["5a:59e1"] = "…Uau.\nVocê se tornou\vpoderoso,\v{PLAYER}!\fSeus POKéMONS\nlutaram de uma\vforma valente, e\vmostraram serem\vseus amigos.\fComo um teinador,\nvocê continuará a\vcrescer forte com\vseu POKéMON.",
  ["5a:5a8c"] = "MARY: Oh, não!\nJá acabou tudo!\fSe você não fosse\ntão devagar,\vPROFESSOR CARVA-\vLHO…",
  ["5a:5aca"] = "CARVALHO: Ah,\n{PLAYER}!\fFaz tempo que o\nvi.\fVocê está\nmuito mais\vamadurecido.\fSua conquista na\nLIGA foi\vfantástica!\fSua dedicação,\nconfiança e amor\vpor seus POKéMONS \vfez isto\vacontecer.\fSeu POKéMON está\nem excelente\vestado.  \fPorque eles\nacreditaram em\vvocê como um\vtreinador POKéMON.\fMeus Parabéns por\nisto {PLAYER}!",
  ["5a:5bf6"] = "MARY: Vamos\nentrevistar este\vnovo CAMPEÃO!",
  ["5a:5c26"] = "LANCE: Isto está\nse tornando meio\vbarulhento…\f{PLAYER}, você\npode vir comigo?",
  ["5a:5c70"] = "MARY: Oh, pare!\nAinda não o\vintrevistamos!",
  ["5a:5d51"] = "LANCE: Faz muito\ntempo que vim \vaqui pela última\vvez.\fAqui, é onde\nhonramos os\vCAMPEÕES da LIGA\vpela eternidade.\fSeus corajosos\nPOKéMONS também\vterão lugar.\fHoje,\ntestemunhamos a\vsubida de um novo\vCAMPEÃO da LIGA,\vum treinador que\vsente compaixão,\ve confiança pelos\vseus POKéMONS.\fUm treinador que\nteve sucesso pela\vperseverança e\vdeterminação.\fO novo CAMPEÃO\nda LIGA, que\vtem todas as\vqualidades da\vgrandeza!\f{PLAYER},\ndeixe-me registrar\vvocê e seus\vcomanheiros como\vCAMPEÕES!",
  ["5b:41b3"] = "Partiremos logo.\nVá em frente, por\vfavor.",
  ["5b:41de"] = "Desculpe-me. Você\nnão pode embarcar\vagora.",
  ["5b:41fa"] = "Bem-vindo ao NAVIO\nVELOZ S.S.ÁQUA.\fVocê embarcará\nhoje?",
  ["5b:4238"] = "Posso ver sua\nPASSAGEM, senhor?",
  ["5b:4259"] = "Esperamos voltar\na vê-lo!",
  ["5b:4274"] = "{PLAYER} mostrou\nsua PASSAGEM.\fMuito bem.\nObrigado, amigo!",
  ["5b:42a9"] = "{PLAYER} tentou\nmostrar sua\vPASSAGEM…\fMas você não tem!\fDesculpe, você\nsó vai viajar se\vtiver uma\vPASSAGEM.",
  ["5b:4336"] = "Este NAVIO\nsairá na próxima\vSEXTA.",
  ["5b:435c"] = "Capturar SHELLDERS\naqui é fácil.\fEles são raros\nem outro lugar.",
  ["5b:439d"] = "Quantas POKé BOLAS\nvocê tem?\fTodas POKé BOLAS\npegam POKéMONS\vdiferentes.",
  ["5b:43de"] = "O NAVIO usa jatos\npara passar por\vondas!",
  ["5b:440a"] = "Existem muitos\nPOKéMONS em KANTO.\fEu quero ir lá…",
  ["5b:443f"] = "Não queremos que\nvocê caia no mar,\ventão não passe\vdaqui agora.",
  ["5b:466e"] = "Partiremos logo.\fVá em frente,\npor favor.",
  ["5b:4699"] = "Desculpe-me. Você\nnão pode embarcar\vagora.",
  ["5b:46b5"] = "Bem-vindo ao NAVIO\nVELOZ S.S.ÁQUA.\fVocê embarcará\nhoje?",
  ["5b:46f3"] = "Posso ver sua\nPASSAGEM, senhor?",
  ["5b:4714"] = "Esperamos voltar a\nvê-lo!",
  ["5b:472f"] = "{PLAYER} mostrou\nsua PASSAGEM.\fÓtimo. Obrigado,\nsenhor!",
  ["5b:4764"] = "{PLAYER} tentou\nmostrar a\vPASSAGEM…\f…Mas você não tem!\fDesculpe! Você só\nviajará se tiver\vuma PASSAGEM.",
  ["5b:47cb"] = "O NAVIO sairá na\npróxima QUARTA.",
  ["5b:47f2"] = "O NAVIO sairá no\npróximo Domingo.",
  ["5b:4818"] = "Você veio de\nJOHTO?\fEu soube que há\nPOKéMONS raros\vmorando lá.",
  ["5b:49ad"] = "Este NAVIO está\nnos levando à\vCIDADE VERMILION.\fNós avisaremos\nquando chegarmos\vaté lá.",
  ["5b:4a0d"] = "Este NAVIO está\nnos levando à\vCIDADE OLIVINE.\fNós avisaremos\nquando chegarmos\vaté lá.",
  ["5b:4a6b"] = "Aqui é sua cabine.\fSe seu POKéMON\nse machucar, tire\vum cochilo.\fIsto irá curar\ntodos.",
  ["5b:4ac1"] = "Aqui é sua cabine.\fVocê pode curar\nseu POKéMON \vtirando um\vcochilo.\fO NAVIO chegará\nenquanto, você\vestiver dormindo.",
  ["5b:4b32"] = "Todos os\npassageiros são\vtreinadores.\fEles estão\nesperando batalhas\vnas cabines.",
  ["5b:4c00"] = "e!",
  ["5b:4c04"] = "O NAVIO chegou ao\ncais da CIDADE\vOLIVINE.",
  ["5b:4c35"] = "O NAVIO chegou ao\ncais da CIDADE\vVERMILION.",
  ["5b:4f89"] = "Sim, sou um\nmarinheiro, certo?\fNão estva fugindo\ndo trabalho.\fEsta cabine estava\nvazia daí\vcochilei!\fAh, esquece isto!\nVamos lutar!",
  ["5b:500e"] = "Desculpe, sou\no culpado!",
  ["5b:5028"] = "Por eu ser\nmarinheiro uso\vmuita força\vfísica.\fEstava esgotado!",
  ["5b:54af"] = "Uma boa cama!\nVou dormir…",
  ["5b:54cc"] = "Ah, refrescou e me\ncurou!",
  ["5b:54e9"] = "O NAVIO VELOZ\nS.S.ÁQUA chegou na\vCIDADE OLIVINE.",
  ["5b:551a"] = "O NAVIO VELOZ\nS.S.ÁQUA chegou na\vCIDADE VERMILION.",
  ["5b:570e"] = "Bem! Obrigado\npor vir junto.\fDevido aquela\npequena menina eu\vjá estou esgotado.",
  ["5b:5760"] = "Como você gostaria\nque fosse o NAVIO?\fEle praticamente\vpatina nas ondas.",
  ["5b:57aa"] = "Olá, filho…\nEu não encontro\vminha neta.\fSe estiver no\nnavio, tudo bem. \fMas e se ela caiu\nneste mar?\fEla é uma criança\nenérgetica, se ela\vestiver causando\vproblema a alguém?",
  ["5b:585a"] = "{PLAYER}, né?\nOuvi dizer que\vvocê divertiu a\vminha neta.\fQuero lhe dizer\nobrigado por tudo.",
  ["5b:58b2"] = "Eu sei! Eu quero\nque pegue isto!",
  ["5b:58d5"] = "Estamos viajando\npelo mundo.",
  ["5b:58f7"] = "CAPITÃO, vamos\nbrincar, por\vfavor?\fChato!\fEu quero brincar!",
  ["5b:5936"] = "Oi! Você vai\nbrincar comigo?\fOh! Vovô está\npreocupado comigo?\fJá vou indo!\fTenho que achar\no Vovô!",
  ["5b:599b"] = "Vovô aqui estou!\nEu estava\vbrincando com o\vCAPITÃO e com ele!",
  ["5b:59dd"] = "Me perdi quando\nbrincava!",
  ["5b:5d15"] = "O NAVIO VELOZ\nchegou à CIDADE\vVERMILION.",
  ["5b:5f4b"] = "Ei, cara.\nVocê poderia\vprocurar meu amigo?\fEle deve estar\ndormindo, aquele\vpreguiçoso!\fEu queria\nprocurá-lo, mas\vestou trabalhando\vagora.",
  ["5b:5fd7"] = "Oh, não…\fO CAPITÃO ficará\nfurioso…",
  ["5b:5ffe"] = "Obrigado, cara!\nEu fiz ele pensar\vno que fez e então\vele moderou!",
  ["5b:603d"] = "Uma garotinha?\fEu acho que a vi\nindo por aqui.",
  ["5b:606d"] = "A sala de jantar\né lá em cima.\fAs escadas no\nfinal vão à cabine\vdo CAPITÃO.",
  ["5b:667f"] = "O NAVIO VELOZ\nS.S.ÁQUA vai à\vKANTO às Segundas\ve às Sextas.",
  ["5b:66ed"] = "O NAVIO VELOZ\nnavega todas às\vQuartas e Domin-\vgos.",
  ["5b:680b"] = "MONTE LUA.\fNão é pequeno.",
  ["5b:6882"] = "Quando o sol se\npõe, CLEFAIRYS\vsaem para brincar.",
  ["5b:845a"] = "estinguirá\nnossa verdadeira\vLÍDER?",
  ["5b:9100"] = "Antes de conectar\nvocê deve salvar\vo seu jogo.",
  ["5b:9600"] = "99x\v{STRBUF}esculpe-me, a\nCÁPSULA DO TEMPO\vnão está ativada.",
  ["5b:a453"] = "és dele\npara chegar à\vUSINA DE ENERGIA.",
  ["5b:c45c"] = " REPELENTE é\nnecessário se você\vfor explorar uma\vcaverna.\fEmbora eu goste de\nexplorar, eu ainda\vnão fiz isso em\vtodas cavernas.",
  ["5b:ce5b"] = "tão? Eu sei que\nestou com razão.",
  ["5b:d200"] = "ficar com ele.\fMas me prometa\nque será bom com\vele!",
  ["5b:d700"] = "um\nlaço forte com\vseu POKéMON\vtambém!",
  ["5b:e04d"] = "Eu acho que a vi\nindo por aqui.",
  ["5c:400f"] = "Eu esperava\ncomprar lembranças\vda ZONA DO SAFARI,\vmas está fechado…",
  ["5c:4050"] = "A neta do DIRETOR\nDA ZONA DO SAFARI\vmora nessa vila.",
  ["5c:424f"] = "Hahahaha…\fPerdão por\ndesapontá-lo…\fÉ só uma piada!\fEu sou a\nverdadeira!\fJANINE do GINÁSIO\nDE FUCHSIA é eu!",
  ["5c:42bb"] = "JANINE: Você é\nforte.\fVocê venceu\ndefinitivamente.\fAqui está a\nINSÍGNIA DA ALMA.\vLeve-a!",
  ["5c:4305"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vALMA DO GINÁSIO\vDA CIDADE FUCHSIA.",
  ["5c:431c"] = "JANINE: Você é\nmuito forte!\fTenho um presente\nespecial! É o\vTÓXICO, um forte\vveneno que tira\vPS aos poucos da\vvítima.",
  ["5c:438e"] = "JANINE: Eu vou\nrealmente me\vaplicar e melhorar\vminhas técnicas.\fEu quero superar\no meu Pai e você\vtambém!",
  ["5c:4400"] = "Hahaha!\fEu sou JANINE, a\nLÍDER DO GINÁSIO!\fNão sou! Te peguei\notário!",
  ["5c:4440"] = "Eu enganei você…",
  ["5c:4453"] = "Como destinguirá\nnossa verdadeira\vLÍDER?",
  ["5c:4480"] = "Te enganei!\nHahaha!",
  ["5c:4495"] = "Ooh… Eu perdi…\nVocê não é fraco…",
  ["5c:44d5"] = "Eu sou JANINE!\fComo soube quem\neu era de verdade?\fVamos batalhar!",
  ["5c:450b"] = "Droga! Eu queria\nvencer!",
  ["5c:4526"] = "Você deve estar\ncansado.",
  ["5c:4542"] = "Hahaha!\fVocê errou! Eu\nsou JANINE!",
  ["5c:456a"] = "Meu disfarce\nestava bom! Droga!",
  ["5c:458b"] = "Ei, cara.\nMeu disfarce era\vbonito ou o que?",
  ["5c:45ba"] = "Você, CAMPEÃO em\nprogresso! Opa!\vOlhe bem ao seu\vredor.\fTodos treinadores\nse parecem com\va LÍDER, JANINE.\fQual deles é a\nverdadeira JANINE?",
  ["5c:4646"] = "A batalha foi\nótima, treinador\vde JOHTO.",
  ["5c:46e4"] = "Meu avô está na\ncasa do meu irmão\vBILL, na PENÍNSULA\vDE CERULEANA.",
  ["5c:471a"] = "Eu vi estes\nestranhos e lentos\vPOKéMONS na PISTA\vDE CICLISMO.",
  ["5c:47b5"] = "Ei! Você tem um\nnovo tipo de\vPOKéDEX.\fFoi o PROFESSOR\nCARVALHO que te\vdeu?",
  ["5c:47fd"] = "Eu fiquei\nbem chocada no\vGINÁSIO.\fTodas as garotas\ntinham aparência\vidêntica.",
  ["5c:484f"] = "Eu sou JANINE!\nOpa! Errei… \vPuf!",
  ["5c:486f"] = "Viu? Me pareço com\nela agora!",
  ["5c:4907"] = "Meu avô está na\nDIRETORIA da ZONA\vDO SAFARI.\fPelo menos estava…\fEle decidiu tirar\nférias e conhecer\vnovos lugares\vsozinho.\fEle parou de\ncomandar a ZONA\vDO SAFARI devido\va isso.",
  ["5c:49b2"] = "Várias pessoas\nficaram desaponta-\vdas porque a ZONA\vDO SAFARI fechou,\vmas meu avô é tão\vteimoso…",
  ["5c:4a0b"] = "É uma foto de um\nidoso sorridente\vcercado por\vPOKéMONS.",
  ["5c:4a47"] = "É uma foto de uma\ngrande área\vgramosa com\vPOKéMONS raros\vbrincando nela.",
  ["5c:4ac2"] = "Você está\ntrabalhando com a\vPOKéDEX.\fQue legal! Não\ndesista!",
  ["5c:4b31"] = "Os treinadores que\nprocuram poder\vescalam o MONTE\vPRATEADO ignorando\vtodos os perigos\vexistentes lá…\fCom seus POKéMONS\nde confiança, eles\vdevem sentir que\vpodem ir a qual-\vquer lugar.",
  ["5c:4c13"] = "Oh, querido.\nVocê me achou.\fNão conte a ninguém sobre mim.\fEu lhe darei\nisso por guardar\vsegredo.\fTudo bem?",
  ["5c:4c81"] = "É duro ser uma\nmuito famosa.\n     \fSeja onde eu for,\nas pessoas me\vperseguem.\fEu só quero ficar\nsozinha!",
  ["5c:4fa4"] = "Bem-vindo ao\nCOLISEU CLUBE\vCABO.  \fVocê pode\nbatalhar aqui!\fVocê quer fazer\numa batalha?",
  ["5c:4ffe"] = "Bem-vindo ao\nCENTRO DE TROCAS\vDO CLUBE CABO.\fAqui você troca\nPOKéMONS com um\vamigo seu!\fVocê gostaria\nde trocar?",
  ["5c:5068"] = "Bem-vindo à\nCAPSULA DO TEMPO\vDO CLUBE CABO.\fVocê pode viajar\npara o passado e\vtrocar POKéMONS.\fDeseja trocar\natravés do tempo?",
  ["5c:50e2"] = "Seu amigo não\nestá aqui.",
  ["5c:50fd"] = "Antes de conectar\nvocê deve salvar\vo seu jogo.",
  ["5c:5130"] = "Aguarde!",
  ["5c:513e"] = "A conexão foi\nfechada devido à\vinatividade.\fPor favor, chame\nseu amigo e venha\vnovamente.",
  ["5c:51f2"] = "Não pode conectar\nao passado aqui.",
  ["5c:5213"] = "Seu amigo escolheu\noutra sala.",
  ["5c:5238"] = "Entre por favor.",
  ["5c:5258"] = "Perdão-{STRBUF}\nnão pode ir.",
  ["5c:5275"] = "Não pode levar o\n{STRBUF} com   \v{STRBUF}.",
  ["5c:529c"] = "Não pode levar o\n{STRBUF} que tem\vCARTA com você.",
  ["5c:52cd"] = "Desculpe-me, a\nCÁPSULA DO TEMPO\vnão está ativada.",
  ["5c:52fc"] = "Desculpe-me, a\nMÁQUINA DE TROCAS\vnão está ativada.",
  ["5c:532c"] = "Desculpe-me,\na MÁQUINA DE\vBATALHAS não está\vativada.",
  ["5c:535d"] = "Olá! Você é\n{PLAYER}, certo? \fEu tenho algo para\nvocê.",
  ["5c:5391"] = "Aqui está!",
  ["5c:539f"] = "Esperamos servi-lo\nde novo.",
  ["5c:53bc"] = "Oh, você não tem\nlugar para isso.\fPare em qualquer\nCENTRO POKéMON\vpelo mundo e\vpegue-o.",
  ["5c:541a"] = "Não? Isso é muito\nestranho…",
  ["5c:553d"] = "Seu amigo está\npronto.",
  ["5c:55be"] = "Seu amigo está\npronto.",
  ["5d:401f"] = "Ao norte de\nLAVANDA fica o\vTUNEL DE PEDRA.\fVá através dele\npara chegar à\vUSINA DE ENERGIA.",
  ["5d:4072"] = "Há um programa de\nrádio que toca a\vmúsica da POKé\vFLAUTA.\fMas seu rádio\nprecisa do CARTÃO\vEXPANSOR para\vsintonizar nesta\vestação!",
  ["5d:40db"] = "A ESTAÇÃO DE RÁDIO\nnão pode operar\nporque não tem\venergia.",
  ["5d:411e"] = "O DIRETOR da\nESTAÇÃO DE RÁDIO\vcom certeza está\vfeliz.\fEle disse que a\nrádio voltou a\vfuncionar porque\va USINA DE ENERGIA\vestá funcionando\vnormalmente de\vnovo.",
  ["5d:4222"] = "O SENHOR FUJI\nmora aqui, mas não\vestá em casa\vagora.\fEle deve estar na\nCASA DA ALMA.",
  ["5d:4271"] = "Suitas pessoas de\ncoração frio páram\vde cuidar de seus\vPOKéMONS.\fMeu avô traz\nestes POKéMONS\vabandonados para\vcasa e cuida deles\vde maneira\vadequada.",
  ["5d:437e"] = "LAVANDA é uma\ncidade pequena e\vcalma que fica\vnas bases das\vmontanhas.\fEla está um pouco\nmais agitada\vdesde quando a\vTORRE DE RÁDIO foi\vconstruída.",
  ["5d:445a"] = "O REPELENTE é\nnecessário se você\vfor explorar uma\vcaverna.\fEmbora eu goste de\nexplorar, eu ainda\vnão fiz isso em\vtodas cavernas.",
  ["5d:44dd"] = "Eu ouvi falar de\num artesão que\vfaz POKé BOLAS sob\vencomenda na\vCIDADE AZALEA em\vJOHTO.\fQueria ter uma.",
  ["5d:4586"] = "SENHOR FUJI: Bem\nvindo.\fHmm… Vejo que\nvocê treina\vseus POKéMONS\vde maneira \vgentil e amorosa.\fOs amantes de\nPOKéMONS vêm aqui\vpara pagar devotos\vaos POKéMONS\vfalecidos.\fSeja simpático\ncom as almas\vdos POKéMONS\vfalecidos.\fTenho certeza que\nisso vai deixá-los\vfelizes.",
  ["5d:4680"] = "Há outras covas de\nPOKéMONS aqui, eu\vacho.\fHá varios\ncompartimentos que\vapenas o SENHOR\vFUJI pode entrar.",
  ["5d:46e4"] = "Eu vim com minha\nmãe para visitar\vas covas dos\vPOKéMONS…",
  ["5d:470e"] = "Os POKéMONS que\nviveram comigo…\fEu os amei como os\nmeus netos…",
  ["5d:47f2"] = "Bem-vindo!\nSinta a vontade\vpara olhar tudo\vnesse andar.",
  ["5d:482d"] = "Desculpe-me, você\nsó pode visitar o\vandar térreo.\fDesde quando a\nTORRE DE RÁDIO DE\vJOHTO foi envadida\vpor uma gangue\vcriminosa, nós\vtemos tomado\vmedidas de\vsegurança.",
  ["5d:48c3"] = "Muitas pessoas\ntrabalham duro\vaqui na TORRE DE\vRÁDIO. \fEles dão o\nmelhor de si para\vtransmitirem\vprogramas de\vqualidade.",
  ["5d:492e"] = "Oh, não, não, não!\fNós saimos do ar\ndesde quando a\vUSINA DE ENERGIA\vfoi desligada.\fTodos os meus\nesforços para\vconstruir esta\vestação poderiam\vter sidos em vão\vse eu não fazer\vtransmissões.\fEu vou ser\narruindado!",
  ["5d:49d4"] = "Ah! Então você é\n{PLAYER}, a pessoa\vque resolveu o\vproblema na USINA\vDE ENERGIA?\fGraças a você, eu\nnão perdi o meu\vemprego.\fEu admito, você é\num verdadeiro\vsalva-vidas!\fLeve isso\ncomo forma de\vagradecimento.",
  ["5d:4a74"] = "Com essa coisa,\nvocê pode\vsintonizar em\vprogramas que vem\vde KANTO.\fHahahaha!",
  ["5d:4ac6"] = "Como vai, colega!\fEu sou o\nsuper DIRETOR DE\vM→SICAS!\fHã? Sua POKéGEAR\nnão pode\vsintonizar em\vminhas músicas?\vQue tristeza!   \fSe você adquirir\na atualização do\vCARTÃO EXPANSOR,\vvocê poderá\vsintonizar em\vnossa programação.\fÉ melhor você\nadquirir um!",
  ["5d:4b83"] = "Olá colega!\fEu sou o super\nDIRETOR DE M→SICA!\fEu sou responsável\npelas belas\vmelodias que vão\vao ar.\fNão seja quadrado.\nLargue as músicas\vque ficam fora do\var!",
  ["5d:4c26"] = "1º ANDAR-RECEPÇÃO\n2º-LOJAS\v3º-FUNCIONÁRIOS\v4º-PRODUÇÃO\v5º-ESCRITÓRIO DO\vDIRETOR.",
  ["5d:4c70"] = "Desperte POKéMONS\ncom o som alegre\vda POKé FLAUTA no\vCANAL 20.",
  ["5d:4d5c"] = "Você já foi à\nCIDADE LAVANDA?\fHá uma grande\nTORRE DE RÁDIO lá.",
  ["5d:4df2"] = "Eu sou o irmão\nmais novo do\vPESCADOR LÍDER.\fVejo que você\ngosta de pescar.\fEu não tenho\ndúvidas disso!\fEntão? Eu sei que\nestou com razão.",
  ["5d:4e72"] = "Sim, sim. Como\neu imaginei.\fEi, fã da pesca!\fLeve esta, SUPER\nVARA!",
  ["5d:4ebf"] = "Tente pescar em\nqualquer lugar\vque tenha água.\fLembre-se, você\npode capturar\vdiferentes\vPOKéMONS usando\vdiferentes VARAS.",
  ["5d:4f2f"] = "Hã? Meus próprios\nolhos estão me\venganando?",
  ["5d:4ff8"] = "Estou chocado!\nUm menino da sua\vidade, com cabelo\vgrande entrou\vaqui em casa.\fEle me assustou e\ntentou fazer eu\vdar o meu POKéMON.\fEu fugi, mas\ne se ele voltar\vpara tentar\vpegá-lo?\fVocê é forte.\nVocê pode cuidar\vdo meu POKéMON\vpor enquanto?",
  ["5d:50e2"] = "Oh, obrigado!\nCuide bem dele,\vpor favor!",
  ["5d:5110"] = "{PLAYER}\nrecebeu o \vPOKéMON.",
  ["5d:5124"] = "A sua equipe está\ncheia.",
  ["5d:513e"] = "Oh, não…\nO que vou fazer\vagora?",
  ["5d:5165"] = "Oi! Como vai meu\nPOKéMON?\fAcho que ele está\nseguro agora,\ventão eu poderia\vtê-lo de volta?",
  ["5d:51a6"] = "Obrigado!",
  ["5d:51b2"] = "Ei, você não está\ncom o meu POKéMON.",
  ["5d:51d8"] = "Meu POKéMON gostou\nde você.\fCerto, você deve\nficar com ele.\fMas me prometa\nque será bom com\vele!",
  ["5d:5234"] = "Oh, não… É o\nmesmo de ter sido\vroubado.",
  ["5d:5261"] = "Para o POKéMON,\nfelicidade é estar\vcom a pessoa que\vo trata bem.",
  ["5d:53ee"] = "HAHAHAH!\fEntão veio de\nlonge.\fDeixe-me avisar,\nsou forte!\fMeu POKéMON\nesmagará pedras\ve quebrará seus\vossos!\fVeja só\nisto!",
  ["5d:547f"] = "Já se assustou\nseu pivete?\fO quê?\nNão tem nada a ver\vcom POKéMONS?\fÉ verdade!\fVamos.\nNós devemos\vbatalhar!",
  ["5d:54eb"] = "O quê? Hã?\nperdi?\fBom, você ganhou\na INSÍGNIA da\vTEMPESTADE!",
  ["5d:552a"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vTEMPESTADE do\vGINÁSIO da CIDADE\vCIANWOOD.",
  ["5d:5542"] = "A INSÍGNIA DA\nTEMPESTADE faz\vPOKéMONS até o\vNÍVEL 70 lhe\vobedecerem!\fE também permite\nseu POKéMON usar a\vtécnica VOAR fora\vde batalhas\vPOKéMON.\fEi, leve isso\naqui.",
  ["5d:55cf"] = "Isto é SOCO\nDINÂMICO.\fNão atinge sempre,\nmas quando\vatinge causa uma\vconfusão!",
  ["5d:5625"] = "HAHAHAH! Eu\napreciei nossa\vluta!\fMas a perda foi\nruim!\fA partir de agora,\ntreinarei 24 horas\vpor dia.",
  ["5d:58dd"] = "Você encontrou o\nPOKéMANÍACO?\fEle vive falando\nsobre seus\vPOKéMONS raros.",
  ["5d:5923"] = "Os treinadores\nPOKéMONS do\vGINÁSIO, são\vmachistas.\fSe eu for lá, eles\npodem querer bater\vem mim.\fAqui vai um\nconselho: O LÍDER\vDO GINÁSIO usa\vPOKéMONS do tipo\vlutador.\fEntão confunda-o\nusando POKéMONS\vPSÍQUICOS.\fElimine os\nPOKéMONS dele\vantes que ele\velimine os seus\vmelhores POKéMONS.",
  ["5d:5a2a"] = "{PLAYER}! Você\nvenceu!\fEstava torcendo\npor você!",
  ["5d:5ac9"] = "Seu POKéMON\nparece estar bem.\fMas tem algo\npreocupando você?\fO POKéMON do\nFAROL está com\vproblemas?\fPegue isto, ele\ndeve dar um jeito\vno POKéMON.",
  ["5d:5b52"] = "{PLAYER} recebeu\nPOÇÃO SECRETA.",
  ["5d:5b6c"] = "Minha POÇÃO\nSECRETA é muito\vforte.\fEu só ofereço em\ncasos de urgência.",
  ["5d:5bf5"] = "Você tem um\nPOKéMON magnífico\vcom você. \fQue tal uma foto\nde lembrança?",
  ["5d:5c3e"] = "Certo! Dê um\ngrande sorriso\vagora!",
  ["5d:5c52"] = "Oh, isto é muito\nruim. Eu achei\vque ia dar tudo\vcerto!…",
  ["5d:5cb8"] = "Você veio de\nOLIVINE?\fSe lembra das\nquatro ilhas ao\vlongo do caminho?\fEu ouvi dizer que\numa criatura\vmística vive\vnestas ilhas.",
  ["5d:5d3b"] = "Eu soube que você\nsó poderá vê-lo\vse tiver a ASA\vPRATEADA.\fEla e essa\ncriatura devem ter\vo mesmo cheiro.",
  ["5d:5da5"] = "Os redemoinhos em\ntorno da ilha são\vcausados por uma\vcriatura do mar.",
  ["5d:9100"] = "r lá fora.\fVolte após o\npôr-do-sol, tá?",
  ["5d:a500"] = "ra.",
  ["5d:cd00"] = "RIDIANA.\fA política do\nLÍDER é ganhar sem\va ajuda de nenhum\vsubalterno.",
  ["5e:4011"] = "Olá! Bem Vindo a\nbela LOJA de\vCELADON!\fO diretório está\nna parede.",
  ["5e:4057"] = "Esta loja faz\nparte do mesmo\vDEPARTAMENTO lá da\vCIDADE GOLDENROD.\n    \fElas são ambos\nrenovados ao mesmo\vtempo.",
  ["5e:40cb"] = "É minha primeira\nvez aqui.\fÉ tão grande.\nTenho medo de\vsubir.",
  ["5e:410c"] = "1º ANDAR-RECEPÇÃO\f2º-LOJA DO\nTREINADOR\f3º-LOJA DE TM\f4º-PRESENTES\f5º-FARMÁCIA\f6º-MÁQUINA DE\nVENDAS.",
  ["5e:41ed"] = "Me tornei\ntreinador\vrecentemente.  \fFoi meu filho quem\nme ajudou.\fEstou admirado\ncom esta seleção\vde produtos.",
  ["5e:4262"] = "Meu pai está tendo\ntrabalho para\vdecorar o nome dos\vitems e como\veles devem ser\vusados…",
  ["5e:42c0"] = "Ótimos itens para\ntreinadores.\f2º ANDAR-LOJA DO\nTREINADOR.",
  ["5e:4377"] = "Não consigo\nme decidir em qual\vPOKéMON devo pôr\veste TM…",
  ["5e:43aa"] = "Opa!\nEu negociei o meu\vPOKéMON sem\vretirar a minha\vATUALIZAÇÃO dele.",
  ["5e:43eb"] = "Isso! Finalmente\nconsegui um\vPORYGON.\fEu sou ruim nas\nmáquinas, nunca\vconseguiria muitas\vmoedas…\f…Hã?\fO PORYGON trocado\nevoluiu em um \vPOKéMON diferente.",
  ["5e:4485"] = "A LOJA de TM\nvende golpes\vraros.",
  ["5e:44a9"] = "3º ANDAR-LOJA\nDE TM.\fFortaleça seu\nPOKéMON!",
  ["5e:4545"] = "Vim comprar a\nCARTA SURFE para\va minha namorada.",
  ["5e:4579"] = "Este é o único\nlugar onde você\vencontra a CARTA\vAMOR.",
  ["5e:45b0"] = "Se expresse com\nPRESENTES.\f4º ANDAR-\nPRESENTES.",
  ["5e:4647"] = "Quero comprar\nartigos que elevam\vo estado do\vPOKéMON, mas não\vtenho tanto\vdinheiro…",
  ["5e:4696"] = "Quero PP MAIS,\npara elevar o PP\vdos golpes.\fMas não posso\ncomprar.",
  ["5e:46da"] = "Os POKéMONS ficam\nfelizes se você\vusar itens neles.\fEles odeiam alguns\nitens.",
  ["5e:4724"] = "5º ANDAR-FARMÁCIA.",
  ["5e:486c"] = "Uma máquina de\nvenda.\fOlha o menu.",
  ["5e:4890"] = "Click!\f{STRBUF}\nsaiu.",
  ["5e:48aa"] = "Opa, dinheiro\ninsuficiente.",
  ["5e:48c3"] = "Não tem mais\nespaço para\visto…",
  ["5e:48e3"] = "Uma máquina de\nvendas com uma\vroleta de prêmios.\fNunca verei uma\nigual.",
  ["5e:492c"] = "Ahh! Não há jogos\naqui!\fEu queria jogar…",
  ["5e:495a"] = "6º ANDAR-PRAÇA DO\nTELHADO.\fMÁQUINAS DE VENDA.",
  ["5e:4a32"] = "Os meus POKéMONS\nme fazem companhia\vpor isto não fico\vsó.\fO MEOWTH até me\ntraz dinheiro.",
  ["5e:4ac7"] = "A SUÍTE DO GERENTE\nDA MANSÃO CELADON.",
  ["5e:4b55"] = "PC de {PLAYER}\nfoi ligado.\f…\fAlguém estava\ntentando passar um\vnovo e-mail.\fEspero que venha\nme visitar em\vKANTO.\fAcho que você\nficará surpreso,\vcom as mudanças\vque ocorreram\vaqui.\fVocê verá alguns\nPOKéMONS que não\vexistem em JOHTO.\fPara o PRODUTOR\f…",
  ["5e:4c48"] = "GAME FREAK\nSALA DE ENCONTROS.",
  ["5e:4cea"] = "Está certo!\nEu sou o\vDESENHISTA do\vJOGO!\fCompletar sua\nPOKéDEX é duro,\vmas não desista!",
  ["5e:4d41"] = "Uau! Excelente!\nVocê completou sua\vPOKéDEX!\fMeus Parábens!",
  ["5e:4d7f"] = "O ARTISTA GRÁFICO\nvai imprimir um\vDIPLOMA para você.\fVocê deve lhe\nmostrar isto.",
  ["5e:4dd0"] = "Sou o ARTISTA\nGRÁFICO.\fEu fiz  ocê!",
  ["5e:4df4"] = "Sou o ARTISTA\nGRÁFICO.\fOh, você completou\nsua POKéDEX?\fQuer que eu\nimprima o seu\vDIPLOMA?",
  ["5e:4e4c"] = "Dê-me um grito se\nquiser a impressão\vdo DIPLOMA.",
  ["5e:4eb1"] = "Quem sou?\nSou o PROGRAMADOR.\fVá jogar nas\nmáquinas!",
  ["5e:4ee6"] = "As GÊMEAS não são\nlegais?\fJASMINE também é!\nOh, Eu os\vadoro!",
  ["5e:4f27"] = "GAME FREAK\nSALA DE PRODUÇÃO.",
  ["5e:4f44"] = "É um desenho\ndetalhado de uma\vmenina.",
  ["5e:4f6e"] = "É o programa do\njogo.\fSe usar errado,\npode causar erros\vno jogo!",
  ["5e:4fb2"] = "Existem materiais\nsobre eles.    \fExiste até uns\nBONECOS POKéMON.",
  ["5e:50ad"] = "Deixe-me contar\nalgo assustador…",
  ["5e:50d0"] = "Não será\ntão assustador\venquanto haver luz\vsolar lá fora.\fVolte após o\npôr-do-sol, tá?",
  ["5e:5129"] = "Era uma vez, um\ngaroto que ainda\vpequeno recebeu\vuma BICICLETA\vNOVA…\fEle tentou andar\nnela na mesma\vhora…\fEle se divertia\ntanto que nem viu\vo sol se pôr…   \fEnquanto voltava\nà sua casa no\vmeio da noite, a\vBICICLETA diminuia\vde velocidade.\fOs pedais ficaram\nduros!\fQuando ele parou\nde pedalar, a\vBICICLETA foi\vpuxada para trás.\fEra como\nse estivesse\vamaldiçoada e\vtentasse levá-lo\va algum lugar!\f…\n…KABUMMM!\fO menino havia\nvoltado para a\vPISTA DE CICLISMO!\f…Ba-dum ba-dum!\fPor ter ouvido\na minha história,\vleve este TM03.",
  ["5e:5339"] = "O TM03 é a\nMALDIÇÃO.\fÉ um golpe que\napavora a vítima\ve a faz perder PS\vlentamente.",
  ["5e:53b4"] = "ERIKA é a mestra\nde POKéMONS grama.\fEla lhe fará pagar\nse não agir\voriginalmente!",
  ["5e:5405"] = "A EQUIPE ROCKET\nestá escondida no\vporão da CASA DE JOGOS.\fOh, espere. Isto\nocorreu há três\vanos",
  ["5e:5571"] = "Bem-vindo!\fVocê pode trocar\nmoedas por prêmios\vna casa ali ao\vlado.",
  ["5e:55b6"] = "Estas máquinas são\ngrandes obras de\vartes.",
  ["5e:55e3"] = "Eu quero esta\nmáquina.\fMe limpou\ntotalmente ontem,\ventão devia me\vpagar hoje.",
  ["5e:5636"] = "Acho que esta\nmáquina ainda me\vpagará…\fAs chances variam\nentre elas.",
  ["5e:567d"] = "Hahahaha!\fAs moedas\ncontinuam caindo!\fHum?\nO que menino?\vVocê quer jogar?\fVou compartilhar\nminha sorte!",
  ["5e:56e6"] = "Hahahaha!\fMe sinto bem\nquando eu ajudo\vos meus vários\vcolegas!",
  ["5e:572b"] = "Ei, você não tem\numa BOLSA de\vMOEDAS!\fComo eu poderei\nlhe dar umas\vmoedas?",
  ["5e:577a"] = "Ei, sua BOLSA\nde MOEDAS, está\vcheia.\fVocê deve estar\ntramando algo,\vnão é?",
  ["5e:57c6"] = "Ei! Ganhar\nfaz bem!\fVocê está jogando\naqui também?\fEstou tentando\nconseguir moedas\vpara ganhar\vprêmios.\fMas não tenho\nmuitas moedas…",
  ["5e:584e"] = "Hum… Eu tenho\nmais chances de\vter um PIKACHU\vdo que…\fO que eu\vfaço?",
  ["5e:5894"] = "Ei! Embaixo deste\npôster…\fNão existe\nnada!",
  ["5e:58c2"] = "Ei! Embaixo deste\nposter…\fNão existe\nnada!",
  ["5e:58f0"] = "Existe algo por\naqui.",
  ["5e:5908"] = "Um refrigerante.\fAlguém deve ter\nesquecido…\fHã? Está\nvazio!",
  ["5e:5c59"] = "Eu queria um\nMR.MIME, mas só\vtinha 100 moedas…",
  ["5e:5c8a"] = "Bem…\nPreciso ficar\vcalmo e alegre…\fNão posso perder\na calma senão\vperderei dinheiro…",
  ["5e:5cdf"] = "Bem-vindo!\nTrocamos suas\vmoedas por grandes\vprêmios!",
  ["5e:5d15"] = "Qual você gostaria\nde ter?",
  ["5e:5d32"] = "Certo, você quer o\n{STRBUF}?",
  ["5e:5d4e"] = "Aqui está!",
  ["5e:5d5c"] = "Você não tem mais\nmoedas.",
  ["5e:5d79"] = "Você não tem\nespaço.",
  ["5e:5d93"] = "Oh. Por favor,\nvolte com moedas!",
  ["5e:5db5"] = "Oh? Você não tem\nCOFRE.      .",
  ["5e:5ec9"] = "ERIKA: Olá…\nO tempo está\vótimo, né?\fÉ tão relaxante…\n…Tenho medo de\vcair no sono…\fMeu nome é\nERIKA.\fSou a LÍDER\ndo GINÁSIO de\vCELADON.\fHã? Você veio lá\ndo continente\vJOHTO.\fQue bom…\fOh. Desculpe,\nnão percebi que\vvocê veio aqui\vpara me desafiar.\fMuito bem, mas\nnão devo perder.",
  ["5e:5fdf"] = "ERIKA: Oh!\nAdmito a derrota…\fVocê é realmente\nforte…\fVou lhe dar\na INSÍGNIA DO ARCO\vÍRIS…",
  ["5e:6037"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DO\vARCO-ÍRIS DO\vGINÁSIO DA CIDADE\vCELADON.",
  ["5e:6051"] = "ERIKA: Foi uma\npartida deliciosa.\fMe senti\ninspirada.\fPor favor, fique\ncom este meu TM.\fÉ o GIGA DRENO.\fÉ um golpe\nmaravilhoso, que\vdrena metade do\vdano infligido no\vPOKéMON inimigo.\fPor favor, use\neste TM se você\vprecisar.",
  ["5e:6100"] = "migo.\fPor favor, use\neste TM se você\vprecisar.",
  ["5e:6130"] = "ERIKA: Perder\ndeixa um gosto\vruim…\fMas saber\nque existem\vtreinadores\vfortes, me dá\vinspiração para\vtreinar.",
  ["5e:64ba"] = "Oi!\fNós estamos\nrealizando uma\vcompetição.\fNão podemos lhe\nservir agora.",
  ["5e:6505"] = "Nhac…\nGlup…",
  ["5e:6516"] = "Não fale\ncomigo!\fVocê quebrou a\nconcentração!",
  ["5e:6546"] = "Glup…\nGlup…",
  ["5e:6554"] = "Quero quantidade\nacima de\vqualidade.\fEstou\ninchado!",
  ["5e:658a"] = "Nhac…\nNhac…",
  ["5e:6599"] = "A comida é boa\naqui, mas\vGOLDENROD tem a \vmelhor comida do\vmundo.",
  ["5e:65dd"] = "Nhac…\nNhac…",
  ["5e:65ee"] = "Ninguém lhe dará\numa BOLSA de\vMOEDA.\fVá procurar lá\nem JOHTO.",
  ["5e:6630"] = "Nhac…\nNhac…   \fAinda posso\ncomer!",
  ["5e:6654"] = "Manda mais!",
  ["5e:6661"] = "Nesta Competição\nnão tem tempo!\fUma batalha sem\nfim!\fO chefe da cozinha\npega tudo em\várvores",
  ["5e:66c3"] = "{PLAYER} achou o\n{STRBUF}.",
  ["5e:66d5"] = "Mas {PLAYER} não\npode ter mais\vitem…",
  ["5e:6757"] = "Se você cruzar a\nESTRADA de\vCICLISMO, você irá\và CIDADE FUCHSIA.",
  ["5e:67e6"] = "A PISTA DE CICLISMO\ncomeça aqui.  \fÉ tudo em declive.\nEntão é bem\vanimado.\fÉ um ótimo\ndivertimento que\vnão se sente nem\vem navio nem em\vtrêm.",
  ["5e:6874"] = "Ei! Você! Pare!\fNão pode entrar\nna ESTRADA DE\vCICLISMO sem\vBICICLETA.",
  ["5e:690a"] = "Você já soube do\nacidente na USINA\vDE ENERGIA?\fEle fica à Leste,\nperto da CIDADE\vLAVANDA.",
  ["5e:6970"] = "Eu levo meu\ntrabalho de GUARDA\va sério.\fEi! Você tem uma\nPOKéDEX.\fCerto. Você pode\npassar.",
  ["5e:6a0a"] = "ESTRADA DE\nCICLISMO.\fSiga reto.",
  ["5e:6a2b"] = "Agarre-se! Você\nnão tem BICICLETA?\fA ESTRADA DE\nCICLISMO.\fÉ aqui fora.\fVocê tem que ter\vuma BICICLETA.",
  ["5e:8b63"] = "a…",
  ["5e:ce62"] = "\fDizem que POKéMONS\nroubados por\vpessoas más,\vacabam ficando\vmaus também.",
  ["5f:4057"] = "GARY: Finalmente\nchegou aqui.\fNão estava com\nânino em CINNABAR,\vmas agora eu quero\vbatalhar.     \f…\fVocê está me\ndizendo que\vconseguiu todas\vINSÍGNIAS de\vJOHTO?\fOs GINÁSIOS de\nJOHTO devem ser\vruins.  \fNão se preocupe\ncom isto.\fEu saberei se você\né bom ou não se\vlutarmos agora.\fPronto, menino de\nJOHTO?",
  ["5f:4188"] = "GARY: O quê?\fComo? Droga!\nPerdi para você?\f…\fHum, está bem…\fEi, leve isto,\né a INSÍGNIA DA\vTERRA.",
  ["5f:41e9"] = "{PLAYER} foi\npresenteado com\numa INSÍGNIA\vDA TERRA DO\vGINÁSIO DA CIDADE\vVERIDIANA.",
  ["5f:4201"] = "GARY: Certo, eu\nestava errado.\vVocê é sincero.\fVocê é um ótimo\ntreinador.\fMas um dia eu\nderrotarei você. \fNão se esqueça\ndisto!",
  ["5f:4285"] = "GARY: Escute.\fÉ melhor não\nperder até que eu\vlhe vença.\fEntendeu?",
  ["5f:42c8"] = "Olá, CAMPEÃO em\nprogresso!\fComo vai? Parece\nque você está\venrolado.\fO LÍDER DO GINÁSIO\né um garoto\vque lutou com o\vCAMPEÃO há três\vanos.\fEle não é ruim.\fDê tudo o que\nvocê tiver!",
  ["5f:437a"] = "Cara, você é mesmo\ndurão…\fEssa foi uma\nbatalha inspira-\vdora.\fEla trouxe\nlágrimas aos meus\volhos.",
  ["5f:442e"] = "Você pensa muito\nantes de nomear\vos seus POKéMONS?\fDando a eles bons\napelidos, aumenta\va diversão de\vtodos os outros.",
  ["5f:44a5"] = "O nome SPEARY é\ndo SPEAROW, e o\vRATTEY do RATTATA.",
  ["5f:4559"] = "Bem-vindo à\nCASA DE TREINO,\vo mais novo centro\vde atividades de\vVERIDIANA.\fEstamos abertos\na treinadores.\fVocê pode lutar\ncom o melhor dos\vmelhores no andar\vabaixo.",
  ["5f:45ff"] = "VERIDIANA é a\ncidade mais\vpróxima do\vPLANALTO ÍNDIGO.\fConstruíram este\nlocal porque\vmuitos treinadores\vvêm aqui para\vir ao PLANALTO\vÍNDIGO.",
  ["5f:468f"] = "Eles realizam\nbatalhas no andar\vde baixo.\fEu adoraria ver o\nquanto é bom um\vtreinador lá de\vJOHTO.",
  ["5f:46f7"] = "Acho que você não\nse torna um\vCAMPEÃO a menos\vque vá a todos os\vlugares e enfrente\vtodos os tipos de\vpessoas.\fO CAMPEÃO de\nPALLET viajou por\vtodas as cidades\vde KANTO.",
  ["5f:47a3"] = "Bem…\nEstou tirando um\vdescanso de\vbatalhas.",
  ["5f:47ce"] = "As batalhas são\nrealizadas no\vSAGUÃO de\vTREINAMENTO\vabaixo.\fTreinadores hábeis\nsão chamados para\vlutar.",
  ["5f:4837"] = "Lá não existe\nregras ou\vregulamentos para\vbatalhas.\fÉ como nas\nbatalhas de campo,\vvale quase tudo!",
  ["5f:489b"] = "…O que é isto?\nUma estratégia?\fEsta escrita\nparece com um\vONIX…\fÉ completamente\nilegível…",
  ["5f:49fa"] = "Oi. Bem-vindo ao\nSAGUÃO DE\vTREINAMENTO.\fSó pode batalhar\num vez ao dia.",
  ["5f:4a44"] = "{STRBUF} será o\nseu oponente.",
  ["5f:4a61"] = "Você quer batalhar\nagora?",
  ["5f:4a7c"] = "Por favor, vá à\ndireita.\fVocê já\npode começar.",
  ["5f:4ab0"] = "Desculpe.\nSó trenadores que\vbatalharão hoje\vpodem entrar neste\vlocal.",
  ["5f:4af7"] = "Desculpe, senhor.\fSeria sua segunda\nvez hoje.\fSó é permitido\nvocê neste local\vuma vez por dia.",
  ["5f:4b57"] = "Perdi…\nDroga…",
  ["5f:4b66"] = "Vim de fora\npara aqui.\fSó assim poderia\nlutar.",
  ["5f:4bd3"] = "O LÍDER DO GINÁSIO\ndaqui é bem legal.",
  ["5f:4bf9"] = "Você tem ido a\nCINNABAR?\fÉ uma ilha que\nfica ao sul daqui.",
  ["5f:4c8c"] = "Em que parte do\nmundo esta o LÍDER\vDO GINÁSIO?\fEu quero\ndesafiá-lo.",
  ["5f:4cd4"] = "Não existe nenhum\nTREINADOR no\vGINÁSIO de\vVERIDIANA.\fA política do\nLÍDER é ganhar sem\va ajuda de nenhum\vsubalterno.",
  ["5f:4d4a"] = "Ouvi dizer que o\nGINÁSIO de\vCINNABAR acabou.\fO que aconteceu a\nBLAINE, o LÍDER\vDO GINÁSIO?",
  ["5f:4da7"] = "Meu sonho, é\nser um LÍDER DE\vGINÁSIO.",
  ["5f:4e44"] = "Oi! Uau, estou\ncontente por te\vver.\fVocê é a primeira\nvisita em muito\vtempo.\fEstou super-feliz.\fDeixe-me lhe dar\num presente.",
  ["5f:4ec4"] = "Isto é uma PEPITA.\fNão posso te dar\npepitas do saber,\vvocê terá que\vfazê-las.",
  ["5f:4f34"] = "Você é {PLAYER}?\fTrabalho como\nAJUDANTE DO\vCARVALHO.\fNão sei como estou\naqui.\fO LABORATÓRIO DO\nCARVALHO fica na\vCIDADE PALLET.",
  ["5f:5008"] = "Só os treinadores\nque provaram seus\vvalores podem\vpassar.",
  ["5f:503e"] = "Você não tem todas\nas INSÍGNIAS DOS\vGINÁSIOS DE JOHTO.\fMe desculpe, eu\nnão posso deixá-lo\vprosseguir.",
  ["5f:5093"] = "Oh! As oito\nINSÍGNIAS DE\vJOHTO!\fPor favor, siga\nem frente, senhor!",
  ["5f:50d0"] = "Esse caminho vai\nao MONTE PRATEADO.\fVocê verá POKéMONS\nfortes e\vassustadores lá.",
  ["5f:5116"] = "Saindo da LIGA\nPOKéMON?\fA ELITE QUATRO\né assustadora de\vtão forte que é,\ve eles estão\vpreparados para\vbatalhar contra\vvocê!",
  ["60:43f7"] = "ELM: {PLAYER}!\nAí está você!\fPreciso lhe pedir\num favor.\fTenho um conhecido\nchamado MR.\vPOKéMON.\fEle vive achando\ncoisas estranhas\fe se gabando das\ndescobertas.\fEnfim, recebi um\ne-mail dele agora\fdizendo que desta\nvez é de verdade.\fÉ intrigante, mas\nestamos ocupados\fcom nossa pesquisa\nde POKéMON.\fVocê poderia ir\nver isso por nós?\fVou lhe dar um\nPOKéMON de\vparceiro.\fSão todos POKéMON\nraros que acabamos\vde encontrar.\fEscolha um deles!",
  ["60:4590"] = "Se um POKéMON\nselvagem aparecer,\vdeixe o seu lutar",
  ["60:45c2"] = "ELM: Espere! Aonde\nvocê vai?",
  ["60:45e3"] = "ELM: Vai levar o\nCYNDAQUIL, o\vPOKéMON de fogo?",
  ["60:460e"] = "ELM: Você quer o\nTOTODILE, o\vPOKéMON de água?",
  ["60:463a"] = "ELM: Então gosta\nda CHIKORITA, a\vPOKéMON planta?",
  ["60:4668"] = "ELM: Pense bem\ncom calma.\fSeu parceiro é\nimportante.",
  ["60:46a2"] = "ELM: Acho esse\num ótimo\vPOKéMON também!",
  ["60:46c8"] = "{PLAYER} recebeu\n{STRBUF}!",
  ["60:46db"] = "MR.POKéMON mora\nperto de\vCHERRYGROVE.\fA próxima cidade.\nÉ quase direto\vdaqui.",
  ["60:472f"] = "Se seu POKéMON se\nmachucar, cure\fele nesta\nmáquina.",
  ["60:476c"] = "Ah, aqui está meu\ntelefone.\fMe ligue se algo\nacontecer.",
  ["60:47a9"] = "{PLAYER} anotou o\ntelefone do ELM.",
  ["60:47c3"] = "MR.POKéMON vai a\ntoda parte e acha\vraridades.\fPena que sejam só\nraras e não muito\vúteis…\f{PLAYER}, conto\ncom você!",
  ["60:4835"] = "Contém um POKéMON\ncapturado pelo\vPROF.ELM.",
  ["60:485d"] = "Será que isto faz\no quê?",
  ["60:4877"] = "Curar POKéMON?",
  ["60:4883"] = "ELM: {PLAYER}, isto\né terrível…\fAh, sim, qual foi\na descoberta do\vMR.POKéMON?",
  ["60:48c8"] = "{PLAYER} entregou\no OVO MISTERIOSO\vao PROF.ELM.",
  ["60:48ef"] = "ELM: Isto?",
  ["60:48fb"] = "Mas… Será um OVO\nde POKéMON?\fSe for, é um\ngrande achado!",
  ["60:4936"] = "ELM: O quê?!?\fO PROF.OAK lhe deu\numa POKéDEX?\f{PLAYER}, é verdade\nmesmo? I-isso é\vincrível!\fEle é ótimo em ver\no potencial das\vpessoas como\vtreinadores.\fUau, {PLAYER}. Você\npode ter o que é\fpreciso para virar\nCAMPEÃO.\fParece que você se\ndá muito bem\vcom POKéMON.\fVocê devia encarar\no desafio do\vGINÁSIO POKéMON.\fO GINÁSIO mais\nperto fica em\vVIOLET CITY.",
  ["60:4a85"] = "…{PLAYER}. O\ncaminho até o\fcampeonato vai ser\nlongo.\fAntes de partir,\nnão esqueça de\vfalar com sua mãe",
  ["60:4af2"] = "ELM: Não desista!\nEu ligo se souber\fde algo sobre\naquele OVO!",
  ["60:4b33"] = "ELM: {PLAYER}?\nVocê não achou meu\vassistente?\fEle devia lhe\nentregar o OVO\fno CENTRO POKéMON\nde VIOLET CITY.\fVocê deve ter\nperdido ele. Tente\vencontrá-lo lá.",
  ["60:4bd1"] = "ELM: Ei, aquele\nOVO mudou algo?",
  ["60:4bf6"] = "{PLAYER}? Pensei\nque o OVO chocou.\fCadê o\nPOKéMON?",
  ["60:4c28"] = "ELM: {PLAYER}, você\nestá ótimo!",
  ["60:4c41"] = "O quê?\nAquele POKéMON!?!",
  ["60:4c55"] = "O OVO chocou!\nEntão POKéMON\vnascem de OVOS…\fNão, talvez não\ntodos eles.\fUau, ainda há\nmuita pesquisa\vpela frente.",
  ["60:4cd2"] = "Obrigado, {PLAYER}!\nVocê nos ajuda a\fdesvendar os\nmistérios POKéMON\fQuero que fique\ncom isto em sinal\vda nossa gratidão",
  ["60:4d43"] = "Isso é uma\nEVERSTONE.\fCertas espécies de\nPOKéMON evoluem\fao chegar a certos\nníveis.\fUm POKéMON segu-\nrando a EVERSTONE\vnão evolui.\fDê a um POKéMON\nque você não quer\vque evolua.",
  ["60:4ded"] = "ELM: {PLAYER}, eu\nligo se algo\vacontecer.",
  ["60:4e1b"] = "…ai… Aquele\nPOKéMON roubado.\fFico pensando como\nele está.\fDizem que POKéMON\ncriado por gente\fruim fica ruim\ntambém.",
  ["60:4e86"] = "ELM: Oi, {PLAYER}!\nGraças a você,\fminha pesquisa vai\nmuito bem!\fLeve isto como\nsinal da minha\vgratidão.",
  ["60:4ee7"] = "A MASTER BALL é a\nmelhor de todas!\fÉ a BALL suprema!\nCaptura qualquer\fPOKéMON sem\nfalhar nunca.\fSó é dada a\npesquisadores\vPOKéMON de renome\fAcho que você faz\nmelhor uso dela\fdo que eu,\n{PLAYER}!",
  ["60:4fa4"] = "ELM: {PLAYER}!\nAí está você!\fLiguei porque\ntenho algo para\vvocê.\fViu? É um\nS.S.TICKET.\fAgora pode pegar\nPOKéMON em KANTO.",
  ["60:5020"] = "O navio parte de\nOLIVINE CITY.\fMas isso você já\nsabia, {PLAYER}.\fAfinal, você foi\na toda parte\vcom seus POKéMON.\fMande lembranças\nao PROF.OAK!",
  ["60:50e9"] = "{PLAYER}, quero que\nfique com isto\vpara a sua missão",
  ["60:5116"] = "Somos só nós dois,\nentão vivemos\vsempre ocupados.",
  ["60:5146"] = "Houve um barulho\nalto lá fora…\fQuando fomos ver,\nroubaram um\vPOKéMON daqui.\fÉ inacreditável\nque alguém faça\visso!\f…ai… Aquele\nPOKéMON roubado.\fFico pensando como\nele está.\fDizem que POKéMON\ncriado por gente\fruim fica ruim\ntambém.",
  ["60:5229"] = "{PLAYER}!\fUse isto na sua\njornada POKéDEX!",
  ["60:524b"] = "Para completar a\nPOKéDEX, você tem\vque pegar POKéMON\fJogue POKé BALLS\nnos POKéMON\vselvagens.",
  ["60:52a1"] = "Soube que roubaram\num POKéMON aqui…\fEu estava colhendo\ninformações com o\vPROF.ELM.\fPelo visto era um\njovem de cabelo\vlongo e vermelho…\fO quê?\fVocê lutou com um\ntreinador assim?\fPor acaso soube\no nome dele?",
  ["60:5371"] = "Certo! Então\n{RIVAL} é o nome.\fObrigado por\najudar na busca!",
  ["60:53ae"] = "Janela aberta.\fUma brisa gostosa\nentra por ela.",
  ["60:53e2"] = "Ele entrou\npor aqui!",
  ["60:53fd"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 1:\fAperte START para\nabrir o MENU.",
  ["60:543b"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 2:\fRegistre a viagem\ncom SAVE!",
  ["60:5477"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 3:\fAbra a BOLSA e\naperte SELECT para\vmover itens.",
  ["60:54c6"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 4:\fVeja os movimentos\ndo POKéMON. Use\fo botão A para\ntrocar de lugar.",
  ["60:5521"] = "A embalagem do\nlanche que o PROF.\vELM comeu está aí",
  ["60:5719"] = "Ah, {PLAYER}! Nosso\nvizinho, o PROF.\fELM, estava\nprocurando você.\fDisse que queria\nque você fizesse\valgo para ele.\fAh! Quase esqueci!\nSua POKéMON GEAR\fvoltou do\nconserto.\fAqui está!",
  ["60:57d2"] = "POKéMON GEAR, ou\nsó POKéGEAR.\fÉ essencial se\nvocê quer ser um\vbom treinador.\fAh, falta ajustar\no dia da semana.\fNão pode esquecer\ndisso!",
  ["60:5857"] = "Estamos no horário\nde verão agora?",
  ["60:5878"] = "Volte para casa\npara ajustar o\frelógio no horário\nde verão.\fA propósito, você\nsabe usar o\vTELEFONE?",
  ["60:58e0"] = "Não é só ligar a\nPOKéGEAR e\fescolher o ícone\ndo TELEFONE?",
  ["60:591c"] = "Vou ler as\ninstruções.\fLigue a POKéGEAR e\nescolha o ícone\vdo TELEFONE.",
  ["60:5965"] = "Os números ficam\nsalvos na memória\fÉ só escolher o\nnome para ligar.\fQue prático,\nnão é mesmo?",
  ["60:59ca"] = "O PROF.ELM está\nesperando você.\fVá logo, querido!",
  ["60:59fa"] = "E aí, qual era\na missão do ELM?\f…\fIsso parece\nmesmo um desafio.\fMas orgulhe-se de\nque as pessoas\vcontam com você.",
  ["60:5a6c"] = "{PLAYER}, vá!\fEstou com você\naté o fim!",
  ["60:5a92"] = "Prato da mamãe!\fHAMBÚRGUER VULCÃO\nDE CINNABAR!",
  ["60:5abc"] = "A pia está\nimpecável. A mamãe\vgosta dela limpa.",
  ["60:5ae9"] = "Vamos ver o que há\nna geladeira…\fFRESH WATER e uma\nboa LEMONADE!",
  ["60:5b28"] = "Passa um filme na\nTV: estrelas no\fcéu e dois\nmeninos no trem…\fÉ melhor eu ir\nandando também!",
  ["60:5c5c"] = "POKéMON TALK DO\nPROF.OAK! Não\vperca a próxima!",
  ["60:5c8d"] = "CANAL POKéMON!",
  ["60:5c9c"] = "Aqui é a DJ MARY,\nsua parceira!",
  ["60:5cbc"] = "POKéMON!\nCANAL POKéMON…",
  ["60:5d64"] = "PIKACHU é um\nPOKéMON evoluído.\fFoi o PROFESSOR\nELM quem\vdescobriu isto!\fEle é famoso\npelas pesquisas\vsobre a evolução\vPOKéMON. \f…hum… \fEu poderia ser\numa pesquisadora\vtambém…",
  ["60:5e09"] = "SHOW DO CARVALHO!  \fPor favor acesse\noutra hora!",
  ["60:5e3a"] = "Canal POKéMON!",
  ["60:5e49"] = "Esta é a DJ Mary\narrasando!",
  ["60:5e69"] = "POKéMON!\nCANAL POKéMON!…",
  ["60:5eb8"] = "Oi, {PLAYER}! Meu\nmarido vive tão\focupado, e espero\nque ele fique bem\fQuando mergulha na\npesquisa POKéMON,\fele até esquece\nde comer.",
  ["60:5f2c"] = "Quando eu crescer,\nvou ajudar o meu\vpai!\fVou ser um grande\nprofessor\vPOKéMON!",
  ["60:5fdc"] = "POKéMON. De onde\neles vêm?\fPara onde eles\nvão?\fPor que ninguém\nnunca viu um\vPOKéMON nascer?\fQuero saber! Vou\ndedicar a vida\fao estudo dos\nPOKéMON!\f…\fFaz parte dos\nartigos de\vpesquisa do ELM.",
  ["60:610b"] = "Seus POKéMONS\nparecem bem\vcansados.\fVocê deve\ndescansá-los.",
  ["60:6149"] = "Ah! Os seus\nPOKéMONS parecem\vótimos!\fContinue assim!",
  ["60:61b7"] = "Há algo escrito\naqui? Quer ler?",
  ["60:61e0"] = "Aos meus irmãos\ne irmãs:\fNós temos\norgulho em servir\vos treinadores\vPOKéMON.\fQuando eles\nfalarem com vocês,\vdê algo útil a\veles.\fCom amor, MÔNICA.\fContinuar lendo?",
  ["60:6277"] = "Segunda, MÔNICA\nROTA 40.\fTerça, TUSCANY\nROTA 29.\fQuarta, WESLEY\nLAGO DA RAIVA.\fQuinta, ARTHUR,\nROTA 36.\fSexta, FRIEDA,\nROTA 32\fSábado, SANTOS,\nVILA BLACKTHORN\fDomingo, SUNNY,\nROTA 37.",
  ["60:6384"] = "Onde você está\nindo com seus\vPOKéMONS?\fLIGA POKéMON?\fOs seus POKéMONS\nsão bem leais para\vvocê vencer?\fDeixe-me ver…",
  ["60:63e9"] = "Ah! Seu POKéMON\nconfia muito em\vvocê.\fÉ ótimo ver um\nbom treinador.\fEi. Um presente\npara a sua\vjornada.",
  ["60:644d"] = "O TM 37 é a\nTEMPESTADE.\fÉ um golpe que\ncausa em danos em\vambos lutadores.\fÉ só para\ntreinadores\vavançados.\fUse isso se\nquiser. Boa sorte!",
  ["60:64dd"] = "Se ele não confiar\nmais em você, ele\vpoderia se tornar\vviolento.\fA confiança é o\nlaço que une\vtreinadores aos\vPOKéMONS.",
  ["60:657f"] = "Você não pode\nsubir margens.\fMas pode saltá-las\npara pegar um\vatalho!",
  ["60:65cb"] = "Diferentes\nespécies de\vPOKéMON aparecem\vaqui.\fSe quiser pegar\ntodos, você deve\vprocurar em todo\vlugar.",
  ["61:400d"] = "Olá! O REI CARATÊ,\no mestre do\vGINÁSIO DE LUTA,\vestá em uma\vcarverna em JOHTO\vpara treinar.",
  ["61:4061"] = "Tudo o que vai ao\nredor, volta ao\vredor!",
  ["61:4081"] = "Há inimigos em\ntodos os lados!",
  ["61:4180"] = "SABRINA: Eu sabia\nque você viria…\fHá três anos\natrás, eu previ\vo momento que\vchegaria.\fVocê quer minha\nINSÍGNIA.\fNão gosto muito de\nbatalhar, mas é\vmeu dever de LÍDER\vconceder INSÍGNIAS\va quem provar a si\vmesmo o seu valor.\fComo você quer, eu\nte mostrarei meus\vpoderes psíquicos!",
  ["61:4295"] = "SABRINA: Seu\npoder…   \fUltrapassa muito\no que eu previ…\fTalvez seja\nimpossível prever\vo que o futuro\voferecerá…\fCerto, você\nvenceu, você\vmerece a INSÍGNIA\vDA LAMA.",
  ["61:4336"] = "{PLAYER} foi\npresenteado com\vuma INSÍGNIA DA\vLAMA DO GINÁSIO DA\vCIDADE SAFFRON.",
  ["61:4346"] = "nou\nsua alma mais\vpoderosa, não\vapenas suas\vhabilidades.",
  ["61:434e"] = "SABRINA: A\nINSÍGNIA DA\vLAMA extrai\vseus poderes\vadormecidos…\fPorém, eu falhei\nna precisão ao\vprever os seus\vpoderes, esta é a\vverdade.\fVocê se tornará\num celebrado e\vidolatrado CAMPEÃO\vPOKéMON.",
  ["61:440d"] = "SABRINA: Seu amor\npelos seus\vPOKéMONS oprimiram\vos meus poderes\vpsíquicos…\fO poder do amor,\neu acho, é também\vum tipo de poder\vpsíquico…",
  ["61:46a2"] = "Você, CAMPEÃO em\nprogresso!\fUm treinador\nhabilidoso como\vvocê não deve ser\vavisado de\vcomo batalhar\vcom POKéMONS\vpsíquicos, certo?\fEu espero boas\ncoisas de você!\fBoa sorte!",
  ["61:4741"] = "Essa foi outra\nbatalha incrível!",
  ["61:486d"] = "Existe uma grande\nTORRE DE RÁDIO em\vLAVANDA.",
  ["61:4894"] = "Eu quero me tornar\nmais forte, mas eu\vnão sou muito boa\vainda…\fVocê poderia me\nmostrar alguma\vcoisa?",
  ["61:493b"] = "Há uma grande\nUSINA DE ENERGIA\vao norte da\vCIDADE LAVANDA.",
  ["61:496e"] = "Eu tinha acabado\nde atravessar o\vT→NEL DE PEDRA.\fHavia uma confusão\nna USINA DE\vENERGIA.",
  ["61:49c9"] = "As cavernas\nse destroem\vfacilmente.\fMuitas cavernas\ndesapareceram no\vpassado, como a\vque está fora de\vCERULEANA.\fIsso é um\nconhecimento comum\vdos ANDARILHOS\vexperientes.",
  ["61:4a60"] = "O ESCRITÓRIO\nPRINCIPAL DA\vCORPORAÇÃO SILPH e\va ESTAÇÃO DO TRÊM\vMAGNETO, são os\vlugares para se\vvisitar em\vSAFFRON.",
  ["61:4b33"] = "…\f…\f…\f…Eu tenho isso!\fVocê quer isso!",
  ["61:4b56"] = "O TM29 contém o\nPSÍQUICO.\fEle pode reduzir\nas habilidades\vespeciais do alvo.",
  ["61:4c45"] = "Desculpe-me, mas\no TRÊM MAGNETO não\vestá funcionando\vainda.",
  ["61:4c79"] = "Em breve, nós\npartiremos para\vGOLDENROD.\fVocê deseja\nembarcar?",
  ["61:4cb3"] = "Eu posso conferir\no seu PASSE?\fCerto, é por aqui\nsenhor.",
  ["61:4cef"] = "Desculpe-me, mas\nvocê não tem o\vPASSE do TRÊM\vMAGNETO.",
  ["61:4d11"] = "Nós esperamos\nvê-lo novamente.",
  ["61:4d2c"] = "Nós chegamos em\nSAFFRON.\fNós esperamos\nvê-lo novamente.",
  ["61:4d63"] = "O TRÊM MAGNETO\né um veículo\vferroviário super\vmoderno que usa\veletricidade e\vimãs para alcançar\vuma velocidade\vincrível.\fPorém, se\nnão tiver\veletricidade…",
  ["61:4dfa"] = "Uau…\fQuantas vezes\neu já devo ter\vviajado entre os\vcontinentes KANTO\ve JOHTO?",
  ["61:4e44"] = "Antes da ESTAÇÃO\ndo TRÊM MAGNETO\vfor construída,\vexistia uma casa\vaqui.\fUma garotinha\nchamada DUPLICA\vmorava aqui.",
  ["61:4eb9"] = "Olá. Você tem um\nPASSE de TRÊM?\vEu tenho um. Todas\vas pessoas em\vSAFFRON que usam\vo TRÊM MAGNETO\vpossuem PASSES.",
  ["61:4f9c"] = "Bem-vindo.\fEsse é o PRÉDIO\nPRINCIPAL DA\vCORPOPAÇÃO SILPH.",
  ["61:4fcf"] = "Apenas os\nempregados podem\vir ao andar de\vcima.    \fMas como você veio\nde um longo\vcaminho, eu vou te\vdar essa pequena\ve nítida\vlembrança.",
  ["61:5041"] = "É o produto mais\nrecente da\vCORPORAÇÃO SILPH.\fEle não se\nencontra a venda\vainda.",
  ["61:50cd"] = "Minha filha gosta\nde imitar pessoas.\fEssa técnica a fez\nficar conhecida\vpor aqui como\vDUPLICA.",
  ["61:512e"] = "Minha filha é tão\negoísta…\fEla possui muito\npoucos amigos.",
  ["61:516c"] = "Ela recentemente\nperdeu uma BONECA\vque um garoto lhe\vdeu a três anos\vatrás.\fDesde lá, ele vem\nmelhorado suas\vmímicas…",
  ["61:52f1"] = "{PLAYER}: Oi! Você\ngosta de POKéMONS?\f{PLAYER}: Uh, não,\neu só te\vperguntei.\f{PLAYER}, não é?\nVocê é estranho!",
  ["61:533f"] = "DUPLICA: Hmm?\nParar de imitar?\vMas é o que eu\vadoro fazer!",
  ["61:5400"] = " acha que a\nperdeu quando foi\và CIDADE\vVERMILION?",
  ["61:542d"] = "DUPLICA: Como\ndisse?\fNão devo decidir\no que você deve\vfazer?\fMas eu\nestou realmente\vpreocupada.\fSerá que alguém\npoderia ter a\vgentileza de\vachá-la para mim?",
  ["61:5496"] = "Ei! Essa é a minha\nBONECA CLEFARY!\fEstá vendo\na rasgadura\vcosturada na perna\vdireita?\fEssa é a prova\nque a BONECA é\vminha!",
  ["61:54f9"] = "Certo. Aqui está\no PASSE para o\vTRÊM MAGNETO como\veu prometi!",
  ["61:552b"] = "DUPLICA: Esse é\no PASSE para o\vTRÊM MAGNETO.\fO rapaz da empresa\nde trens me\vdeu quando eles\vdemoliram nossa\vvelha casa para\vconstruir a\vESTAÇÃO.",
  ["61:55af"] = "{PLAYER}: Olá!\nMuito obrigado\vpelo PASSE do TRÊM\vMAGNETO!\f{PLAYER}: Como\ndisse?\f{PLAYER}: É tão\ndivertido assim\vimitar todos os\vmeus movimentos?",
  ["61:560c"] = "DUPLICA: Está\ncerto!\fÉ arrepiante!",
  ["61:5640"] = "ESPELHO, ESPELHO\nMEU, QUEM É O MAIS\vAMÁVEL DE TODOS?",
  ["61:567b"] = "Isso é um POKéMON\nraro!\fHã? É apenas um\nboneco…",
  ["61:5702"] = "Muitas cidades\ndo continente\vJOHTO possuem\vlongas histórias.\fEu amaria conhecer\numa delas!",
  ["61:5766"] = "Você veio do\ncontinente JOHTO,\vnão é?\fO que está\nachando de KANTO?\fÉ um continente\nmaravilhoso,\vconcorda comigo?",
  ["61:57ff"] = "Eeyaaaah!\fEu sinto uma\nsombra sinistra\vte encobrindo.\fLeve isto para se\nproteger!",
  ["61:5851"] = "Você estava num\nperigo mortal,\vmas agora está\vprotegido.",
  ["61:5888"] = "Minha avó está\neliminando o que\vela acredita ser\vmaus espíritos.\fPerdão por ela\nassustar você.",
  ["62:402c"] = "Acabaram as\nPOKé BALLS!\fQuando será que\nchegam mais?",
  ["62:406b"] = "Tem POKé BALLS em\nestoque! Agora\vposso pegar!",
  ["62:4098"] = "Quando eu andava\nno mato, um\fPOKéMON inseto\nenvenenou o meu!\fEu segui andando,\nmas aí o meu\vPOKéMON desmaiou.\fÉ bom andar com um\nANTIDOTE.",
  ["62:4182"] = "É ótimo. Dá para\nguardar quantos\fPOKéMON quiser, e\ntudo de graça.",
  ["62:41c0"] = "Aquele PC é livre\npara qualquer\vtreinador usar.",
  ["62:41e9"] = "O CENTRO DE\nCOMUNICAÇÃO lá em\vcima é novinho.\fMas ainda estão\nterminando ele.",
  ["62:423e"] = "O CENTRO DE\nCOMUNICAÇÃO lá em\vcima é novinho.\fJá troquei POKéMON\nlá!",
  ["62:42e2"] = "Você está tentando\nse tornar um\vgrande mestre\vPOKéMON?\fPara isto\nacontecer, você\vdeve ganhar as\vINSÍGNIAS DOS\vGINÁSIOS DE JOHTO.",
  ["62:435d"] = "Quando eu crescer,\nvou ser LÍDER DE\vGINÁSIO.\fEu farei meu\nPOKéMON batalhar\vcom o do meu\vamigo e torná-lo\vforte!",
  ["62:4405"] = "Quando eu era\nnovo, fui um\vótimo treinador\vPOKéMON!\fAqui vai uma\nsuper dica:\vCapture muitos\vPOKéMONS!\fTrate-os com\ngentileza!",
  ["62:44bb"] = "Os POKéMONS ganham\nexperiência\vpara evoluirem e\vficarem fortes!",
  ["62:44f4"] = "POKéMONS evoluem!\nEstou chocada,\vpois vi um\vevoluir",
  ["62:457a"] = "Você sabe,\nPOKéMONS comem\vGRÃOS. \fBem, meu POKéMON\nficou saudável\vpois comeu um\vGRÃO. \fTome! Pode levar\num GRÃO!",
  ["62:45e4"] = "Cheque as árvores.\nElas sempre deixam\vcair GRÃOS.",
  ["62:4755"] = "Olá! Você deve\nser o famoso\v{PLAYER}.\fO PROFESSOR ELM\nme disse que você\vviria.",
  ["62:4797"] = "É isto o que eu\nquero que o\vPROFESSOR ELM\vexamine para mim.",
  ["62:47c1"] = "{PLAYER} recebeu\nOVO ESTRANHO.",
  ["62:47da"] = "Eu conheço um\ncasal que comanda\vo CRIATÓRIO\vPOKéMON.\fForam eles que me\nderam este OVO.\fEu fiquei\nimpressionado,\ventão eu mandei\vuma carta para o\vPROFESSOR ELM.\fEle é um perito\nna evolução\vPOKéMON!",
  ["62:4881"] = "Até o PROFESSOR\nCARVALHO reconhece\visto.",
  ["62:48a6"] = "Se o que eu acho\nestiver certo, o\vPROFESSOR ELM\vconfirmará.",
  ["62:48dc"] = "Você está voltando\nao LABORATÓRIO DO\vPROFESSOR ELM?\fEi! Seu POKéMON\ndeve descansar um\vpouco.",
  ["62:4923"] = "Eu dependo de\nvocê!",
  ["62:4939"] = "A vida é\ndeliciosa!\fHá sempre novas\ndescobertas à\vserem feitas!",
  ["62:4974"] = "CARVALHO: Ah! Você\né {PLAYER}!\fEu sou CARVALHO.\nUm pesquisador\vPOKéMON.\fEu estava\nvisitando meu\vamigo SENHOR\vPOKéMON.  \fOuvi dizer\nque você tinha um\vrecado do\vPROFESSOR ELM,\ventão eu esperei\vaqui.\fOh! O que é isto?\nUm POKéMON raro!\fDeixe-me ver…\fHum, entendi!\fEu sei porque o\nPROFESSOR ELM te\vdeu um POKéMON\vpara esta missão.\fPara pesquisadores\ncomo o PROFESSOR\vELM e eu,\vos POKéMONS\vsão nossos\vamigos.\fEle percebeu que\nvocê trataria seu\vPOKéMON com amor e\vcarinho.\f…Ah!\fVocê parece ser\nconfiante.\fComo você gostaria\nde me ajudar?\fViu? Essa é a mais\nnova versão da\vPOKéDEX.\fEla registra\nautomaticamente\vas informações dos\vPOKéMONS que você\vviu ou capturou.\fÉ uma enciclopédia\nde tecnologia\valta!",
  ["62:4bbb"] = "{PLAYER} recebeu\nPOKéDEX.",
  ["62:4bcd"] = "Saia para pegar\ntodos os POKéMONS\ve completar a\vPOKéDEX.\fEu demorei muito\naqui.\fEu devo ir à\nGOLDENROD para o\vmeu usual show de\vrádio.\f{PLAYER}, eu estou\ncontando com você!",
  ["62:4c65"] = "Hã? É uma ESCAMA!\nO que é isso? Um\nGYARADOS vermelho?\fIsso é raro! Eu,\neu quero isso…\f{PLAYER}, não se\nimportaria de\vfazer uma troca?\fEu posso oferecer\neste DIVIDE\vEXPERIÊNCIA que o\vPROFESSOR CARVALHO\vme deu.",
  ["62:4cfc"] = "Isso é muito\ntriste.\fIsso parece ser\nmuito raro.",
  ["62:4d32"] = "Está empacotado\ncom revistas\vestrangeiras.\fNem dá para ler\nseus títulos…",
  ["62:4d73"] = "É um grande\ncomputador. Hum.\vEle está quebrado.",
  ["62:4d9b"] = "Uma grande pilha\nde moedas\vestranhas!\fTalvez elas sejam\nde outro país…",
  ["62:4e29"] = "Olá rapaz!\nVocê já visitou a\vTORRE BROTINHO?",
  ["62:4e4f"] = "Eu vim de longe.\nÉ melhor eu tele-\vfonar para minha\vcasa!",
}
